(window.JCPA_DATA=window.JCPA_DATA||{})["insurance"]={"id":"insurance","name":"قانون تنظيم أعمال التأمين","full":"قانون تنظيم أعمال التأمين رقم (12) لسنة 2021","icon":"☂️","articles":[{"n":"1","chapter":"","notes":[],"source":"يسمى هذا القانون (قانون تنظيم أعمال التأمين لسنة ٢٠٢١) ويعمل به بعد مرور ثلاثين يوماً على تاريخ نشره في الجريدة الرسمية.","title":"اسم القانون وسريانه","memo":"⭐ يعمل بالقانون بعد مرور ثلاثين يوماً على تاريخ نشره في الجريدة الرسمية.","qs":[{"q":"متى يعمل بقانون تنظيم أعمال التأمين لسنة ٢٠٢١؟","o":["بعد مرور ثلاثين يوماً على تاريخ نشره في الجريدة الرسمية","من تاريخ نشره في الجريدة الرسمية","بعد مرور ستين يوماً على تاريخ نشره في الجريدة الرسمية","بعد مرور تسعين يوماً على تاريخ نشره في الجريدة الرسمية"],"a":0}]},{"n":"2","chapter":"","notes":[],"source":"يكون للكلمات والعبارات التالية حيثما وردت في هذا القانون المعاني المخصصة لها أدناه ما لم تدل القرينة على غير ذلك:-\nالبنك المركزي : البنك المركزي الأردني.\nالمجلس : مجلس إدارة البنك المركزي.\nالمحافظ : محافظ البنك المركزي.\nعقد التأمين : اتفاق تلتزم بمقتضاه شركة التأمين أن تؤدي إلى المؤمن له أو إلى المستفيد عوضاً مالياً أو أي منفعة أخرى عند تحقق الخطر المؤمن منه أو حدوث الواقعة المحددة في العقد مقابل مبلغ محدد أو أقساط يؤديها المؤمن له إلى شركة التأمين.\nالمؤمن له : الشخص الذي يتعاقد باسمه مع شركة التأمين لمصلحته أو لمصلحة المؤمن عليه أو لمصلحة المستفيد.\nالمستفيد : الشخص المحدد في عقد التأمين والذي تؤول إليه الحقوق الواردة فيه.\nشركة التأمين : أي شركة أردنية أو فرع لشركة تأمين أجنبية حاصلة على ترخيص لممارسة أعمال التأمين في المملكة بموجب أحكام هذا القانون.\nشركة اعادة التأمين : أي شركة أردنية أو فرع لشركة أجنبية حاصلة على ترخيص لممارسة إعادة التأمين في المملكة بموجب أحكام هذا القانون.\nالتأمين التكافلي : أعمال التأمين التي تتفق مع أحكام الشريعة الإسلامية ومبادئها.\nالموظف الرئيسي : مدير عام شركة التأمين أو مديرها المفوض أو نائب أو مساعد أي منهما أو أي مدير دائرة أو مدير التدقيق الداخلي أو أي موظف في شركة التأمين له سلطة تنفيذية موازية لسلطات أي منهم.\nالمدير المفوض : الشخص المقيم في المملكة المعين من قبل شركة تأمين أجنبية لإدارة فرعها المرخص له بالعمل في المملكة.\nمقدم الخدمة التأمينية : أي شخص حاصل على ترخيص لممارسة أي من أعمال الخدمات التأمينية وفق أحكام هذا القانون.\nالمخصصات الفنية : المخصصات التي يجب على شركة التأمين اقتطاعها والاحتفاظ بها وفق أحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه لتغطية الالتزامات المالية المترتبة عليها تجاه المؤمن لهم والمستفيدين.\nالشركة المقيدة : شركة تأمين تؤسسها جهة أو أكثر بهدف تأمين الأخطار التي تواجهها أو تواجه أي جهة أخرى .\nالسيطرة : القدرة المباشرة أو غير المباشرة على ممارسة تأثير فعال على أعمال شخص أو قراراته.\nالمصلحة المؤثرة : السيطرة على ما لا يقل عن (١٠%) من رأسمال شخص اعتباري.\nالمساهم الرئيسي : أي شخص له سيطرة على ما لا يقل عن (١٠%) من رأسمال شركة التأمين.\nالشركة التابعة : الشركة التي يملك شخص أو مجموعة أشخاص، تجمعهم مصلحة واحدة ، ما لا يقل عن (٥٠%) من رأسمالها أو يملك هذا الشخص أو هؤلاء الأشخاص المصلحة المؤثرة التي تسمح بالسيطرة على إدارتها أو سياستها العامة.\nذوو الصلة : شخصان أو أكثر يسيطر أحدهما على الآخر أو يتملك أحدهما ما لا يقل عن (٤٠%) من رأسمال الشخص الآخر أو تربطهما أي علاقة تؤثر بصورة جوهرية على استقلالية قرارات كل منهما وموضوعيته ، ولمقاصد هذا القانون يعتبر ذوو الصلة شخصاً واحداً.\nالاكتواري : الشخص المرخص من البنك المركزي للقيام بتقدير قيمة عقود التأمين وتسعيرها وتقييم المخصصات الفنية و الحسابات كافة المتعلقة بتلك العقود.\nوكيل التأمين : الشخص المعتمد من شركة التأمين لممارسة أعمال التأمين نيابة عنها أو عن أحد فروعها والمرخص له من البنك المركزي للقيام بهذه الأعمال.\nوسيط التأمين : الشخص المرخص من البنك المركزي لممارسة أعمال وساطة التأمين بين شركة التأمين والمؤمن له.\nوسيط إعادة التأمين : الشخص المرخص من البنك المركزي لممارسة أعمال وساطة التأمين بين شركة التأمين وشركة إعادة التأمين.","title":"التعريفات","memo":"⭐ المجلس = مجلس إدارة البنك المركزي؛ المحافظ = محافظ البنك المركزي.\n⭐ المصلحة المؤثرة والمساهم الرئيسي: السيطرة على ما لا يقل عن (١٠%) من رأس المال.\n⭐ الشركة التابعة: ملكية ما لا يقل عن (٥٠%) من رأسمالها؛ ذوو الصلة: تملك ما لا يقل عن (٤٠%) ويعتبرون شخصاً واحداً.\n⭐ المدير المفوض: مقيم في المملكة تعينه شركة تأمين أجنبية لإدارة فرعها؛ التأمين التكافلي: المتفق مع أحكام الشريعة الإسلامية.","qs":[{"q":"يقصد بـ(المجلس) في قانون تنظيم أعمال التأمين:","o":["مجلس إدارة البنك المركزي","مجلس إدارة شركة التأمين","مجلس الوزراء","مجلس إدارة الاتحاد الأردني لشركات التأمين"],"a":0},{"q":"المساهم الرئيسي هو أي شخص له سيطرة على ما لا يقل عن ... من رأسمال شركة التأمين:","o":["(١٠%)","(٥%)","(٤٠%)","(٥٠%)"],"a":0},{"q":"يعتبر شخصان من (ذوي الصلة) إذا تملك أحدهما ما لا يقل عن ... من رأسمال الآخر:","o":["(٤٠%)","(١٠%)","(٢٥%)","(٥٠%)"],"a":0},{"q":"تملك شركة (س) (٥٠%) من رأسمال شركة (ص)، فإن شركة (ص) تعتبر وفق التعريفات:","o":["شركة تابعة","شركة مقيدة","شركة معفاة","شركة إعادة تأمين"],"a":0}]},{"n":"3","chapter":"","notes":[],"source":"تسري أحكام هذا القانون على شركات التأمين وشركات إعادة التأمين ومقدمي الخدمات التأمينية وجميع الجهات والوسائل المتصلة لتنظيم قطاع التأمين والرقابة عليه بما يضمن حقوق المؤمن لهم والمستفيدين وسلامة المراكز المالية لشركات التأمين وشركات إعادة التأمين.","title":"نطاق سريان القانون","memo":"⭐ يسري على شركات التأمين وإعادة التأمين ومقدمي الخدمات التأمينية وجميع الجهات والوسائل المتصلة.\n⭐ الغاية: ضمان حقوق المؤمن لهم والمستفيدين وسلامة المراكز المالية للشركات.","qs":[{"q":"أي مما يلي لا يرد ضمن الجهات التي تسري عليها أحكام قانون تنظيم أعمال التأمين صراحة؟","o":["البنوك التجارية","شركات إعادة التأمين","مقدمو الخدمات التأمينية","شركات التأمين"],"a":0},{"q":"من غايات تنظيم قطاع التأمين والرقابة عليه وفق القانون:","o":["ضمان حقوق المؤمن لهم والمستفيدين وسلامة المراكز المالية لشركات التأمين","تحديد أسعار أقساط التأمين لجميع الشركات","حماية الشركات من المنافسة الأجنبية","زيادة إيرادات الخزينة من رسوم التأمين"],"a":0}]},{"n":"4","chapter":"","notes":[],"source":"تحدد إجازات التأمين على الحياة والتأمينات العامة وفروعهما والأنشطة المتعلقة بهما بموجب نظام يصدر لهذه الغاية .","title":"إجازات التأمين","memo":"⭐ تحدد إجازات التأمين على الحياة والتأمينات العامة وفروعهما والأنشطة المتعلقة بهما بموجب نظام.","qs":[{"q":"تحدد إجازات التأمين على الحياة والتأمينات العامة وفروعهما بموجب:","o":["نظام يصدر لهذه الغاية","تعليمات يصدرها المحافظ","قرار من مجلس الوزراء","قرار من مجلس إدارة شركة التأمين"],"a":0}]},{"n":"5","chapter":"","notes":[],"source":"أ- لا يجوز لأي شخص ممارسة أعمال التأمين وأعمال الخدمات التأمينية إلا بعد حصوله على الترخيص اللازم وفق أحكام هذا القانون.\nب- يحظر على أي شخص غير حاصـل على ترخيص وفق أحكام هذا القانون ممارسة أعمال التأمين أو أي من الخدمات التأمينية أن يستعمل في أوراقه ووثائقه ودعاياته أي كلمة أو عبارة بأي لغة تدل على ممارسة أي من تلك الأعمال أو الخدمات.","title":"حظر ممارسة التأمين دون ترخيص","memo":"⭐ لا تمارس أعمال التأمين والخدمات التأمينية إلا بعد الحصول على الترخيص.\n⭐ يحظر على غير المرخص استعمال أي كلمة أو عبارة بأي لغة تدل على ممارسة تلك الأعمال في أوراقه ووثائقه ودعاياته.","qs":[{"q":"لا يجوز لأي شخص ممارسة أعمال التأمين وأعمال الخدمات التأمينية إلا:","o":["بعد حصوله على الترخيص اللازم وفق أحكام القانون","بعد تسجيله لدى وزارة الصناعة والتجارة فقط","بعد موافقة الاتحاد الأردني لشركات التأمين","بعد إيداع كفالة بنكية لدى المحكمة"],"a":0},{"q":"حالة عملية: شخص غير مرخص استعمل في دعاياته عبارة باللغة الإنجليزية تدل على ممارسة أعمال الوساطة التأمينية، فإن ذلك:","o":["محظور لأن الحظر يشمل أي كلمة أو عبارة بأي لغة","جائز لأن الحظر يقتصر على العبارات باللغة العربية","جائز ما دام لم يبرم أي عقد تأمين فعلاً","جائز بشرط إعلام البنك المركزي خلال ثلاثين يوماً"],"a":0}]},{"n":"6","chapter":"","notes":[],"source":"أ- لا يجوز التأمين على المسؤولية الناشئة داخل المملكة أو على أي من الأموال المنقولة وغير المنقولة الواقعة في المملكة لدى شركة تأمين خارج المملكة، كما لا يجوز لأي جهة في المملكة إجراء أي تأمين للعاملين لديها داخل المملكة أو لعملائها المقيمين في المملكة لدى شركة تأمين خارج المملكة.\nب- على الرغم مما ورد في الفقرة (أ) من هذه المادة، يجوز التأمين لدى شركة تأمين خارج المملكة بعد أخذ الموافقة الخطية المسبقة من البنك المركزي وذلك في أي من الحالات التالية:-\n١-عدم وجود شركة تأمين عاملة في المملكة حاصلة على ترخيص في فرع التأمين موضوع عقد التأمين المراد ابرامه أو عدم طرح التغطية التأمينية المطلوبة في المملكة.\n٢- امتناع او تعذر شركات التأمين العاملة في المملكة لأسباب مبررة عن توفير هذه التغطية التأمينية.","title":"التأمين لدى شركات خارج المملكة","memo":"⭐ الأصل: لا يجوز التأمين على المسؤولية الناشئة داخل المملكة أو الأموال الواقعة فيها أو العاملين/العملاء المقيمين لدى شركة تأمين خارج المملكة.\n⭐ الاستثناء: بموافقة خطية مسبقة من البنك المركزي عند عدم وجود شركة مرخصة بالفرع أو عدم طرح التغطية، أو امتناع/تعذر الشركات لأسباب مبررة.","qs":[{"q":"يجوز التأمين لدى شركة تأمين خارج المملكة على أموال واقعة في المملكة بعد الحصول على:","o":["الموافقة الخطية المسبقة من البنك المركزي","موافقة وزير الصناعة والتجارة","موافقة مجلس الوزراء","موافقة الهيئة العامة للمؤمن له"],"a":0},{"q":"أي مما يلي لا يعد من حالات جواز التأمين لدى شركة تأمين خارج المملكة؟","o":["انخفاض قسط التأمين لدى الشركة الأجنبية عنه لدى الشركات المحلية","عدم وجود شركة تأمين عاملة في المملكة مرخصة في فرع التأمين المطلوب","عدم طرح التغطية التأمينية المطلوبة في المملكة","امتناع شركات التأمين العاملة في المملكة لأسباب مبررة عن توفير التغطية"],"a":0},{"q":"حالة عملية: شركة أردنية تريد التأمين الصحي على العاملين لديها داخل المملكة لدى شركة تأمين أجنبية خارج المملكة مع توفر هذه التغطية محلياً، فإن ذلك:","o":["غير جائز","جائز دون أي موافقة","جائز بموافقة الهيئة العامة للشركة","جائز إذا كان عدد العاملين يزيد على مئة"],"a":0}]},{"n":"7","chapter":"","notes":[],"source":"للبنك المركزي وبطلب من الجهة أو من الصندوق أو من الهيئة العامة أن يخضع لرقابته وفقاً لأحكام هذا القانون أي جهة أو صندوق يوفر لأعضائه أو المستفيدين منه منافع تأمينية كالتي يوفرها عقد التأمين دون وجود شركة تأمين وذلك بموجب نظام خاص يصدر لهذه الغاية يتضمن حماية حقوق المؤمن لهم.","title":"إخضاع الصناديق والجهات لرقابة البنك المركزي","memo":"⭐ للبنك المركزي، بطلب من الجهة أو الصندوق أو الهيئة العامة، إخضاع أي جهة/صندوق يوفر منافع تأمينية دون شركة تأمين لرقابته.\n⭐ يتم ذلك بموجب نظام خاص يتضمن حماية حقوق المؤمن لهم.","qs":[{"q":"يخضع البنك المركزي لرقابته أي صندوق يوفر لأعضائه منافع تأمينية دون وجود شركة تأمين بناءً على:","o":["طلب من الجهة أو من الصندوق أو من الهيئة العامة","قرار منفرد من وزير المالية","طلب من شركة تأمين منافسة","حكم قضائي"],"a":0},{"q":"يتم إخضاع الجهات والصناديق التي توفر منافع تأمينية لرقابة البنك المركزي بموجب:","o":["نظام خاص يصدر لهذه الغاية","تعليمات يصدرها المحافظ","عقد يبرم مع شركة تأمين","قرار من الهيئة العامة للصندوق فقط"],"a":0}]},{"n":"8","chapter":"","notes":[],"source":"أ- يشتـرط لترخيص شركة التأمين أن تكون شركة مساهمة عامة، ويستثنى من ذلك ما يلي:-\n١- فرع شركة التأمين الأجنبية.\n٢- الشركة التابعة لشركة تأمين سواء كانت أردنية أو أجنبية.\n٣- شركـــة التأمين الأردنية العاملـة خارج المملكة (الشركة المعفاة).\n٤- شركة التأمين المقيدة على أن تكون شركة مساهمة خاصة أو ذات مسؤولية محدودة.\nب- يتـم ترخيص شركة التأمين بقرار من المجلس وفقاً للمتطلبات والشروط والإجراءات التي تحدد بنظام يصدر لهذه الغاية لمنح الموافقة المبدئية أو الموافقة النهائية للترخيص بما في ذلك المتطلبات والشروط الخاصة ببرنامج العمل للسنوات الثلاث الأولى لعمل شركة التأمين وهيكلها التنظيمي والملاءمة والكفاءة لمؤسسيها والقائمين على إدارتها وبياناتها المالية التقديرية.\nج- للمجلس وبقرار مسبب رفض طلب الترخيص إذا تبين له أن هذا الترخيص لن يحقق قيمة مضافة في قطاع التأمين أو ستكون له انعكاسات سلبية أو غير مقبولة على هذا القطاع.\nد- يعتبر طلب الترخيص موافق عليه حكماً في حال لم يصدر المجلس قراره بالموافقة أو الرفض خلال مدة تسعين يوماً تبدأ من تاريخ استكمال المتطلبات والشروط اللازمة للحصول على الترخيص.\nهـ- يترتب على شركة التأمين الحاصلة على ترخيص بمقتضى أحكام هذا القانون إعلام البنك المركزي فوراً عن أي تغيير يطرأ على البيانات والمعلومات التي منح الترخيص بمقتضاها.","title":"شروط ترخيص شركة التأمين","memo":"⭐ يشترط أن تكون شركة مساهمة عامة، ويستثنى: فرع الأجنبية، الشركة التابعة، الشركة المعفاة، والمقيدة (مساهمة خاصة أو ذات مسؤولية محدودة).\n⭐ يتم الترخيص بقرار من المجلس؛ ويتضمن برنامج العمل للسنوات الثلاث الأولى.\n⭐ يعتبر الطلب موافقاً عليه حكماً إذا لم يصدر القرار خلال تسعين يوماً من استكمال المتطلبات.\n⭐ للمجلس رفض الطلب بقرار مسبب إذا لم يحقق قيمة مضافة أو كانت له انعكاسات سلبية.","qs":[{"q":"يشترط في الأصل لترخيص شركة التأمين أن تكون:","o":["شركة مساهمة عامة","شركة ذات مسؤولية محدودة","شركة توصية بسيطة","شركة مساهمة خاصة"],"a":0},{"q":"يعتبر طلب ترخيص شركة التأمين موافقاً عليه حكماً إذا لم يصدر المجلس قراره خلال:","o":["تسعين يوماً من تاريخ استكمال المتطلبات والشروط","ثلاثين يوماً من تاريخ تقديم الطلب","ستين يوماً من تاريخ استكمال المتطلبات والشروط","اثني عشر شهراً من تاريخ تقديم الطلب"],"a":0},{"q":"يتم ترخيص شركة التأمين بقرار من:","o":["المجلس","المحافظ","وزير الصناعة والتجارة","مراقب عام الشركات"],"a":0},{"q":"يجوز أن تكون شركة التأمين المقيدة:","o":["شركة مساهمة خاصة أو ذات مسؤولية محدودة","شركة تضامن أو توصية بسيطة","شركة مساهمة عامة فقط","فرعاً لشركة أجنبية فقط"],"a":0}]},{"n":"9","chapter":"","notes":[],"source":"أ- تقـدم شركة التأمين الأجنبية طلب الترخيص للمجلس لفتح فرع لها في المملكة على أن تتوافر فيها الشروط التالية:-\n١-أن تكون مرخصة لممارسة نوع التأمين ذاته في بلد مركزها الرئيسي.\n٢-أن تتمتع بسمعة وملاءة مالية جيدة.\n٣-أن تكون حاصلة من الجهة المختصة في بلد مركزها الرئيسي على موافقة لممارسة أعمال التأمين في المملكة.\nب- يصدر البنك المركزي قراره بطلب ترخيص فرع شركة التأمين الأجنبية وفق الشروط والإجراءات التي يحددها نظام يصدر لهذه الغاية.","title":"ترخيص فرع شركة التأمين الأجنبية","memo":"⭐ تقدم الأجنبية الطلب للمجلس بشروط: مرخصة لنوع التأمين ذاته في بلد مركزها، سمعة وملاءة جيدة، موافقة الجهة المختصة في بلدها على العمل في المملكة.\n⭐ يصدر البنك المركزي قراره وفق شروط وإجراءات يحددها نظام.","qs":[{"q":"أي مما يلي لا يعد من الشروط الواجب توافرها في شركة التأمين الأجنبية لفتح فرع لها في المملكة؟","o":["أن يكون لها شريك أردني يملك نصف رأسمال الفرع","أن تكون مرخصة لممارسة نوع التأمين ذاته في بلد مركزها الرئيسي","أن تتمتع بسمعة وملاءة مالية جيدة","أن تحصل من الجهة المختصة في بلد مركزها الرئيسي على موافقة لممارسة أعمال التأمين في المملكة"],"a":0},{"q":"تقدم شركة التأمين الأجنبية طلب الترخيص لفتح فرع لها في المملكة إلى:","o":["المجلس","وزير الصناعة والتجارة","مجلس الوزراء","الاتحاد الأردني لشركات التأمين"],"a":0}]},{"n":"10","chapter":"","notes":[],"source":"أ- تلتزم شركة التأمين الأجنبية عند بدء عملها في المملكة بتعيين مدير مفوض مقيم في المملكة متفرغ لممارسة أعمال التأمين باسمها وبالنيابة عنها في المملكة، وتكون مسؤولة عن جميع أعماله.\nب- على شركة التأمين الأجنبية أن ترفق بقرار تعيين المدير المفوض وثيقة صادرة عنها مصادقاً عليها حسب الأصول تودع لدى البنك المركزي صورة مصدقة عنها تخوله ممارسة الصلاحيات اللازمة لإدارة الفرع بما في ذلك ما يلي:-\n١- إصدار عقود التأمين وملاحقها ودفع التعويضات المترتبة عليها.\n٢- تمثيل الشركة لدى البنك المركزي وأمام المحاكم المختصة وسائر الجهات الرسمية وغير الرسمية فيما يتعلق بأعمال الفرع وإدارته.\n٣- تبلغ الإنذارات وسائر الإشعارات والمراسلات الموجهة إلى كل من الشركة الأم والفرع.","title":"المدير المفوض لفرع الشركة الأجنبية","memo":"⭐ تلتزم الأجنبية عند بدء عملها بتعيين مدير مفوض مقيم في المملكة متفرغ، وتكون مسؤولة عن جميع أعماله.\n⭐ تودع لدى البنك المركزي صورة مصدقة عن وثيقة التفويض.\n⭐ صلاحياته: إصدار العقود ودفع التعويضات، التمثيل أمام البنك المركزي والمحاكم، تبلغ الإنذارات والمراسلات.","qs":[{"q":"تلتزم شركة التأمين الأجنبية عند بدء عملها في المملكة بتعيين مدير مفوض يشترط فيه أن يكون:","o":["مقيماً في المملكة ومتفرغاً","أردني الجنسية وحاصلاً على شهادة الاكتواري","عضواً في مجلس إدارة الشركة الأم","مقيماً في بلد المركز الرئيسي للشركة"],"a":0},{"q":"المسؤول عن جميع أعمال المدير المفوض لفرع شركة التأمين الأجنبية هو:","o":["شركة التأمين الأجنبية","البنك المركزي","المدير المفوض وحده","الاتحاد الأردني لشركات التأمين"],"a":0},{"q":"تودع صورة مصدقة عن الوثيقة التي تخول المدير المفوض صلاحيات إدارة الفرع لدى:","o":["البنك المركزي","وزارة العدل","دائرة مراقبة الشركات","المحكمة المختصة"],"a":0}]},{"n":"11","chapter":"","notes":[],"source":"للمجلـس أن يصدر قرارا بإلغاء ترخيص شركة التأمين في أي من\nالحالات التالية : -\nأ- إذا منح الترخيص بناء على معلومات غير صحيحة أو مضللة وردت في طلب الترخيص أو الوثائق المرفقة به.\nب- إذا لم تبدأ شركة التأمين بممارسة أعمالها خلال اثني عشر شهرا من تاريخ حصولها على الترخيص.\nج- إذا قدمت شركة التأمين طلبا لإلغاء ترخيصها.\nد- إذا تم إلغاء ترخيص شركة تأمين أخرى لها مصلحة مؤثرة في شركة التأمين وكانت لهذا الإلغاء انعكاسات سلبية على شركة التأمين وفقاً لأسباب مبررة يحددها البنك المركزي في قرار الإلغاء.","title":"حالات إلغاء ترخيص شركة التأمين","memo":"⭐ للمجلس إلغاء الترخيص إذا: منح بناءً على معلومات غير صحيحة أو مضللة؛ لم تبدأ العمل خلال اثني عشر شهراً؛ طلبت الشركة الإلغاء؛ ألغي ترخيص شركة لها مصلحة مؤثرة فيها وكان للإلغاء انعكاسات سلبية.","qs":[{"q":"للمجلس إلغاء ترخيص شركة التأمين إذا لم تبدأ بممارسة أعمالها خلال ... من تاريخ حصولها على الترخيص:","o":["اثني عشر شهراً","ستة أشهر","تسعين يوماً","أربعة وعشرين شهراً"],"a":0},{"q":"أي مما يلي لا يعد من حالات إلغاء ترخيص شركة التأمين بموجب المادة (١١)؟","o":["تحقيق الشركة خسائر في سنة مالية واحدة","منح الترخيص بناءً على معلومات غير صحيحة أو مضللة","تقديم شركة التأمين طلباً لإلغاء ترخيصها","إلغاء ترخيص شركة تأمين أخرى لها مصلحة مؤثرة فيها مع انعكاسات سلبية"],"a":0},{"q":"الجهة المختصة بإصدار قرار إلغاء ترخيص شركة التأمين هي:","o":["المجلس","المحافظ","مجلس الوزراء","الهيئة العامة لشركة التأمين"],"a":0}]},{"n":"12","chapter":"","notes":[],"source":"أ- إضافة الى الحالات الواردة في المادة (١١) من هذا القانون، للمجلس إلغاء ترخيص فرع شركة التأمين الأجنبية في أي من الحالات التالية:- ١- إذا توقفت الشركة في مركزها الرئيسي عن ممارسة أعمال التأمين. ٢- إذا طرأ أي تغيير على جنسية الشركة الأم أو على ملكيتها أو على عقد تأسيسها أو نظامها الأساسي، وكان هذا التغيير مؤثرا على فرع شركة التأمين الأجنبية وفق تقدير البنك المركزي.\n٣- إذا حصل ضعف جوهري في المركز المالي للشركة الأم، أو إذا طرأ لديها أي تغيير جوهري يرى البنك المركزي أنه يؤثر سلبا في نشاط فرع شركة التأمين الأجنبية في المملكة أو حسن سير أعمالها.\n٤- إذا ثبت أن السلطات المختصة في بلد مركزها الرئيسي لا تطبق الأسس السليمة في الرقابة على أعمال التأمين.\nب- إذا تم إلغاء ترخيص فرع شركة تأمين أجنبيـــة، فلا يجوز للفرع أو الشركة الأم التصرف في أي من موجودات الفرع وأمواله أو تحويلها إلى خارج المملكة إلا بعد تسديد الالتزامات المترتبة عليه داخل المملكة جميعها.","title":"إلغاء ترخيص فرع الشركة الأجنبية","memo":"⭐ إضافة لحالات المادة (١١): توقف المركز الرئيسي، تغيير مؤثر في جنسية/ملكية الشركة الأم، ضعف جوهري في مركزها المالي، عدم تطبيق سلطات بلدها أسساً سليمة للرقابة.\n⭐ بعد الإلغاء لا يجوز التصرف بموجودات الفرع أو تحويلها للخارج إلا بعد تسديد جميع الالتزامات داخل المملكة.","qs":[{"q":"أي مما يلي لا يعد من الحالات الإضافية لإلغاء ترخيص فرع شركة التأمين الأجنبية؟","o":["تعيين مدير مفوض جديد للفرع","توقف الشركة في مركزها الرئيسي عن ممارسة أعمال التأمين","حصول ضعف جوهري في المركز المالي للشركة الأم","ثبوت أن السلطات المختصة في بلد مركزها الرئيسي لا تطبق الأسس السليمة في الرقابة"],"a":0},{"q":"إذا ألغي ترخيص فرع شركة تأمين أجنبية، فلا يجوز تحويل موجودات الفرع إلى خارج المملكة إلا:","o":["بعد تسديد الالتزامات المترتبة عليه داخل المملكة جميعها","بعد مرور سنة على قرار الإلغاء","بموافقة الشركة الأم","بعد تسديد نصف الالتزامات داخل المملكة"],"a":0},{"q":"يُعتد بالتغيير الطارئ على جنسية الشركة الأم أو ملكيتها كسبب لإلغاء ترخيص الفرع إذا كان مؤثراً على الفرع وفق تقدير:","o":["البنك المركزي","الشركة الأم","المدير المفوض","المحكمة المختصة"],"a":0}]},{"n":"13","chapter":"","notes":[],"source":"أ- على شركة التأمين أن تقدم إلى البنك المركزي وديعة نقدية لأمر المحافظ اضافة الى وظيفته تودع لدى أي بنك عامل في المملكة وذلك ضمانا لالتزامها بأحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه، ويكون المحافظ هو صاحب الحق الوحيد في التصرف في هذه الوديعة، ويحدد مبلغها وسائر الأمور المتعلقة بها بموجب نظام يصدر لهذه الغاية.\nب-١- للمحافظ في حال عدم التزام شركة التأمين بدفع مبالغ الغرامات أو الرسوم أو أي مبالغ أخرى يتم فرضها بمقتضى أحكام هذا القانون أو الأنظمة أو التعليمات الصادرة بمقتضاه أن يقرر اقتطاع هذه المبالغ من مبلغ الوديعة.\n٢- لا يجوز الحجـز أو التنفيذ علـى الوديعة لصالح أي جهة كانت أو استعمالها لأي غاية أخرى خلاف ما هو منصوص عليه في البند (١) من هذه الفقرة الا اذا وقع الحجز او التنفيذ لصالح المؤمن لهم.\nج- إذا وقع نقص في مبلغ الوديعة، فعلى شركة التأمين تسديده خلال المدة التي يحددها البنك المركزي.","title":"الوديعة النقدية لشركة التأمين","memo":"⭐ وديعة نقدية لأمر المحافظ إضافة لوظيفته لدى أي بنك عامل في المملكة، والمحافظ صاحب الحق الوحيد في التصرف بها، ويحدد مبلغها بنظام.\n⭐ للمحافظ اقتطاع الغرامات والرسوم غير المدفوعة منها.\n⭐ لا يجوز الحجز أو التنفيذ عليها إلا لصالح المؤمن لهم.\n⭐ يسدد النقص خلال المدة التي يحددها البنك المركزي.","qs":[{"q":"صاحب الحق الوحيد في التصرف في الوديعة النقدية لشركة التأمين هو:","o":["المحافظ","مجلس إدارة شركة التأمين","المدير العام لشركة التأمين","وزير المالية"],"a":0},{"q":"لا يجوز الحجز أو التنفيذ على وديعة شركة التأمين إلا إذا وقع لصالح:","o":["المؤمن لهم","دائرة ضريبة الدخل والمبيعات","البنك المودعة لديه","مساهمي شركة التأمين"],"a":0},{"q":"يحدد مبلغ الوديعة النقدية لشركة التأمين وسائر الأمور المتعلقة بها بموجب:","o":["نظام يصدر لهذه الغاية","تعليمات يصدرها مجلس إدارة الشركة","قرار من الهيئة العامة للشركة","قانون الشركات"],"a":0},{"q":"إذا وقع نقص في مبلغ الوديعة، فعلى شركة التأمين تسديده خلال:","o":["المدة التي يحددها البنك المركزي","ثلاثين يوماً من تاريخ النقص","تسعين يوماً من تاريخ النقص","السنة المالية التالية"],"a":0}]},{"n":"14","chapter":"","notes":[],"source":"على شركة التأمين خلال ثلاثين يوماً من تاريخ منحها الترخيص أن تعتمد اكتوارياً للوفاء بالمتطلبات ذات العلاقة بالأمور الاكتوارية الخاصة بعمل شركة التأمين المنصوص عليها في هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه.","title":"اعتماد الاكتواري","memo":"⭐ على شركة التأمين خلال ثلاثين يوماً من تاريخ منحها الترخيص أن تعتمد اكتوارياً.","qs":[{"q":"على شركة التأمين أن تعتمد اكتوارياً خلال ... من تاريخ منحها الترخيص:","o":["ثلاثين يوماً","تسعين يوماً","ستين يوماً","اثني عشر شهراً"],"a":0},{"q":"الغاية من اعتماد شركة التأمين اكتوارياً وفق القانون:","o":["الوفاء بالمتطلبات ذات العلاقة بالأمور الاكتوارية الخاصة بعمل الشركة","تدقيق الحسابات الختامية للشركة","تمثيل الشركة أمام المحاكم","مراقبة التزام الشركة بأحكام الشريعة الإسلامية"],"a":0}]},{"n":"15","chapter":"","notes":[],"source":"أ- لا يجوز لشركة التأمين إجراء أي تعديل علــى عقد تأسيسها أو نظامهـا الأساسـي، بما في ذلك غاياتها أو زيادة رأس مالها أو تخفيضه، إلا بعد الحصول على موافقة خطية مسبقة من البنك المركزي.\nب- لا يجوز لشركة التأمين أن تتوقف عن ممارسة أعمالها لأي سبب كان إلا بعد الحصول على موافقة خطية مسبقة من البنك المركزي.","title":"تعديل عقد التأسيس والتوقف عن العمل","memo":"⭐ لا يجوز تعديل عقد التأسيس أو النظام الأساسي (بما فيه الغايات أو زيادة رأس المال أو تخفيضه) إلا بموافقة خطية مسبقة من البنك المركزي.\n⭐ لا يجوز التوقف عن ممارسة الأعمال لأي سبب إلا بموافقة خطية مسبقة من البنك المركزي.","qs":[{"q":"لا يجوز لشركة التأمين زيادة رأسمالها أو تخفيضه إلا بعد الحصول على:","o":["موافقة خطية مسبقة من البنك المركزي","موافقة الهيئة العامة فقط","موافقة لاحقة من المحافظ","إشعار البنك المركزي خلال ثلاثين يوماً"],"a":0},{"q":"حالة عملية: قررت شركة تأمين التوقف عن ممارسة أعمالها بسبب ضعف السوق، فإن ذلك:","o":["لا يجوز إلا بعد الحصول على موافقة خطية مسبقة من البنك المركزي","يجوز بقرار من مجلس إدارتها فقط","يجوز بعد إعلام المؤمن لهم بثلاثين يوماً","يجوز دون موافقة لأن السبب مبرر"],"a":0}]},{"n":"16","chapter":"","notes":[],"source":"لا يجوز لشركة التأمين ممارسة أعمالها في أي موقع داخل المملكة أو خارجها أو وقف أعمالها من خلال هذا الموقع أو تغييره إلا بموافقة خطية مسبقة من البنك المركزي ووفق تعليمات تصدر لهذه الغاية.","title":"مواقع عمل شركة التأمين","memo":"⭐ ممارسة الأعمال في أي موقع داخل المملكة أو خارجها أو وقفها أو تغيير الموقع تحتاج موافقة خطية مسبقة من البنك المركزي ووفق تعليمات.","qs":[{"q":"لا يجوز لشركة التأمين تغيير أي موقع تمارس أعمالها من خلاله إلا:","o":["بموافقة خطية مسبقة من البنك المركزي","بقرار من مجلس إدارتها فقط","بإشعار لاحق للبنك المركزي","بموافقة أمانة عمان الكبرى"],"a":0},{"q":"يشمل اشتراط الموافقة المسبقة للبنك المركزي على مواقع عمل شركة التأمين المواقع:","o":["داخل المملكة وخارجها","داخل المملكة فقط","خارج المملكة فقط","الرئيسية دون الفروع"],"a":0}]},{"n":"17","chapter":"","notes":[],"source":"أ- تطبق أحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه على الشركة المعفاة والشركة المقيدة وشركة إعادة التأمين بقدر انطباقها عليها ووفقاً لما تحدده تعليمات تصدر لهذه الغاية.\nب- تحدد بنظام الأحكام الخاصة بترخيص شركة التأمين الأجنبية غير العاملة في المملكة.","title":"الشركة المعفاة والمقيدة وإعادة التأمين","memo":"⭐ تطبق أحكام القانون على الشركة المعفاة والمقيدة وشركة إعادة التأمين بقدر انطباقها ووفق تعليمات.\n⭐ أحكام ترخيص شركة التأمين الأجنبية غير العاملة في المملكة تحدد بنظام.","qs":[{"q":"تطبق أحكام القانون على الشركة المعفاة والشركة المقيدة وشركة إعادة التأمين:","o":["بقدر انطباقها عليها ووفقاً لما تحدده تعليمات تصدر لهذه الغاية","بشكل كامل دون أي استثناء","لا تطبق عليها مطلقاً","وفقاً لما يقرره مجلس إدارة كل منها"],"a":0},{"q":"تحدد الأحكام الخاصة بترخيص شركة التأمين الأجنبية غير العاملة في المملكة بموجب:","o":["نظام","تعليمات يصدرها المحافظ","قرار من مجلس الوزراء","اتفاقية دولية"],"a":0}]},{"n":"18","chapter":"","notes":[],"source":"أ- يكون مجلس إدارة شركة التأمين مسؤولا عن وضع السياسات العامة لشركة التأمين والإشراف عليها وتطبيق قواعد الحوكمة فيها وفقاً لأحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه والتشريعات ذات العلاقة.\nب-١- على الرغم مما ورد في قانون الشركات يحدد البنك المركزي عدد اعضاء مجلس إدارة شركة التأمين بما لا يقل عن سبعة اعضاء وعدد الاعضاء المستقلين منهم على ان لا يزيد عددهم على نصف عدد اعضاء مجلس الادارة .\n٢- يجب ان تتوافر فيمن يشغل رئاسة او عضوية مجلس إدارة شركة التأمين إضافة الى ما هو منصوص عليه في قانون الشركات الشروط التالية :-\nأ- أن لا يقل عمره عن خمسة وعشرين سنة .\nب- أن يكون حسن السيرة.\nج- أن لا يكون عضوا في مجلس إدارة أي شركة تأمين أخرى أو مديرا عاما لها أو مديرا مفوضا أو موظفا فيها ما لم تكن شركة التأمين الأخرى شركة تابعة لتلك الشركة .\nد- يجوز للبنك المركزي أن يحدد المؤهلات والخبرات والشروط الواجب توافرها في الرئيس أو عضو مجلس إدارة شركة التأمين ومدى ملاءمة الاعضاء لهذه الشروط .\nج- لا يجوز ترشيح أو تعيين أي شخص عضواً أو ممثلاً عن عضو في مجلس إدارة شركة التأمين دون الحصول على موافقة البنك المركزي المسبقة على ترشيحه أو تعيينه.\nد- يشترط الحصول على الموافقة المسبقة للبنك المركزي قبل تعيين أي موظف رئيسي في شركة التأمين وفق التعليمات التي تصدر لهذه الغاية.","title":"مجلس إدارة شركة التأمين","memo":"⭐ يحدد البنك المركزي عدد الأعضاء بما لا يقل عن سبعة، والمستقلون لا يزيدون على نصف عدد الأعضاء.\n⭐ يشترط ألا يقل عمر الرئيس/العضو عن خمسة وعشرين سنة وأن يكون حسن السيرة وألا يكون عضواً أو موظفاً في شركة تأمين أخرى (إلا التابعة).\n⭐ ترشيح/تعيين العضو وتعيين أي موظف رئيسي يحتاج موافقة البنك المركزي المسبقة.","qs":[{"q":"يحدد البنك المركزي عدد أعضاء مجلس إدارة شركة التأمين بما لا يقل عن:","o":["سبعة أعضاء","خمسة أعضاء","تسعة أعضاء","ثلاثة أعضاء"],"a":0},{"q":"يشترط فيمن يشغل رئاسة أو عضوية مجلس إدارة شركة التأمين ألا يقل عمره عن:","o":["خمسة وعشرين سنة","ثمانية عشر سنة","ثلاثين سنة","واحد وعشرين سنة"],"a":0},{"q":"عدد الأعضاء المستقلين في مجلس إدارة شركة التأمين:","o":["لا يزيد على نصف عدد أعضاء مجلس الإدارة","لا يقل عن نصف عدد أعضاء مجلس الإدارة","لا يزيد على ثلث عدد أعضاء مجلس الإدارة","لا يقل عن سبعة أعضاء"],"a":0},{"q":"حالة عملية: مرشح لعضوية مجلس إدارة شركة تأمين يشغل وظيفة في شركة تأمين أخرى ليست تابعة لها، فإن ترشيحه:","o":["لا يجوز لفقدانه أحد شروط العضوية","جائز بموافقة الهيئة العامة","جائز إذا كان عمره يزيد على خمسة وعشرين سنة","جائز إذا كان عضواً مستقلاً"],"a":0}]},{"n":"19","chapter":"","notes":[],"source":"لا يجـوز أن يكـون عضواً في مجلس إدارة شركة التأمين بصفة شخصية أو بصفة ممثل عن أي مساهم أو أن يكون موظفاً رئيسياً فيها أو أن يقدم أي خدمات إليها أي شخص:-\nأ- صدر بحقه حكم قضائي قطعي بجنحة مخلة بالشرف والأمانة أو بجناية أو ما زال خاضعاً لإجراءات الإعسار أو صدر عليه حكم بالإفلاس ولم يرد إليه اعتباره.\nب- كان مسؤولاً بأي صفة كانت ووفقاً لتقدير المجلس عن مخالفة جسيمة لأي من أحكام التشريعات ذات العلاقة بالأنشطة المالية.","title":"موانع العضوية والوظيفة الرئيسية","memo":"⭐ يمنع من العضوية أو الوظيفة الرئيسية أو تقديم الخدمات: المحكوم بحكم قطعي بجنحة مخلة بالشرف والأمانة أو بجناية، الخاضع لإجراءات الإعسار، المفلس غير المرد اعتباره.\n⭐ والمسؤول وفق تقدير المجلس عن مخالفة جسيمة لتشريعات الأنشطة المالية.","qs":[{"q":"أي مما يلي لا يعد مانعاً من عضوية مجلس إدارة شركة التأمين وفق المادة (١٩)؟","o":["صدور حكم بالإفلاس ورد اعتباره بعد ذلك","صدور حكم قضائي قطعي بجناية","الخضوع لإجراءات الإعسار","صدور حكم قطعي بجنحة مخلة بالشرف والأمانة"],"a":0},{"q":"يعتبر الشخص ممنوعاً من أن يكون موظفاً رئيسياً في شركة التأمين إذا كان مسؤولاً عن مخالفة جسيمة لتشريعات الأنشطة المالية وفقاً لتقدير:","o":["المجلس","المحكمة المختصة","الهيئة العامة لشركة التأمين","المدير العام لشركة التأمين"],"a":0}]},{"n":"20","chapter":"","notes":[],"source":"يفقد عضو مجلس إدارة شركة التأمين عضويته بقرار يتخذه المجلس وذلك في أي من الحالتين التاليتين:-\nأ- إذا فقد أي شرط من الشروط الواجب توافرها في عضويته في مجلس إدارة شركة التأمين وفقا لأحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه.\nب- إذا قرر المجلس تنحية رئيس أو أي من أعضاء مجلس إدارة شركة التأمين لأسباب مبررة.","title":"فقدان عضوية مجلس الإدارة","memo":"⭐ يفقد العضو عضويته بقرار من المجلس إذا فقد أي شرط من شروط العضوية، أو إذا قرر المجلس تنحيته لأسباب مبررة.","qs":[{"q":"يفقد عضو مجلس إدارة شركة التأمين عضويته بقرار يتخذه:","o":["المجلس","مجلس إدارة شركة التأمين","الهيئة العامة للمساهمين","المحافظ"],"a":0},{"q":"من الحالتين اللتين يفقد فيهما عضو مجلس إدارة شركة التأمين عضويته وفق المادة (٢٠):","o":["قرار المجلس تنحيته لأسباب مبررة","تغيبه عن اجتماع واحد لمجلس الإدارة","انتهاء سنة على عضويته","بيعه جزءاً من أسهمه"],"a":0}]},{"n":"21","chapter":"","notes":[],"source":"لا يجوز لمن فقد عضويته في مجلس إدارة شركة التأمين لأي سبب من الاسباب أن يكون رئيساً أو عضوا في مجلس إدارة أي شركة تأمين أخرى بصفته الشخصية أو بصفته ممثلاً عن أي مساهم أو أن يعمل فيها أو أن يقدم خدمات إليها دون الحصول على موافقة خطية مسبقة من البنك المركزي.","title":"حظر عمل من فقد العضوية","memo":"⭐ من فقد عضويته لأي سبب لا يكون رئيساً أو عضواً في شركة تأمين أخرى أو يعمل فيها أو يقدم خدمات لها دون موافقة خطية مسبقة من البنك المركزي.","qs":[{"q":"حالة عملية: عضو فقد عضويته في مجلس إدارة شركة تأمين ويرغب في العمل لدى شركة تأمين أخرى، فإنه يحتاج إلى:","o":["موافقة خطية مسبقة من البنك المركزي","موافقة الشركة التي فقد عضويته فيها","مرور سنة على فقدان عضويته فقط","موافقة وزير الصناعة والتجارة"],"a":0},{"q":"يسري حظر العمل على من فقد عضويته في مجلس إدارة شركة التأمين إذا كان فقدانه العضوية:","o":["لأي سبب من الأسباب","بسبب صدور حكم قضائي فقط","بسبب تنحيته من المجلس فقط","بسبب استقالته فقط"],"a":0}]},{"n":"22","chapter":"","notes":[],"source":"أ- يحظر على عضو مجلس إدارة شركة التأمين، بصفته الشخصية أو بصفته ممثلاً عن أي مساهم فيها، والموظف الرئيسي فيها والمحاسب القانوني الخارجي لها ومستشارها القانوني ومستشارها الاكتواري وعضو هيئة الرقابة الشرعية ما يلي:-\n١- القيام بأعمال تنفيذية في شركة تأمين أخرى مشابهة.\n٢- أن يكون عضوا في مجالس إدارة شركات تأمين منافسة أو مشابهة.\n٣- القيام بأي عمل أو نشاط ينجم عنه تضارب مع مصلحة شركة التأمين.\n٤- ممارسة أعمال وكيل التأمين أو وسيط التأمين أو وسيط إعادة التأمين أو أي من أعمال مقدمي الخدمات التأمينية التي يحددها البنك المركزي.\n٥- أن يكون على صلة عمل أو زواج أو قرابة حتى الدرجة الثالثة مع أي من الأشخاص المشار إليهم في البند (٤) من هذه الفقرة الذين تتعامل معهم شركة التأمين.\n٦- تقاضي عمولة عن أي عمل من أعمال التأمين أو تحقيق منفعة مادية أو مزايا بأي صورة كانت عن أي من الخدمات التأمينية المقدمة لشركة التأمين.\nب- يحظر على عضو مجلس الإدارة أن يكون مديرا عاما للشركة أو مستشاراً قانونياً لها أو اكتوارياً أو محاسبا قانونيا لها أو عضوا في هيئة الرقابة الشرعية لها.\nج- يشترط أن لا يشكل تعيين الموظف الرئيسي تضارباً في المصالح ناشئاً عن صلته مع رئيس مجلس الإدارة أو أي عضو فيه أو أي مساهم رئيسي بما في ذلك الزوج وصلة القرابة حتى الدرجة الثالثة لمدير عام شركة التأمين وحتى الدرجة الأولى للموظف الرئيس ما عدا المدير العام في الشركة .","title":"حظر تضارب المصالح","memo":"⭐ يحظر على العضو والموظف الرئيسي والمحاسب الخارجي والمستشار القانوني والاكتواري وعضو هيئة الرقابة الشرعية: العمل التنفيذي أو العضوية في شركات منافسة، ممارسة أعمال الوكيل أو الوسيط، تقاضي عمولة.\n⭐ حظر الصلة أو الزواج أو القرابة حتى الدرجة الثالثة مع الوكلاء والوسطاء الذين تتعامل معهم الشركة.\n⭐ يحظر على عضو مجلس الإدارة أن يكون مديراً عاماً أو مستشاراً قانونياً أو اكتوارياً أو محاسباً قانونياً أو عضو هيئة رقابة شرعية للشركة.\n⭐ قرابة الموظف الرئيسي: حتى الثالثة للمدير العام وحتى الأولى لغيره.","qs":[{"q":"يحظر على عضو مجلس إدارة شركة التأمين أن يكون على صلة قرابة مع وكلاء ووسطاء التأمين الذين تتعامل معهم الشركة حتى الدرجة:","o":["الثالثة","الأولى","الثانية","الرابعة"],"a":0},{"q":"أي مما يلي يجوز لعضو مجلس إدارة شركة التأمين وفق المادة (٢٢)؟","o":["أن يكون رئيساً لمجلس إدارة الشركة ذاتها","أن يكون مديراً عاماً للشركة","أن يكون مستشاراً قانونياً للشركة","أن يكون اكتوارياً للشركة"],"a":0},{"q":"حالة عملية: المستشار القانوني لشركة تأمين يمارس أعمال وسيط التأمين، فإن ذلك:","o":["محظور","جائز إذا لم يتعامل مع الشركة","جائز بموافقة مجلس إدارة الشركة","جائز إذا كان مرخصاً من البنك المركزي"],"a":0},{"q":"يشترط ألا تكون للمدير العام لشركة التأمين صلة قرابة مع رئيس مجلس الإدارة أو أي عضو فيه أو أي مساهم رئيسي حتى الدرجة:","o":["الثالثة","الأولى","الثانية","الرابعة"],"a":0}]},{"n":"23","chapter":"","notes":[],"source":"إذا قدم رئيس وأعضاء مجلس إدارة شركة التأمين استقالتهم أو إذا فقد مجلس إدارة الشركة نصابه القانوني لأي سبب كان، يقوم المجلس بتشكيل لجنة مؤقتة من ذوي الخبرة والاختصاص، لتتولى إدارة شركة التأمين ودعوة هيئتها العامة إلى الاجتماع لانتخاب مجلس إدارة جديد خلال مدة لا تزيد على تسعين يوماً من تاريخ تشكيلها، قابلة للتجديد لمدة مماثلة ولمرة واحدة بقرار من المجلس، وتتحمل شركة التأمين أتعاب اللجنة المؤقتة التي يحددها المجلس.","title":"اللجنة المؤقتة لإدارة الشركة","memo":"⭐ عند استقالة الرئيس والأعضاء أو فقدان النصاب يشكل المجلس لجنة مؤقتة من ذوي الخبرة.\n⭐ تدعو الهيئة العامة لانتخاب مجلس جديد خلال مدة لا تزيد على تسعين يوماً، قابلة للتجديد لمدة مماثلة ولمرة واحدة.\n⭐ تتحمل شركة التأمين أتعاب اللجنة التي يحددها المجلس.","qs":[{"q":"إذا فقد مجلس إدارة شركة التأمين نصابه القانوني، فإن الجهة التي تشكل اللجنة المؤقتة هي:","o":["المجلس","الهيئة العامة لشركة التأمين","وزير الصناعة والتجارة","المحكمة المختصة"],"a":0},{"q":"على اللجنة المؤقتة دعوة الهيئة العامة لانتخاب مجلس إدارة جديد خلال مدة لا تزيد على:","o":["تسعين يوماً من تاريخ تشكيلها قابلة للتجديد لمرة واحدة","ستين يوماً غير قابلة للتجديد","ثلاثين يوماً قابلة للتجديد مرتين","ستة أشهر من تاريخ الاستقالة"],"a":0},{"q":"تتحمل أتعاب اللجنة المؤقتة التي تتولى إدارة شركة التأمين:","o":["شركة التأمين","البنك المركزي","أعضاء مجلس الإدارة المستقيلين","الخزينة العامة"],"a":0}]},{"n":"24","chapter":"","notes":[],"source":"يصدر المجلس التعليمات المنظمة لأعمال شركة التأمين بما في ذلك تنظيم وتحديد ما يلي:-\nأ- الحد الأدنى لرأسمال شركة التأمين ومتطلبات الملاءة المالية.\nب- أسس احتساب المخصصات الفنية.\nج- أسس استثمار أموال شركة التأمين.\nد- قواعد الحوكمة.\nهـ- إدارة المخاطر والرقابة الداخلية.\nو- السياسات المحاسبية الواجب اتباعها والنماذج اللازمة لإعداد التقارير والبيانات المالية وعرضها.\nز- السجلات التي تلتزم شركة التأمين بتنظيمها والاحتفاظ بها والبيانات والوثائق التي يتوجب عليها تزويد البنك المركزي بها.\nح- أعمال التأمين عبر الطرق الإلكترونية.\nط- أعمال التأمينات الصغيرة.\nي- أصول ممارسة المهنة والضوابط اللازمة لتعامل شركة التأمين مع عملائها بطريقة عادلة وشفافة بما في ذلك إجراءات النظر في المطالبات والشكاوى المقدمة ضد شركة التأمين وتسويتها أو الفصل فيها.\nك- اتخاذ الإجراءات اللازمة لمكافحة غسل الأموال وتمويل الإرهاب في أعمال التأمين.","title":"تعليمات المجلس لتنظيم أعمال الشركات","memo":"⭐ يصدر المجلس تعليمات تنظم: الحد الأدنى لرأس المال والملاءة، أسس المخصصات الفنية، أسس الاستثمار، الحوكمة، إدارة المخاطر، السياسات المحاسبية، السجلات، التأمين الإلكتروني، التأمينات الصغيرة، أصول المهنة والشكاوى، مكافحة غسل الأموال.","qs":[{"q":"الجهة التي تصدر التعليمات المنظمة للحد الأدنى لرأسمال شركة التأمين ومتطلبات الملاءة المالية هي:","o":["المجلس","مجلس الوزراء","الهيئة العامة لشركة التأمين","الاتحاد الأردني لشركات التأمين"],"a":0},{"q":"أي مما يلي لا يرد ضمن الأمور التي ينظمها المجلس بتعليمات بموجب المادة (٢٤)؟","o":["تحديد رواتب موظفي شركة التأمين","أسس احتساب المخصصات الفنية","أعمال التأمينات الصغيرة","مكافحة غسل الأموال وتمويل الإرهاب في أعمال التأمين"],"a":0}]},{"n":"25","chapter":"","notes":[],"source":"على شركات التأمين المرخص لها بممارسة نوعي التأمين المنصوص عليهما في المادة (٤) من هذا القانون عند نفاذ أحكامه أن تفصل فيما بين استثمارات ومخصصات كل نوع منهما وأن تخصص جهازاً فنياً منفصلاً لكل منهما، وفق الشروط والمحددات الواردة في تعليمات تصدر لهذه الغاية.","title":"الفصل بين نوعي التأمين","memo":"⭐ الشركات المرخصة بنوعي التأمين (الحياة والعامة) تفصل بين استثمارات ومخصصات كل نوع وتخصص جهازاً فنياً منفصلاً لكل منهما وفق تعليمات.","qs":[{"q":"تلتزم شركة التأمين المرخصة بممارسة التأمين على الحياة والتأمينات العامة معاً بأن:","o":["تفصل بين استثمارات ومخصصات كل نوع وتخصص جهازاً فنياً منفصلاً لكل منهما","تؤسس شركة مستقلة لكل نوع","تدمج مخصصات النوعين في حساب واحد","تتخلى عن أحد النوعين خلال سنة"],"a":0},{"q":"يتم الفصل بين استثمارات ومخصصات نوعي التأمين وفق الشروط والمحددات الواردة في:","o":["تعليمات تصدر لهذه الغاية","قانون الشركات","عقد تأسيس شركة التأمين","قرار الهيئة العامة"],"a":0}]},{"n":"26","chapter":"","notes":[],"source":"أ- لا يجوز دون موافقة خطية مسبقة من البنك المركزي إجراء أي تغيير في ملكية شركة التأمين أو تحويل في أسهمها سواء تم ذلك بعملية واحدة أو بعمليات عدة وبشكل مباشر أو غير مباشر إذا أدى هذا التحويل إلى ملكية شخص لمصلحة مؤثرة في رأسمال شركة التأمين أو أدى إلى زيادة نسبة هذه المصلحة.\nب- يسري حكم الفقرة (أ) من هذه المادة إذا كان تحويل الأسهم أو تغيير الملكية عائدا لمجموعة أشخاص من ذوي الصلة أو بينهم صلة قرابة حتى الدرجة الثالثة.\nج- إذا جرى اتفاق أو تعهد بتحويل أسهم شركة تأمين أو بإجراء تغيير في ملكيتها خلافاً لأحكام الفقرتين (أ) و (ب) من هذه المادة، فلا يجوز تنفيذ هذا الاتفاق أو التعهد لدى السلطات المختصة أو قيده في سجلاتها.\nد- إذا تم تحويل الأسهم أو تغيير الملكية خلافا لأحكام هذه المادة فيراعى ما يلي:-\n١- لا يحق لمالك الأسهم أو لمن جرى التغيير في الملكية لمصلحته أن يقبض أي أرباح أو تتأتى له أي منافع نتيجة لهذه المساهمة أو التغيير في الملكية، كما لا يحق له التصويت سواء أصالة أو وكالة في اجتماعات الهيئة العامة لشركة التأمين أو الترشح لعضوية مجلس إدارة شركة التأمين بأي صورة كانت.\n٢- لا يحق لمالك الأسهم أو لمن جرى التغيير في الملكية لمصلحته التصرف في تلك الأسهم أو الملكية أو في جزء منها سواء كان ذلك بيعاً أو رهناً أو أي تصرف دون الحصول على موافقة خطية مسبقة من البنك المركزي وللبنك المركزي وضع قيد منع التصرف في الملكية أو الأسهم.\nهـ- للبنك المركزي أن يصدر موافقة لاحقة على تحويل الأسهم أو تغيير الملكية الذي تم خلافاً لأحكام الفقرة (أ) من هذه المادة.","title":"تغيير ملكية شركة التأمين","memo":"⭐ لا يجوز دون موافقة خطية مسبقة من البنك المركزي أي تحويل يؤدي لملكية مصلحة مؤثرة أو زيادتها، ويسري ذلك على ذوي الصلة والأقارب حتى الدرجة الثالثة.\n⭐ الاتفاق المخالف لا ينفذ ولا يقيد لدى السلطات المختصة.\n⭐ المخالف لا يقبض أرباحاً ولا يصوت ولا يترشح، ولا يتصرف بالأسهم دون موافقة البنك المركزي.\n⭐ للبنك المركزي إصدار موافقة لاحقة.","qs":[{"q":"يشترط الحصول على موافقة خطية مسبقة من البنك المركزي على تحويل أسهم شركة التأمين إذا أدى التحويل إلى:","o":["ملكية شخص لمصلحة مؤثرة في رأسمال الشركة أو زيادة نسبتها","ملكية شخص لأي سهم من أسهم الشركة","انخفاض القيمة السوقية لأسهم الشركة","زيادة عدد المساهمين في الشركة"],"a":0},{"q":"يسري حكم الموافقة المسبقة على تحويل الأسهم إذا كان التحويل عائداً لمجموعة أشخاص بينهم صلة قرابة حتى الدرجة:","o":["الثالثة","الأولى","الثانية","الرابعة"],"a":0},{"q":"حالة عملية: تملك شخص مصلحة مؤثرة في شركة تأمين دون موافقة البنك المركزي، فأي مما يلي لا يترتب على ذلك؟","o":["بطلان عقد تأسيس شركة التأمين","حرمانه من قبض أي أرباح نتيجة هذه المساهمة","حرمانه من التصويت في اجتماعات الهيئة العامة","حرمانه من الترشح لعضوية مجلس الإدارة"],"a":0},{"q":"بخصوص تحويل الأسهم الذي تم خلافاً لاشتراط الموافقة المسبقة، فإن للبنك المركزي:","o":["أن يصدر موافقة لاحقة عليه","إبطال الترخيص حكماً دون أي خيار آخر","مصادرة الأسهم لصالح الخزينة","فرض بيع الأسهم في مزاد علني"],"a":0}]},{"n":"27","chapter":"","notes":[],"source":"أ- على شركة التأمين تزويد البنك المركزي بنماذج عقود التأمين وملاحقها المعتمدة لأعمالها والمعدة وفقاً للضوابط والشروط التي تحددها تعليمات تصدر لهذه الغاية، وللبنك المركزي أن يطلب من شركة التأمين في أي وقت إجراء تعديل على أي من تلك النماذج إذا وجد أن مصلحة المؤمن لهم والمستفيدين أو سلامة قطاع التأمين تقتضي ذلك.\nب- على شركة التأمين تزويد المؤمن له والمستفيد بنسخة عن عقد التأمين شاملا جميع بياناته وملاحقه.\nج- ينظم أي عقد تأمين يتم إصداره في المملكة باللغة العربية، ما لم يقرر البنك المركزي غير ذلك ولأسباب مبررة.","title":"نماذج عقود التأمين ولغتها","memo":"⭐ تزود الشركة البنك المركزي بنماذج العقود وملاحقها، وله طلب تعديلها في أي وقت لمصلحة المؤمن لهم أو سلامة القطاع.\n⭐ تزود المؤمن له والمستفيد بنسخة عن العقد شاملاً جميع بياناته وملاحقه.\n⭐ ينظم عقد التأمين الصادر في المملكة باللغة العربية ما لم يقرر البنك المركزي غير ذلك لأسباب مبررة.","qs":[{"q":"ينظم أي عقد تأمين يصدر في المملكة باللغة:","o":["العربية ما لم يقرر البنك المركزي غير ذلك لأسباب مبررة","الإنجليزية في جميع الأحوال","التي يختارها المؤمن له دون قيد","العربية والإنجليزية معاً وجوباً"],"a":0},{"q":"للبنك المركزي أن يطلب من شركة التأمين تعديل نماذج عقود التأمين:","o":["في أي وقت إذا اقتضت مصلحة المؤمن لهم والمستفيدين أو سلامة القطاع ذلك","مرة واحدة فقط عند الترخيص","بعد موافقة الهيئة العامة لشركة التأمين","خلال السنة الأولى من الترخيص فقط"],"a":0},{"q":"على شركة التأمين تزويد المؤمن له والمستفيد بـ:","o":["نسخة عن عقد التأمين شاملاً جميع بياناته وملاحقه","ملخص عن عقد التأمين دون الملاحق","نسخة عن البيانات المالية للشركة","شهادة تأمين فقط دون العقد"],"a":0}]},{"n":"28","chapter":"","notes":[],"source":"أ- لشركة التأمين القيام بأعمال إعادة التأمين في أي فرع من فروع التأمين المرخص لها بممارستها شريطة ألا تتجاوز أقساط إعادة التأمين النسب المنصوص عليها في تعليمات تصدر لهذه الغاية.\nب- لشركة التأمين إجراء إعادة التأمين داخل المملكة أو خارجها وفق المعايير والضوابط الواردة في تعليمات تصدر لهذه الغاية.","title":"أعمال إعادة التأمين","memo":"⭐ لشركة التأمين القيام بإعادة التأمين في فروعها المرخصة بشرط ألا تتجاوز الأقساط النسب المحددة بتعليمات.\n⭐ يجوز إعادة التأمين داخل المملكة أو خارجها وفق معايير وضوابط التعليمات.","qs":[{"q":"يجوز لشركة التأمين إجراء إعادة التأمين:","o":["داخل المملكة أو خارجها وفق المعايير والضوابط الواردة في التعليمات","داخل المملكة فقط","خارج المملكة فقط","لدى شركات عربية فقط"],"a":0},{"q":"يشترط لقيام شركة التأمين بأعمال إعادة التأمين في فروع التأمين المرخصة لها:","o":["ألا تتجاوز أقساط إعادة التأمين النسب المنصوص عليها في التعليمات","ألا تتجاوز أقساط إعادة التأمين (١٠%) من رأسمالها","الحصول على موافقة مجلس الوزراء","أن تكون مرخصة كشركة إعادة تأمين مستقلة"],"a":0}]},{"n":"29","chapter":"","notes":[],"source":"لشركات التأمين أن تنشئ فيما بينها مجمعا تأمينيا واحداً أو أكثر لإدارة فرع من فروع التأمين أو أي عملية بذاتها لحسابها وفقا للنظام الداخلي لكل مجمع، شريطة الحصول على الموافقة الخطية المسبقة للبنك المركزي على إنشاء أي منها ووفقاً لتعليمات تصدر لهذه الغاية.","title":"المجمعات التأمينية","memo":"⭐ لشركات التأمين إنشاء مجمع تأميني واحد أو أكثر لإدارة فرع تأمين أو عملية بذاتها وفق نظامه الداخلي.\n⭐ يشترط الحصول على موافقة خطية مسبقة من البنك المركزي ووفق تعليمات.","qs":[{"q":"يشترط لإنشاء شركات التأمين مجمعاً تأمينياً فيما بينها الحصول على:","o":["الموافقة الخطية المسبقة للبنك المركزي","موافقة مجلس الوزراء","موافقة الاتحاد الأردني لشركات التأمين فقط","موافقة لاحقة من المحافظ"],"a":0},{"q":"تنشئ شركات التأمين المجمع التأميني بهدف:","o":["إدارة فرع من فروع التأمين أو أي عملية بذاتها لحسابها","توحيد أسعار أقساط التأمين في السوق","تدقيق حسابات شركات التأمين","إعادة تأمين أخطار البنك المركزي"],"a":0}]},{"n":"30","chapter":"","notes":[],"source":"أ- تلتزم شركة التأمين المرخصة للقيام بأعمال التأمين التكافلي بأن تعكس ذلك في عقد تأسيسها ونظامها الأساسي، وعليها أن تعين هيئة تسمى (هيئة الرقابة الشرعية) بقرار من الهيئة العامة للمساهمين على أن لا يقل عدد أفرادها عن ثلاثة أشخاص ويكون رأيها ملزماً للشركة.\nب- تتولى هيئة الرقابـــة الشرعيـــة المهــــــام التالية:-\n١- مراقبة أعمال شركة التأمين وأنشطتها من حيث التزامها بأحكام الشريعة الإسلامية ومبادئها وإعلام البنك المركزي عن أي مخالفة ترتكبها شركة التأمين.\n٢- مراجعة عقود التأمين وشروطها، واتفاقيات إعادة التأمين جميعها التي تبرمها شركة التأمين لضمان توافقها مع أحكام الشريعة الإسلامية ومبادئها.\n٣- إبداء الرأي في أي أمور تكلف بها وفقاً لتعليمات تصدر لهذه الغاية.\n٤- أي مهام أخرى يكلفها بها المجلس بموجب تعليمات تصدر لهذه الغاية.\nج- تطبــق أحكـام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه على شركة التأمين المرخصة للقيام بأعمال التأمين التكافلي بالقدر الذي لا يتعارض مع طبيعة أعمالها، ولا يجوز لها ممارسة أعمال التأمين بشكل يخالف أحكام الشريعة الإسلامية ومبادئها.\nد- يصدر البنك المركزي التعليمات اللازمة لتنظيم أعمال التأمين التكافلي بما في ذلك أحكام وإجراءات تعيين هيئة الرقابة الشرعية والموافقة عليها والشروط الواجب توافرها في أعضائها.","title":"التأمين التكافلي وهيئة الرقابة الشرعية","memo":"⭐ تعين هيئة الرقابة الشرعية بقرار من الهيئة العامة للمساهمين، لا يقل عدد أفرادها عن ثلاثة، ورأيها ملزم للشركة.\n⭐ مهامها: مراقبة التزام الشركة بالشريعة وإعلام البنك المركزي بالمخالفات، ومراجعة العقود واتفاقيات إعادة التأمين.\n⭐ يصدر البنك المركزي تعليمات تنظيم التأمين التكافلي وتعيين الهيئة.","qs":[{"q":"لا يقل عدد أفراد هيئة الرقابة الشرعية في شركة التأمين التكافلي عن:","o":["ثلاثة أشخاص","خمسة أشخاص","شخصين","سبعة أشخاص"],"a":0},{"q":"تعين هيئة الرقابة الشرعية في شركة التأمين التكافلي بقرار من:","o":["الهيئة العامة للمساهمين","مجلس إدارة شركة التأمين","المحافظ","دائرة الإفتاء العام"],"a":0},{"q":"رأي هيئة الرقابة الشرعية بالنسبة لشركة التأمين التكافلي:","o":["ملزم للشركة","استشاري غير ملزم","ملزم بعد مصادقة البنك المركزي عليه فقط","ملزم بعد مصادقة الهيئة العامة عليه"],"a":0},{"q":"أي مما يلي لا يعد من مهام هيئة الرقابة الشرعية؟","o":["تدقيق الحسابات الختامية لشركة التأمين والمصادقة عليها","مراجعة عقود التأمين واتفاقيات إعادة التأمين لضمان توافقها مع الشريعة","مراقبة أعمال الشركة وإعلام البنك المركزي عن أي مخالفة","إبداء الرأي في الأمور التي تكلف بها وفقاً للتعليمات"],"a":0}]},{"n":"31","chapter":"","notes":[],"source":"لشركة التأمين بموافقة خطية مسبقة من البنك المركزي تحويل عقود التأمين التي أبرمتها بجميع حقوقها والتزاماتها إلى شركة تأمين أخرى تمارس فرع التأمين ذاته، دونما حاجة للحصول على موافقة المؤمن لهم والمستفيدين شريطة مراعاة أي شروط وقيود تقترن بتلك الموافقة وللمؤمن لهم الحق في طلب فسخ عقد التأمين مقابل استرداد نسبة من قسط التأمين تتناسب مع المدة المتبقية من العقد .","title":"تحويل عقود التأمين لشركة أخرى","memo":"⭐ يجوز بموافقة خطية مسبقة من البنك المركزي تحويل العقود بحقوقها والتزاماتها لشركة تمارس فرع التأمين ذاته دون موافقة المؤمن لهم.\n⭐ للمؤمن له طلب فسخ العقد مقابل استرداد نسبة من القسط تتناسب مع المدة المتبقية.","qs":[{"q":"يجوز لشركة التأمين تحويل عقود التأمين التي أبرمتها إلى شركة تأمين أخرى بشرط:","o":["الحصول على موافقة خطية مسبقة من البنك المركزي وأن تمارس الشركة الأخرى فرع التأمين ذاته","الحصول على موافقة جميع المؤمن لهم والمستفيدين","موافقة المحكمة المختصة","أن تكون الشركة الأخرى شركة تابعة لها"],"a":0},{"q":"حالة عملية: حُوّلت عقود شركة تأمين إلى شركة أخرى وفق القانون ولم يرغب أحد المؤمن لهم في الاستمرار، فإن له:","o":["طلب فسخ العقد مقابل استرداد نسبة من القسط تتناسب مع المدة المتبقية","استرداد كامل القسط المدفوع","إبطال قرار التحويل","المطالبة بتعويض يعادل ضعف القسط"],"a":0}]},{"n":"32","chapter":"","notes":[],"source":"أ- يصدر البنك المركزي تعليمات يحدد فيها الشروط الواجب توافرها في المحاسب القانوني الخارجي لشركات التأمين ونطاق عمله ومهامه والوثائق والتقارير الواجب تزويد شركة التأمين والبنك المركزي بها ومواعيد ذلك، وعلى المحاسب القانوني أن يفصح خطياً عن التزامه بهذه التعليمات.\nب- إذا لم يعين محاسب قانوني خارجي لتدقيق حسابات شركة التأمين خلال مدة لا تزيد على أربعة أشهر من بداية السنة المالية، فللبنك المركزي تعيين محاسب قانوني خارجي وتحديد أتعابه على نفقة شركة التأمين لتدقيق حساباتها.\nج- إذا اعتذر المحاسب القانوني الخارجي الذي تم انتخابه عن العمل أو عجز عن القيام به لأي سبب من الأسباب، فعلى مجلس إدارة شركة التأمين أن ينسب إلى البنك المركزي ثلاثة على الأقل من المحاسبين القانونيين الخارجيين ليختار البنك المركزي أحدهم وذلك خلال أربعة عشر يوما من تاريخ اعتذاره أو عجزه.\nد- للبنك المركزي، أن يعين محاسباً قانونياً خارجياً آخر لمراجعة حسابات شركة التأمين وتدقيقها إذا رأى ذلك ضروريا، ويحدد البنك المركزي المهمة الموكلة لهذا المحاسب القانوني ومدة عمله وأتعابه على نفقة شركة التأمين.","title":"المحاسب القانوني الخارجي لشركة التأمين","memo":"⭐ إذا لم يعين محاسب خارجي خلال مدة لا تزيد على أربعة أشهر من بداية السنة المالية يعينه البنك المركزي على نفقة الشركة.\n⭐ عند اعتذار المحاسب أو عجزه ينسب مجلس الإدارة ثلاثة على الأقل خلال أربعة عشر يوماً ليختار البنك المركزي أحدهم.\n⭐ للبنك المركزي تعيين محاسب آخر للمراجعة على نفقة الشركة.","qs":[{"q":"إذا لم يعين محاسب قانوني خارجي لتدقيق حسابات شركة التأمين خلال ... من بداية السنة المالية، فللبنك المركزي تعيينه:","o":["أربعة أشهر","شهرين","ستة أشهر","ثلاثة أشهر"],"a":0},{"q":"إذا اعتذر المحاسب القانوني الخارجي المنتخب عن العمل، فعلى مجلس إدارة شركة التأمين أن ينسب إلى البنك المركزي:","o":["ثلاثة على الأقل خلال أربعة عشر يوماً","اثنين على الأقل خلال ثلاثين يوماً","خمسة على الأقل خلال أربعة عشر يوماً","محاسباً واحداً خلال سبعة أيام"],"a":0},{"q":"أتعاب المحاسب القانوني الخارجي الذي يعينه البنك المركزي لمراجعة حسابات شركة التأمين تكون على نفقة:","o":["شركة التأمين","البنك المركزي","المساهمين الرئيسيين","الخزينة العامة"],"a":0}]},{"n":"33","chapter":"","notes":[],"source":"أ- يزود المحاسب القانوني الخارجي مجلس إدارة شركة التأمين والبنك المركزي بنسخ من التقرير السنوي لنتائج تدقيقه لحسابات شركة التأمين مبينا فيه الأوضاع المالية الحقيقية للشركة، وبأي معلومات أو بيانات إضافية عن أوضاع شركة التأمين وفق ما يقتضيه هذا القانون والانظمة والتعليمات الصادرة لهذه الغاية.\nب- على المحاسب القانوني الخارجي أن يقدم تقريراً فورياً إلى البنك المركزي ونسخة منه إلى رئيس مجلس إدارة شركة التأمين في أي من الحالات التالية:-\n١- إذا تبين له أن الوضع المالي للشركة لا يمكّنها من الوفاء بالتزاماتها تجاه المؤمن لهم أو سيعيق قدرتها على تلبية المتطلبات المالية المنصوص عليها في هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه.\n٢- إذا تبين له أن هناك خللاً جسيماً في ممارسة شركة التأمين لإجراءاتها المالية بما في ذلك تنظيم سجلاتها المحاسبية.\n٣- إذا رفض أو تحفظ على إصدار أي شهادة تتعلق بدخل شركة التأمين أو بياناتها المالية.\n٤- إذا قرر الاستقالة أو رفض إعادة تعيينه في شركة التأمين لأسباب غير عادية.\nج- للبنك المركزي أن يطلب من المحاسب القانوني الخارجي لشركة التأمين تزويده مباشرة وخلال مدة محددة بأي معلومات يراها ضرورية لمراقبة أعمال شركة التأمين.","title":"تقارير المحاسب القانوني الخارجي","memo":"⭐ يزود المحاسب مجلس الإدارة والبنك المركزي بنسخ من التقرير السنوي.\n⭐ يقدم تقريراً فورياً للبنك المركزي ونسخة لرئيس مجلس الإدارة إذا: عجز الوضع المالي عن الوفاء بالالتزامات، خلل جسيم في الإجراءات المالية، رفض أو تحفظ على شهادة، استقالته أو رفض إعادة تعيينه لأسباب غير عادية.","qs":[{"q":"يقدم المحاسب القانوني الخارجي تقريراً فورياً في الحالات المحددة في المادة (٣٣) إلى:","o":["البنك المركزي ونسخة منه إلى رئيس مجلس إدارة شركة التأمين","الهيئة العامة للمساهمين فقط","مراقب عام الشركات","وزير المالية ونسخة منه إلى البنك المركزي"],"a":0},{"q":"أي مما يلي لا يعد من الحالات التي توجب على المحاسب القانوني الخارجي تقديم تقرير فوري إلى البنك المركزي؟","o":["زيادة أرباح شركة التأمين عن السنة السابقة","وجود خلل جسيم في ممارسة الشركة لإجراءاتها المالية","رفضه أو تحفظه على إصدار شهادة تتعلق بالبيانات المالية للشركة","قراره الاستقالة لأسباب غير عادية"],"a":0},{"q":"للبنك المركزي أن يطلب من المحاسب القانوني الخارجي لشركة التأمين تزويده بأي معلومات يراها ضرورية:","o":["مباشرة وخلال مدة محددة","من خلال مجلس إدارة الشركة فقط","بعد موافقة الهيئة العامة","في نهاية السنة المالية فقط"],"a":0}]},{"n":"34","chapter":"","notes":[],"source":"يلتزم مجلس إدارة شركة التأمين بتقديم حساباته الختامية المصدقة والموقعة من المحاسب القانوني الخارجي إلى البنك المركزي خلال مدة لا تتجاوز شهرين من نهاية السنة المالية، كما يلتزم مجلس الادارة بالحصول على موافقة خطية مسبقة من البنك المركزي قبل توجيه الدعوة إلى المساهمين لاجتماع الهيئة العامة بشأنها أو عرضها على الهيئة العامة للمساهمين.","title":"تقديم الحسابات الختامية","memo":"⭐ يقدم مجلس الإدارة الحسابات الختامية المصدقة والموقعة من المحاسب الخارجي للبنك المركزي خلال مدة لا تتجاوز شهرين من نهاية السنة المالية.\n⭐ تلزم موافقة خطية مسبقة من البنك المركزي قبل دعوة الهيئة العامة بشأنها أو عرضها عليها.","qs":[{"q":"يلتزم مجلس إدارة شركة التأمين بتقديم حساباته الختامية المصدقة إلى البنك المركزي خلال مدة لا تتجاوز:","o":["شهرين من نهاية السنة المالية","أربعة أشهر من نهاية السنة المالية","ثلاثة أشهر من نهاية السنة المالية","شهراً من نهاية السنة المالية"],"a":0},{"q":"قبل توجيه الدعوة إلى المساهمين لاجتماع الهيئة العامة بشأن الحسابات الختامية، يجب على مجلس إدارة شركة التأمين:","o":["الحصول على موافقة خطية مسبقة من البنك المركزي","نشر الحسابات في صحيفتين يوميتين","الحصول على موافقة مراقب عام الشركات فقط","إعلام المؤمن لهم بها"],"a":0}]},{"n":"35","chapter":"","notes":[],"source":"أ- يحظر على شركة التأمين توزيع أي أرباح على المساهمين إلا بموافقة مسبقة من البنك المركزي، ولا يجوز للهيئة العامة لمساهمي شركة التأمين أن تقرر توزيع أي أرباح نقدية أو عينية على المساهمين إلا في حدود ما وافق عليه البنك المركزي.\nب- لا يجوز للشركة أن توزع أرباحاً على المساهمين قبل تغطية كامل المصاريف التأسيسية والمصاريف التي لا تقابلها موجودات حقيقية وقبل إطفاء أي خسائر لحقت بها مهما كان نوعها، وتجوز بموافقة البنك المركزي تغطية تلك المصاريف وإطفاء هذه الخسائر خلال مدة لا تزيد على خمس سنوات.","title":"توزيع الأرباح","memo":"⭐ يحظر توزيع أي أرباح إلا بموافقة مسبقة من البنك المركزي وفي حدود ما وافق عليه.\n⭐ لا توزع أرباح قبل تغطية المصاريف التأسيسية والمصاريف التي لا تقابلها موجودات حقيقية وإطفاء الخسائر.\n⭐ يجوز بموافقة البنك المركزي التغطية والإطفاء خلال مدة لا تزيد على خمس سنوات.","qs":[{"q":"لا يجوز لشركة التأمين توزيع أي أرباح على المساهمين إلا:","o":["بموافقة مسبقة من البنك المركزي","بقرار من مجلس إدارتها فقط","بعد مرور سنتين على الترخيص","بموافقة لاحقة من المحافظ"],"a":0},{"q":"يجوز بموافقة البنك المركزي تغطية المصاريف التأسيسية وإطفاء الخسائر خلال مدة لا تزيد على:","o":["خمس سنوات","ثلاث سنوات","سنتين","عشر سنوات"],"a":0},{"q":"حالة عملية: شركة تأمين حققت أرباحاً هذا العام ولديها خسائر متراكمة من سنوات سابقة لم تطفأ، فإنها:","o":["لا يجوز لها توزيع أرباح قبل إطفاء تلك الخسائر","يجوز لها توزيع الأرباح كاملة","يجوز لها توزيع نصف الأرباح فقط","يجوز لها التوزيع بقرار من الهيئة العامة دون موافقة البنك المركزي"],"a":0}]},{"n":"36","chapter":"","notes":[],"source":"أ- مع مراعاة أحكام المادة (٣٤) من هذا القانون، يلتزم مجلس إدارة شركة التأمين بعد مصادقة الهيئــــة العامة للمساهمين على بياناتها المالية الختامية عن السنة المالية المنتهية بما يلي:-\n١- نشر بياناتها المالية الختامية وتقرير المحاسب القانوني الخارجي في صحيفتين يوميتين محليتين الأوسع انتشارا خلال مدة لا تتجاوز اسبوعين من تاريخ المصادقة عليها ونشر بياناتها المالية الاجمالية وبياناتها المالية الختامية في المملكة إذا كان لها فروع خارجها.\n٢- عرض تلك البيانات مع قائمة بأسماء أعضاء مجلس إدارتها على موقعها الإلكتروني ولمدة ثلاثة أشهر على الأقل خلال السنة المالية التالية للسنة المالية المنتهية.\nب- على فرع شركة التأمين الأجنبية أن ينشر البيانات المالية الختامية الاجمالية للشركة الام وفروعها خارج المملكة، إلى جانب البيانات المالية الخاصة به داخل المملكة.","title":"نشر البيانات المالية الختامية","memo":"⭐ بعد مصادقة الهيئة العامة: النشر في صحيفتين يوميتين محليتين الأوسع انتشاراً خلال مدة لا تتجاوز أسبوعين.\n⭐ العرض على الموقع الإلكتروني مع أسماء أعضاء مجلس الإدارة لمدة ثلاثة أشهر على الأقل.\n⭐ فرع الشركة الأجنبية ينشر البيانات الإجمالية للشركة الأم وفروعها إلى جانب بياناته.","qs":[{"q":"تنشر شركة التأمين بياناتها المالية الختامية وتقرير المحاسب القانوني الخارجي في صحيفتين يوميتين محليتين خلال مدة لا تتجاوز:","o":["أسبوعين من تاريخ مصادقة الهيئة العامة عليها","شهرين من نهاية السنة المالية","شهراً من تاريخ مصادقة الهيئة العامة عليها","ثلاثة أيام من تاريخ مصادقة الهيئة العامة عليها"],"a":0},{"q":"تعرض شركة التأمين بياناتها المالية مع قائمة بأسماء أعضاء مجلس إدارتها على موقعها الإلكتروني لمدة لا تقل عن:","o":["ثلاثة أشهر","شهر","ستة أشهر","سنة"],"a":0},{"q":"على فرع شركة التأمين الأجنبية أن ينشر:","o":["البيانات المالية الختامية الإجمالية للشركة الأم وفروعها إلى جانب بياناته داخل المملكة","بياناته المالية داخل المملكة فقط","البيانات المالية للشركة الأم فقط","ملخصاً عن أرباحه دون البيانات الختامية"],"a":0}]},{"n":"37","chapter":"","notes":[],"source":"أ- تخضع شركة التأمين وأي شركة تابعة لها للتفتيش من البنك المركزي أو المحاسبين القانونيين الذين يعينهم البنك المركزي لهذه الغاية على نفقة شركة التأمين، وتلتزم شركة التأمين والشركات التابعة لها بالتعاون معهم بما يمكنهم من القيام بأعمالهم وفق الأصول.\nب- إذا كانت شركة التأمين المراد التفتيش عليها فرعا أو شركة تابعة لشركة تأمين أجنبية، فإنها تخضع لتفتيش الجهات المسؤولة عن الرقابة والإشراف عليها في بلد مقرها الرئيسي أو الإقليمي وفقاً لتعليمات تصدر لهذه الغاية.\nج- للبنك المركزي والمحاسبين القانونيين المعينين منه أثناء تفتيشهم على شركة التأمين وأي شركة تابعة لها القيام بأعمال التفتيش وفق تعليمات تصدر لهذه الغاية.\nد- للبنك المركزي أن يصدر التعليمات التي تمكن مفتشيه ومندوبيه من زيارة مكاتب شركة التأمين وأي شركة تابعة لها وفحص حساباتها وسجلاتها ووثائقها واتخاذ الإجراءات التي يراها ضرورية للتحقق من أن أعمالها وأنشطتها لا تتعارض مع أحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه.","title":"التفتيش على شركات التأمين","memo":"⭐ تخضع الشركة وشركاتها التابعة للتفتيش من البنك المركزي أو المحاسبين الذين يعينهم على نفقة شركة التأمين.\n⭐ الفرع أو التابعة لشركة أجنبية يخضع أيضاً لتفتيش جهات الرقابة في بلد مقرها الرئيسي أو الإقليمي.\n⭐ للبنك المركزي إصدار تعليمات تمكن مفتشيه من زيارة المكاتب وفحص الحسابات والسجلات.","qs":[{"q":"نفقات التفتيش على شركة التأمين الذي يجريه المحاسبون القانونيون المعينون من البنك المركزي تكون على:","o":["نفقة شركة التأمين","نفقة البنك المركزي","نفقة المساهمين الرئيسيين","نفقة الخزينة العامة"],"a":0},{"q":"يخضع فرع شركة التأمين الأجنبية في المملكة لتفتيش الجهات المسؤولة عن الرقابة عليه في:","o":["بلد مقرها الرئيسي أو الإقليمي","أي دولة يختارها الفرع","الدولة التي يقيم فيها المدير المفوض","الدولة التي يحمل جنسيتها أكبر المساهمين"],"a":0},{"q":"تشمل رقابة التفتيش من البنك المركزي:","o":["شركة التأمين وأي شركة تابعة لها","شركة التأمين دون شركاتها التابعة","الشركات التابعة الأجنبية فقط","المؤمن لهم والمستفيدين"],"a":0}]},{"n":"38","chapter":"","notes":[],"source":"للبنك المركزي وعلى نفقة شركة التأمين، تكليف أي خبير أو مستشار أو اكتواري لتقييم أي جوانب تتعلق بأعمال شركة التأمين أو أعمال أي شركة تابعة لها أو أعمال أي شخص أو جهة خاضعة لرقابة البنك المركزي وفق أحكام هذا القانون ، وعلى كل من هذه الجهات التعاون الكامل معه لتمكينه من القيام بمهامه بما في ذلك السماح له بالاطلاع على أي سجلات أو وثائق أو بيانات يطلبها لغايات إعداد تقريره.","title":"تكليف خبير لتقييم أعمال شركة التأمين","memo":"⭐ للبنك المركزي تكليف خبير أو مستشار أو اكتواري لتقييم أعمال شركة التأمين أو شركاتها التابعة أو أي جهة خاضعة لرقابته\n⭐ يكون التكليف على نفقة شركة التأمين\n⭐ على الجهات التعاون الكامل معه والسماح له بالاطلاع على السجلات والوثائق والبيانات","qs":[{"q":"على نفقة من يتم تكليف الخبير أو المستشار أو الاكتواري لتقييم جوانب أعمال شركة التأمين؟","o":["شركة التأمين","البنك المركزي","وزارة الصناعة والتجارة","صندوق ضمان حقوق المؤمن لهم"],"a":0},{"q":"الجهة التي لها صلاحية تكليف خبير أو اكتواري لتقييم أي جوانب تتعلق بأعمال شركة التأمين هي:","o":["البنك المركزي","الهيئة العامة لشركة التأمين","مجلس إدارة شركة التأمين","مراقب الشركات"],"a":0},{"q":"كلّف البنك المركزي اكتوارياً لتقييم أعمال شركة تابعة لشركة تأمين، فإن على هذه الشركة التابعة:","o":["التعاون الكامل معه والسماح له بالاطلاع على أي سجلات أو وثائق أو بيانات يطلبها","الاكتفاء بتزويده بالبيانات المالية المنشورة فقط","رفض التعاون لأنها ليست شركة تأمين","طلب موافقة هيئتها العامة قبل السماح له بالاطلاع"],"a":0}]},{"n":"39","chapter":"","notes":[],"source":"أ- تسري على اندماج شركات التأمين الأحكام المتعلقة باندماج الشركات الواردة في قانون الشركات وذلك فيما لم يرد عليه نص خاص في هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه.\nب- تحدد طرق اندماج شركات التأمين حسب نوع التأمين بموجب تعليمات تصدر لهذه الغاية.","title":"أحكام اندماج شركات التأمين","memo":"⭐ يسري على اندماج شركات التأمين قانون الشركات فيما لم يرد عليه نص خاص في قانون التأمين وأنظمته وتعليماته\n⭐ تحدد طرق الاندماج حسب نوع التأمين بموجب تعليمات","qs":[{"q":"تسري على اندماج شركات التأمين الأحكام الواردة في قانون الشركات:","o":["فيما لم يرد عليه نص خاص في قانون تنظيم أعمال التأمين والأنظمة والتعليمات الصادرة بمقتضاه","بشكل مطلق ولو تعارضت مع قانون تنظيم أعمال التأمين","في حالة اندماج شركات التأمين الأجنبية فقط","بعد موافقة مراقب الشركات على تطبيقها"],"a":0},{"q":"تحدد طرق اندماج شركات التأمين حسب نوع التأمين بموجب:","o":["تعليمات تصدر لهذه الغاية","نظام يصدره مجلس الوزراء","قرار من الهيئة العامة غير العادية","اتفاق بين الشركات الراغبة بالاندماج"],"a":0}]},{"n":"40","chapter":"","notes":[],"source":"أ- لا يجوز لشركة التأمين أن تشرع في أي اجراء من اجراءات الاندماج قبل الحصول على موافقة خطية مسبقة من البنك المركزي وضمن الضوابط والشروط التي يحددها لهذه الغاية.\nب- يعين البنك المركزي الخبراء والمختصين في لجنة التقدير التي تشكل وفقاً لأحكام قانون الشركات لإتمام عملية الاندماج.","title":"موافقة البنك المركزي على الاندماج","memo":"⭐ لا يجوز البدء بأي إجراء من إجراءات الاندماج قبل موافقة خطية مسبقة من البنك المركزي وضمن ضوابطه وشروطه\n⭐ البنك المركزي يعين الخبراء والمختصين في لجنة التقدير المشكلة وفق قانون الشركات","qs":[{"q":"لا يجوز لشركة التأمين أن تشرع في أي إجراء من إجراءات الاندماج قبل الحصول على:","o":["موافقة خطية مسبقة من البنك المركزي","موافقة لاحقة من مراقب الشركات","قرار من المحكمة الإدارية","موافقة المؤمن لهم والمستفيدين"],"a":0},{"q":"من يعين الخبراء والمختصين في لجنة التقدير التي تشكل لإتمام عملية اندماج شركات التأمين؟","o":["البنك المركزي","مراقب الشركات","مجلس إدارة الشركة الدامجة","الهيئة العامة للشركة المندمجة"],"a":0},{"q":"بدأت شركة تأمين بإجراءات الاندماج مع شركة أخرى ثم تقدمت لاحقاً للبنك المركزي بطلب الموافقة، فإن ذلك:","o":["مخالف للقانون لأن الموافقة يجب أن تكون خطية ومسبقة","صحيح ما دام الطلب قُدم قبل إتمام الاندماج","صحيح إذا وافقت الهيئة العامة للشركتين","لا يتطلب موافقة البنك المركزي أصلاً"],"a":0}]},{"n":"41","chapter":"","notes":[],"source":"أ- مع مراعاة أحكام قانون الشركات، تنتقل حكماً إلى شركة التأمين الدامجة أو الناتجة من الاندماج جميع الالتزامات والمطلوبات والموجودات القائمة لدى شركة التأمين المندمجة، دون حاجة للحصول على موافقة المؤمن لهم أو المستفيدين أو أي شخص آخر.\nب- تحل شركة التأمين الدامجة أو الناتجة من الاندماج محل شركة التأمين المندمجة في جميع الامور والإجراءات بما في ذلك الدعاوى والإجراءات القضائية المقامة منها أو ضدها وتعتبر خلفا قانونيا وواقعيا للشركة المندمجة .","title":"آثار الاندماج على الالتزامات والدعاوى","memo":"⭐ تنتقل حكماً للشركة الدامجة أو الناتجة جميع الالتزامات والمطلوبات والموجودات للشركة المندمجة دون حاجة لموافقة المؤمن لهم أو المستفيدين أو أي شخص آخر\n⭐ تحل الدامجة أو الناتجة محل المندمجة في جميع الأمور بما فيها الدعاوى المقامة منها أو ضدها\n⭐ تعتبر خلفاً قانونياً وواقعياً للشركة المندمجة","qs":[{"q":"تنتقل الالتزامات والمطلوبات والموجودات القائمة لدى شركة التأمين المندمجة إلى الشركة الدامجة:","o":["حكماً دون حاجة للحصول على موافقة المؤمن لهم أو المستفيدين أو أي شخص آخر","بعد الحصول على موافقة المؤمن لهم والمستفيدين","بعد الحصول على موافقة دائني الشركة المندمجة","بموجب حكم قضائي يصدر عن محكمة بداية عمان"],"a":0},{"q":"تعتبر شركة التأمين الدامجة أو الناتجة من الاندماج بالنسبة للشركة المندمجة:","o":["خلفاً قانونياً وواقعياً لها","كفيلاً متضامناً لالتزاماتها فقط","شخصاً مستقلاً لا علاقة له بدعاواها","مصفياً لموجوداتها"],"a":0},{"q":"كانت هناك دعوى مقامة ضد شركة تأمين اندمجت لاحقاً في شركة أخرى، فإن الدعوى:","o":["تستمر وتحل الشركة الدامجة محل الشركة المندمجة فيها","تسقط بحكم القانون بسبب زوال الشركة المندمجة","توقف لحين موافقة البنك المركزي","تحال إلى المحكمة الإدارية"],"a":0}]},{"n":"42","chapter":"","notes":[],"source":"أ- للبنك المركزي أن يتخذ أيا من الإجراءات أو أن يفرض أيا من العقوبات المنصوص عليها في الفقرة (ب) من هذه المادة في الحالات التالية:-\n١- مخالفة شركة التأمين أو أي من أعضاء مجلس إدارتها أو موظفيها لأحكام هذا القانون أو أي من الأنظمة والتعليمات والقرارات الصادرة بمقتضاه.\n٢- قيام شركة التأمين أو إحدى الشركات التابعة لها أو أي من أعضاء مجلس إدارتها أو موظفيها بعمليات أو ممارسات غير سليمة أو غير آمنة للشركة أو للمؤمن لهم.\nب- تنفيذاً لأحكام الفقرة (أ) من هذه المادة، للبنك المركزي وبمراعاة التناسب في العقوبة أن يتخذ إجراء أو أكثر أو يفرض عقوبة أو أكثر أو كليهما مما يلي :-\n١- توجيه تنبيه خطي لشركة التأمين.\n٢- الطلب من شركة التأمين تقديم خطة مناسبة لما سيتخذ من إجراءات لإزالة المخالفة وتصويب الوضع.\n٣- منع شركة التأمين من إبرام عقود تأمين إضافية.\n٤- وضع حد أعلى لمجموع مبالغ الأقساط التي تحصل عليها شركة التأمين من عقود التأمين التي تصدرها.\n٥- الاحتفاظ في المملكة بموجودات تعادل في قيمتها جميع التزاماتها الصافية الناشئة عن أعمالها في المملكة أو نسبة معينة من قيمتها.\n٦- تقييد شركة التأمين في ممارسة أي من أنشطتها الاستثمارية أو تصفية استثماراتها.\n٧- منع شركة التأمين من التصرف في موجوداتها أو تحويل أي موجودات أو أموال لها إلى خارج المملكة.\n٨- تحديد أنشطة أي من الشركات التابعة لها وأعمالها وتحديـــد أوجه التملك في تلك الشركات.\n٩- فرض غرامة على شركة التأمين لا تقل عن ألف دينار ولا تزيد على مائتي الف دينار وتضاعف عند التكرار وفقاً لأحكام التعليمات الصادرة لهذه الغاية.\n١٠- الطلب من شركة التأمين حرمان أي من أعضاء مجلس ادارتها أو موظفيها من استحقاقاته من مكافآت وبدلات.\n١١- الطلب من شركة التأمين، أو المركز الرئيسي لفرع شركة التأمين الأجنبية حسب مقتضى الحال، اتخاذ الإجراءات اللازمة لتصويب الأوضاع الإدارية فيها بما في ذلك تنحية المدير العام أو المدير المفوض أو أي موظف فيها.\n١٢- تنحية رئيس مجلس إدارة شركة التأمين أو أي من أعضائه.\n١٣- تنحية المدير المفوض وتعيين لجنة إدارية مؤقتة من ذوي الخبرة يحدد البنك المركزي صلاحياتها وأتعابها والتي تتحملها شركة التأمين لمدة لا تتجاوز ستة أشهر قابلة للتمديد لمدة لا تتجاوز في مجموعهما السنة في الحالات التي تستدعي ذلك .\n١٤- حل مجلس إدارة شركة التأمين وتولي إدارتها من البنك المركزي أو من قبل لجنة مؤقتة من ذوي الخبرة يحدد البنك المركزي صلاحياتها وأتعابها على نفقة شركة التأمين وذلك لمدة لا تتجاوز ستة أشهر قابلة للتمديد لمدة لا تتجاوز في مجموعهما السنة في الحالات التي تستدعي ذلك.\n١٥- الطلب من شركة التأمين رفع دعوى ضد أي من أعضاء مجلس ادارتها أو موظفيها.\n١٦- وقف أو إلغاء ترخيص شركة التأمين أو ترخيص ممارسة فرع معين أو أكثر من فروع التأمين.\nج- للمحافظ اتخاذ أي من القرارات الخاصة بالإجراءات أو العقوبات الواردة في البنود من (٨-١) من الفقرة (ب) من هذه المادة وللمجلس اتخاذ أي من القرارات الخاصة بالإجراءات أو العقوبات الــواردة فـي البنود مـن (١٦-٩) من تلك الفقرة.","title":"الإجراءات والعقوبات على شركة التأمين","memo":"⭐ حالاتها: مخالفة القانون أو الأنظمة والتعليمات، أو ممارسات غير سليمة أو غير آمنة\n⭐ غرامة لا تقل عن ١٠٠٠ دينار ولا تزيد على ٢٠٠ ألف دينار وتضاعف عند التكرار\n⭐ اللجنة الإدارية المؤقتة أو حل المجلس: مدة لا تتجاوز ٦ أشهر قابلة للتمديد بمجموع لا يتجاوز السنة\n⭐ المحافظ: البنود (١-٨)، المجلس: البنود (٩-١٦)","qs":[{"q":"الحد الأعلى للغرامة التي يجوز للبنك المركزي فرضها على شركة التأمين وفق المادة (٤٢) قبل المضاعفة عند التكرار هو:","o":["مائتا ألف دينار","مائة ألف دينار","خمسون ألف دينار","خمسمائة ألف دينار"],"a":0},{"q":"مدة اللجنة المؤقتة التي تتولى إدارة شركة التأمين عند حل مجلس إدارتها وفق المادة (٤٢) لا تتجاوز:","o":["ستة أشهر قابلة للتمديد لمدة لا تتجاوز في مجموعهما السنة","ثلاثة أشهر قابلة للتمديد لمدة مماثلة","سنة قابلة للتمديد لسنة أخرى","سنتين غير قابلتين للتمديد"],"a":0},{"q":"أي من الإجراءات التالية يختص المحافظ باتخاذ القرار بشأنه وفق المادة (٤٢)؟","o":["منع شركة التأمين من إبرام عقود تأمين إضافية","فرض غرامة على شركة التأمين","تنحية رئيس مجلس إدارة شركة التأمين","إلغاء ترخيص شركة التأمين"],"a":0},{"q":"جميع ما يلي من الإجراءات أو العقوبات التي يتخذها المجلس وفق المادة (٤٢) باستثناء:","o":["توجيه تنبيه خطي لشركة التأمين","حل مجلس إدارة شركة التأمين","وقف ترخيص ممارسة فرع من فروع التأمين","الطلب من شركة التأمين رفع دعوى ضد أي من موظفيها"],"a":0}]},{"n":"43","chapter":"","notes":[],"source":"يترتب على قرار وقف الترخيص أو إلغائه لفرع أو أكثر من فروع التأمين وفقاً لأحكام البند (١٦) من الفقرة (ب) من المادة (٤٢) من هذا\nالقانون ما يلي : -\nأ- منع شركة التأمين من إبرام عقود التأمين في ذلك الفرع.\nب- بقاء جميع الحقوق والالتزامات الناشئة عن عقود أبرمت قبل وقف الترخيص أو إلغائه صحيحة وسارية المفعول واستمرار مسؤولية شركة التأمين عنها.","title":"آثار وقف أو إلغاء ترخيص فرع تأمين","memo":"⭐ منع الشركة من إبرام عقود تأمين في ذلك الفرع\n⭐ بقاء الحقوق والالتزامات الناشئة عن عقود أبرمت قبل الوقف أو الإلغاء صحيحة وسارية واستمرار مسؤولية الشركة عنها","qs":[{"q":"يترتب على قرار وقف ترخيص فرع من فروع التأمين لشركة التأمين:","o":["منعها من إبرام عقود التأمين في ذلك الفرع","منعها من إبرام عقود التأمين في جميع الفروع","فسخ عقود ذلك الفرع المبرمة قبل الوقف","تصفية الشركة حكماً"],"a":0},{"q":"أُلغي ترخيص فرع التأمين على الحياة لدى شركة تأمين، فإن العقود التي أبرمتها في ذلك الفرع قبل الإلغاء:","o":["تبقى صحيحة وسارية المفعول وتستمر مسؤولية الشركة عنها","تنفسخ حكماً من تاريخ الإلغاء","تنتقل حكماً إلى صندوق ضمان حقوق المؤمن لهم","تبقى سارية لمدة ثلاثة أشهر فقط"],"a":0}]},{"n":"44","chapter":"","notes":[],"source":"إذا تعرضت شركة التأمين لأوضاع إدارية غير سليمة أو اشكالات ذات أثر جوهري في مركزها المالي أو في حقوق المؤمن لهم أو المستفيدين، فعلى رئيس مجلس إدارة شركة التأمين أو أي عضو فيه أو مديرها العام إعلام البنك المركزي فورا، وذلك تحت طائلة المسؤولية في حال عدم التبليغ عن ذلك.","title":"واجب إعلام البنك المركزي بالأوضاع غير السليمة","memo":"⭐ عند الأوضاع الإدارية غير السليمة أو الإشكالات ذات الأثر الجوهري في المركز المالي أو حقوق المؤمن لهم\n⭐ على رئيس مجلس الإدارة أو أي عضو فيه أو المدير العام إعلام البنك المركزي فوراً تحت طائلة المسؤولية","qs":[{"q":"إذا تعرضت شركة التأمين لإشكالات ذات أثر جوهري في مركزها المالي، فعلى رئيس مجلس إدارتها أو أي عضو فيه أو مديرها العام إعلام البنك المركزي:","o":["فوراً","خلال سبعة أيام","خلال ثلاثين يوماً","مع البيانات المالية السنوية"],"a":0},{"q":"الجهة التي يجب إعلامها عند تعرض شركة التأمين لأوضاع إدارية غير سليمة هي:","o":["البنك المركزي","الهيئة العامة للشركة","مراقب الشركات","مدقق حسابات الشركة"],"a":0}]},{"n":"45","chapter":"","notes":[],"source":"أ- للمجلس في حال تعرّض شركة التأمين لأوضاع غير سليمة أو غير آمنة أو لاشكالات ذات أثر جوهري في مركزها المالي أو في حقوق المؤمن لهم أو المستفيدين أن يتخذ إجراء حل مجلس إدارة شركة التأمين وتشكيل لجنة مؤقتة من ذوي الخبرة ويحدد صلاحياتها وتكون أتعابها على نفقة شركة التأمين وذلك لمدة لا تتجاوز ستة أشهر قابلة للتمديد لمدة لا تتجاوز السنة في الحالات التي تستدعي ذلك ويكون لها ما يلي:-\n١- استعمال أي من عناصر رأس مال شركة التأمين لتقوية الوضع المالي لها بما في ذلك زيادة رأسمالها أو بتخفيض رأسمالها المكتتب به وزيادته بالاكتتاب بأسهم جديدة أو باستعمال الاحتياطيات الاختيارية أو الأرباح المدورة أو بأي وسيلة أخرى يراها البنك المركزي مناسبة.\n٢- تحويل جميع أو بعض التزامات ومطلوبات وموجودات شركة التأمين إلى شركة تأمين أخرى بموافقة الأخيرة ودونما حاجة للحصول على موافقة المؤمن لهم أو المستفيدين أو مديني شركة التأمين.\n٣- إعادة هيكلة ديون شركة التأمين وتنظيم أمورها المالية المتعثرة بالتفاوض مع دائنيها لغايات تخفيض مديونية شركة التأمين، إن لزم، ووضع خطط لتسديدها.\n٤- اتخاذ الإجراءات اللازمة لإدماج شركة التأمين في شركة تأمين أخرى بموافقة شركة التأمين التي ستندمج فيها.\nب- تكون القرارات والموافقات التي يصدرها البنك المركزي وفق أحكام البنود من (١) الى (٤) من الفقرة (أ) من هذه المادة بمثابة القرارات اللازم صدورها بمقتضى أحكام التشريعات النافذة عن مجلس إدارة شركة التأمين وهيئتها العامة العادية وهيئتها العامة غير العادية لغايات تنفيذ الإجراءات المنصوص عليها في تلك الفقرة.\nج- لا يترتب على صدور القرار وفق أحكام الفقرة (أ) من هذه المادة منع شركة التأمين من ممارسة أعمالها ما لم يصدر قرار عن البنك المركزي بخلاف ذلك.","title":"معالجة أوضاع شركة التأمين المتعثرة","memo":"⭐ للمجلس حل مجلس إدارة الشركة وتشكيل لجنة مؤقتة على نفقة الشركة لمدة لا تتجاوز ٦ أشهر قابلة للتمديد لمدة لا تتجاوز السنة\n⭐ صلاحياتها: استعمال عناصر رأس المال، تحويل الالتزامات والموجودات لشركة أخرى بموافقتها دون موافقة المؤمن لهم، إعادة هيكلة الديون، الإدماج\n⭐ قرارات البنك المركزي بمثابة قرارات مجلس الإدارة والهيئة العامة العادية وغير العادية\n⭐ لا يترتب على القرار منع الشركة من ممارسة أعمالها ما لم يقرر البنك المركزي خلاف ذلك","qs":[{"q":"الجهة المختصة بحل مجلس إدارة شركة التأمين وتشكيل لجنة مؤقتة عند تعرضها لأوضاع غير آمنة وفق المادة (٤٥) هي:","o":["المجلس","المحافظ","الهيئة العامة غير العادية للشركة","المحكمة الإدارية"],"a":0},{"q":"يشترط لتحويل جميع أو بعض التزامات وموجودات شركة التأمين المتعثرة إلى شركة تأمين أخرى وفق المادة (٤٥):","o":["موافقة شركة التأمين الأخرى","موافقة المؤمن لهم والمستفيدين","موافقة مديني شركة التأمين","موافقة الهيئة العامة لشركة التأمين المتعثرة"],"a":0},{"q":"تكون القرارات التي يصدرها البنك المركزي لمعالجة أوضاع شركة التأمين وفق البنود (١-٤) من الفقرة (أ) من المادة (٤٥):","o":["بمثابة القرارات اللازم صدورها عن مجلس إدارة الشركة وهيئتها العامة العادية وغير العادية","نافذة بعد مصادقة الهيئة العامة غير العادية عليها","توصيات غير ملزمة لمجلس إدارة الشركة","نافذة بعد مصادقة مراقب الشركات عليها"],"a":0},{"q":"صدر قرار بحل مجلس إدارة شركة تأمين وتشكيل لجنة مؤقتة وفق المادة (٤٥)، ولم يصدر قرار آخر عن البنك المركزي، فإن الشركة:","o":["تستمر في ممارسة أعمالها","تمنع من ممارسة أعمالها حكماً","توقف عن إبرام عقود جديدة حكماً","تعتبر تحت التصفية"],"a":0}]},{"n":"46","chapter":"","notes":[],"source":"إذا تقرر اتخاذ أي من الاجراءات أو العقوبات وفقاً لأحكام المادتين (٤٢) و(٤٥) من هذا القانون، فتراعى الأحكام التالية:-\nأ- لكل ذي مصلحة الطعن في ذلك القرار أمام المحكمة الإدارية خلال ثلاثين يوما من صدوره.\nب- إن صدور ذلك القرار لا يمنع من قيام المسؤولية المدنية والجزائية وفقاً لأحكام التشريعات النافذة.\nج- لا يترتب على الطعن وفقا لأحكام هذه المادة وقف تنفيذ القرار، ما لم تقرر المحكمة خلاف ذلك .","title":"الطعن في قرارات الإجراءات والعقوبات","memo":"⭐ لكل ذي مصلحة الطعن أمام المحكمة الإدارية خلال ٣٠ يوماً من صدور القرار\n⭐ القرار لا يمنع قيام المسؤولية المدنية والجزائية\n⭐ الطعن لا يوقف تنفيذ القرار ما لم تقرر المحكمة خلاف ذلك","qs":[{"q":"يجوز لكل ذي مصلحة الطعن في قرار اتخاذ الإجراءات أو العقوبات وفق المادتين (٤٢) و(٤٥) أمام:","o":["المحكمة الإدارية خلال ثلاثين يوماً من صدوره","محكمة بداية عمان خلال ثلاثين يوماً من صدوره","المحكمة الإدارية خلال ستين يوماً من نشره","محكمة الاستئناف خلال خمسة عشر يوماً من تبليغه"],"a":0},{"q":"يترتب على الطعن في قرار العقوبة الصادر بحق شركة التأمين وفق المادة (٤٦):","o":["عدم وقف تنفيذ القرار ما لم تقرر المحكمة خلاف ذلك","وقف تنفيذ القرار حكماً لحين البت في الطعن","وقف تنفيذ القرار إذا قدمت الشركة كفالة","وقف تنفيذ القرار بقرار من المحافظ"],"a":0},{"q":"صدر قرار بفرض عقوبة على شركة تأمين، فإن صدور هذا القرار:","o":["لا يمنع من قيام المسؤولية المدنية والجزائية وفق التشريعات النافذة","يمنع من ملاحقة الشركة جزائياً عن الفعل ذاته","يعفي أعضاء مجلس الإدارة من المسؤولية المدنية","يحول دون مطالبة المتضررين بالتعويض"],"a":0}]},{"n":"47","chapter":"","notes":[],"source":"أ- لا تسري على فرع شركة التأمين الأجنبية المرخص له بالعمل في المملكة أي قرارات أو إجراءات صادرة عن السلطات المختصة في الدولة التي يقع فيها مركز إدارتها الرئيسي سواء تعلقت تلك القرارات بالإفلاس أو بالإعسار أو التصفية أو معالجة أوضاع شركة التأمين المتعثرة.\nب- للبنك المركزي، وبعد التحقق من أن أيا من الإجراءات المنصوص عليها في الفقرة (أ) من هذه المادة غير مجحف بحق المؤمن لهم أو المستفيدين أو المتعاملين مع فرع شركة التأمين الأجنبية في المملكة ولا يؤثر على استقرار قطاع التأمين فيها، أن يوافق على امتداد الآثار المترتبة على تلك الإجراءات لتشمل فرع شركة التأمين الأجنبية في المملكة وفق الترتيبات التي يحددها البنك المركزي بالطريقة التي يراها مناسبة.\nج- تطبق أحكام هذه المادة على الشركة التابعة لشركة التأمين الأجنبية بقدر انطباقها عليها.","title":"قرارات الدولة الأم بشأن فرع الشركة الأجنبية","memo":"⭐ لا تسري على فرع الشركة الأجنبية في المملكة قرارات سلطات دولة المركز الرئيسي (الإفلاس، الإعسار، التصفية، معالجة التعثر)\n⭐ للبنك المركزي الموافقة على امتداد آثارها للفرع بعد التحقق من عدم الإجحاف بالمؤمن لهم وعدم التأثير على استقرار القطاع\n⭐ تطبق على الشركة التابعة للشركة الأجنبية بقدر انطباقها","qs":[{"q":"صدر قرار بإفلاس شركة تأمين أجنبية عن السلطات المختصة في دولة مركزها الرئيسي، فإن هذا القرار بالنسبة لفرعها المرخص في المملكة:","o":["لا يسري عليه إلا إذا وافق البنك المركزي على امتداد آثاره","يسري عليه حكماً من تاريخ صدوره","يسري عليه بعد تصديقه من محكمة بداية عمان","يسري عليه بعد موافقة مراقب الشركات"],"a":0},{"q":"يشترط لموافقة البنك المركزي على امتداد آثار إجراءات دولة المركز الرئيسي لفرع شركة التأمين الأجنبية التحقق من أنها:","o":["غير مجحفة بحق المؤمن لهم أو المستفيدين أو المتعاملين مع الفرع ولا تؤثر على استقرار قطاع التأمين","صادرة بحكم قضائي قطعي","تتعلق بالإفلاس فقط دون التصفية","موافق عليها من الهيئة العامة للشركة الأم"],"a":0},{"q":"تطبق أحكام المادة (٤٧) المتعلقة بقرارات سلطات الدولة الأم كذلك على:","o":["الشركة التابعة لشركة التأمين الأجنبية بقدر انطباقها عليها","وكلاء التأمين الأفراد","شركات إعادة التأمين الأردنية","وسطاء التأمين المحليين"],"a":0}]},{"n":"48","chapter":"","notes":[],"source":"أ- لغايات تنفيذ أحكام البند (٣) من الفقرة (أ) من المادة (٤٥) من هذا القانون، يشكل المجلس لجنة لإعادة هيكلة ديون شركة التأمين من ذوي الخبرة والاختصاص لا يزيد أعضاؤها على خمسة أعضاء لمدة سنة من تاريخ صدور القرار بإعادة هيكلة الديون قابلة للتمديد، على أن تتحمل شركة التأمين أتعاب تلك اللجنة.\nب- للبنك المركزي تفويض لجنة إعادة هيكلة ديون شركة التأمين بأن تتخذ باسم شركة التأمين الإجراءات اللازمة جميعها لإنجاز إعادة هيكلة الديون ولا يجوز لهذه اللجنة دون الحصول على موافقة مسبقة من البنك المركزي القيام، تحت طائلة البطلان، بأي تصرف يؤثر على مصالح دائني شركة التأمين بما في ذلك أي بيع يخرج عن نطاق ممارسة الأعمال المعتادة للشركة أو الهبة أو الاقتراض أو الإقراض أو إصدار الكفالات أو إجراء أي رهن أو أي من التصرفات المماثلة الأخرى.\nج- تتم اجراءات إعادة هيكلة الديون وسائر الامور المتعلقة بها وفق نظام يصدر لهذه الغاية.","title":"لجنة إعادة هيكلة ديون شركة التأمين","memo":"⭐ يشكلها المجلس من ذوي الخبرة، لا يزيد أعضاؤها على ٥، لمدة سنة من تاريخ قرار إعادة الهيكلة قابلة للتمديد، وأتعابها على الشركة\n⭐ لا يجوز لها دون موافقة مسبقة من البنك المركزي، تحت طائلة البطلان، أي تصرف يؤثر على مصالح الدائنين (بيع خارج الأعمال المعتادة، هبة، اقتراض، إقراض، كفالات، رهن)\n⭐ إجراءات إعادة الهيكلة تنظم بنظام","qs":[{"q":"الحد الأعلى لعدد أعضاء لجنة إعادة هيكلة ديون شركة التأمين هو:","o":["خمسة أعضاء","ثلاثة أعضاء","سبعة أعضاء","تسعة أعضاء"],"a":0},{"q":"مدة لجنة إعادة هيكلة ديون شركة التأمين هي:","o":["سنة من تاريخ صدور القرار بإعادة هيكلة الديون قابلة للتمديد","ستة أشهر غير قابلة للتمديد","سنتان من تاريخ تشكيلها","ثلاث سنوات قابلة للتمديد بموافقة المجلس"],"a":0},{"q":"قامت لجنة إعادة هيكلة ديون شركة تأمين برهن أحد عقارات الشركة دون موافقة مسبقة من البنك المركزي، فإن هذا التصرف:","o":["باطل","صحيح لأن اللجنة مفوضة باسم الشركة","موقوف على إجازة الهيئة العامة","صحيح إذا لم يعترض عليه الدائنون خلال ثلاثين يوماً"],"a":0},{"q":"تتم إجراءات إعادة هيكلة ديون شركة التأمين وسائر الأمور المتعلقة بها وفق:","o":["نظام يصدر لهذه الغاية","تعليمات يصدرها المحافظ","أحكام قانون الإعسار حصراً","قرار من الهيئة العامة للشركة"],"a":0}]},{"n":"49","chapter":"","notes":[],"source":"أ- مع مراعاة أحكام الفقرة (ب) من هذه المادة، يترتب على صدور قرار إعادة هيكلة الديون منذ تاريخ صدوره وحتى تاريخ صدور قرار من المجلس بانتهاء إعادة هيكلة الديون ما يلي:\n١- وقف احتساب مرور الزمن المانع من سماع الدعوى بشأن أي حقوق أو مطالبات مستحقة أو قائمة للغير على شركة التأمين.\n٢- وقف السير في الدعاوى والإجراءات القضائية المقامة ضد شركة التأمين.\n٣- وقف السير في أي معاملات تنفيذية أو إجرائية ضد شركة التأمين.\nب- تطبق أحكام البندين (٢) و (٣) من الفقرة (أ) من هذه المادة لمدة ثلاثة أشهر فقط على ما يلي:-\n١- الحقوق والمطالبات المستحقة أو القائمة لشركة التأمين على الغير وعلى الدعاوى والإجراءات القضائية والمعاملات التنفيذية التي باشرتها شركة التأمين ضد الغير.\n٢- الحقوق والمطالبات المستحقة أو القائمة لأصحاب الحقوق المضمونة على شركة التأمين وعلى الدعاوى والإجراءات القضائية والمعاملات التنفيذية التي باشرها أي من أصحاب الحقوق المضمونة ضد شركة التأمين إذا كانت متعلقة بالحق المضمون ذاته.\nج- لغايات تطبيق أحكام هذا القانون يقصد \" بـأصحاب الحقوق المضمونة\" الدائن صاحب الحق المضمون بحق عيني تبعي على مال منقول أو غير منقول.","title":"آثار قرار إعادة هيكلة الديون","memo":"⭐ من تاريخ القرار حتى قرار المجلس بالانتهاء: وقف مرور الزمن على حقوق الغير، وقف الدعاوى ضد الشركة، وقف المعاملات التنفيذية ضدها\n⭐ يطبق وقف الدعاوى والمعاملات لمدة ٣ أشهر فقط على: حقوق الشركة على الغير، وحقوق أصحاب الحقوق المضمونة المتعلقة بالحق المضمون ذاته\n⭐ أصحاب الحقوق المضمونة: الدائن صاحب الحق المضمون بحق عيني تبعي على مال منقول أو غير منقول","qs":[{"q":"يترتب على صدور قرار إعادة هيكلة ديون شركة التأمين بالنسبة للدعاوى المقامة ضدها من الدائنين العاديين:","o":["وقف السير فيها حتى صدور قرار المجلس بانتهاء إعادة الهيكلة","وقف السير فيها لمدة ثلاثة أشهر فقط","استمرار السير فيها دون أي أثر","إحالتها إلى محكمة بداية عمان"],"a":0},{"q":"تطبق أحكام وقف السير في الدعاوى والمعاملات التنفيذية على الدعاوى التي باشرها أصحاب الحقوق المضمونة المتعلقة بالحق المضمون ذاته لمدة:","o":["ثلاثة أشهر فقط","ستة أشهر فقط","سنة واحدة","حتى انتهاء إعادة الهيكلة"],"a":0},{"q":"يقصد بأصحاب الحقوق المضمونة لغايات قانون تنظيم أعمال التأمين:","o":["الدائن صاحب الحق المضمون بحق عيني تبعي على مال منقول أو غير منقول","الدائن الذي يحمل كفالة شخصية من أحد المساهمين","المؤمن له الذي يحمل وثيقة تأمين سارية","الدائن الممتاز بموجب قانون العمل"],"a":0}]},{"n":"50","chapter":"","notes":[],"source":"أ- على لجنة إعادة هيكلة ديون شركة التأمين نشر إعلان على نفقة شركة التأمين في صحيفتين يوميتين محليتين الاوسع انتشارا لمدة ثلاثة أيام عمل متتالية على الأقل لدعوة دائني الشركة لتقديم بيانات بمقدار ديونهم وضماناتها معززة بالوثائق المثبتة لذلك خلال مدة لا تتجاوز ثلاثين يوما من تاريخ النشر، وتصبح هذه المدة ستين يوما اذا كان الدائن مقيما خارج المملكة، ويصدر المجلس التعليمات اللازمة لبيان إجراءات تثبيت الديون المقدمة ضمن تلك المدة.\nب- بعد تثبيت الديون، تقدم لجنة إعادة هيكلة ديون شركة التأمين للمجلس تقريرها والخطة المقترحة لإعادة هيكلة الديون لأخذ الموافقة على تلك الخطة، على أن تتضمن برنامج عمل متكاملاً يشمل قائمة تبين حقوق شركة التأمين والتزاماتها وأسماء دائنيها ومدينيها ومقترحاً لتسوية ديون شركة التأمين يحدد نسبة التسديد التي تعرضها شركة التأمين على الدائنين وتواريخ السداد وأي ضمانات ستقدمها شركة التأمين لهم، كما يشمل الإجراءات التشغيلية والإدارية والمالية اللازمة لإعادة هيكلة الديون على نحو يضمن استمرارها في أعمالها.\nج- في حال عدم موافقة المجلس على الخطة يطلب المجلس من لجنة إعادة هيكلة ديون شركة التأمين تعديلها أو يتخذ أي إجراء آخر يراه مناسباً وفق أحكام هذا القانون.","title":"دعوة الدائنين وخطة إعادة الهيكلة","memo":"⭐ تنشر اللجنة إعلاناً على نفقة الشركة في صحيفتين يوميتين لمدة ٣ أيام عمل متتالية على الأقل\n⭐ يقدم الدائنون بيانات ديونهم خلال ٣٠ يوماً من النشر، و٦٠ يوماً للمقيم خارج المملكة\n⭐ بعد تثبيت الديون تقدم اللجنة تقريرها وخطتها للمجلس للموافقة، وإن لم يوافق يطلب تعديلها أو يتخذ إجراء آخر","qs":[{"q":"المدة التي يقدم خلالها دائن مقيم داخل المملكة بيانات دينه للجنة إعادة هيكلة ديون شركة التأمين هي:","o":["لا تتجاوز ثلاثين يوماً من تاريخ النشر","لا تتجاوز ستين يوماً من تاريخ النشر","لا تتجاوز شهرين من تاريخ صدور القرار","لا تتجاوز خمسة عشر يوماً من تاريخ النشر"],"a":0},{"q":"دائن لشركة تأمين يقيم خارج المملكة، يقدم بيانات دينه للجنة إعادة هيكلة الديون خلال مدة لا تتجاوز:","o":["ستين يوماً من تاريخ النشر","ثلاثين يوماً من تاريخ النشر","تسعين يوماً من تاريخ النشر","ستة أشهر من تاريخ النشر"],"a":0},{"q":"يجب أن يستمر نشر إعلان دعوة دائني شركة التأمين في صحيفتين يوميتين محليتين لمدة:","o":["ثلاثة أيام عمل متتالية على الأقل","يومين متتاليين على الأقل","أسبوع كامل على الأقل","يوم واحد فقط"],"a":0},{"q":"في حال عدم موافقة المجلس على خطة إعادة هيكلة الديون المقدمة من اللجنة، فإنه:","o":["يطلب من اللجنة تعديلها أو يتخذ أي إجراء آخر يراه مناسباً","يصدر قراراً بتصفية الشركة حكماً","يعرضها على الدائنين للتصويت عليها","يحيلها إلى المحكمة الإدارية"],"a":0}]},{"n":"51","chapter":"","notes":[],"source":"أ- تنشر لجنة إعادة هيكلة ديون شركة التأمين خطة إعادة هيكلة الديون الموافق عليها من المجلس في صحيفتين يوميتين محليتين الاوسع انتشارا ، للطلب من دائني شركة التأمين الموافقة عليها واعتمادها الذي يشترط فيه الحصول على موافقة خطية من دائني شركة التأمين الذين يمثلون ما لا يقل عن ثلاثة أرباع الديون غير الممتازة وغير المغطاة بضمانات، وتصبح هذه الخطة ملزمة لدائني شركة التأمين جميعهم بمن فيهم الدائنون الذين لم يتقدموا ببياناتهم وفق أحكام المادة (٥٠) من هذا القانون والذين لم يوافقوا على الخطة.\nب- يتم اعتماد الديون غير الممتازة وغير المضمونة التي تم تثبيتها وفق أحكام المادة (٥٠) من هذا القانون لغايات الحصول على موافقة الدائنين وفق النسبة المحددة في الفقرة (أ) من هذه المادة، دون المساس بحق أي دائن في اللجوء الى القضاء للاعتراض على ما تم تحديده من دينه أو لتثبيت دينه في حال تقديمه بعد المدة المحددة في المادة (٥٠) من هذا القانون.","title":"موافقة الدائنين على خطة إعادة الهيكلة","memo":"⭐ تنشر الخطة الموافق عليها من المجلس في صحيفتين يوميتين\n⭐ يشترط موافقة خطية من دائنين يمثلون ما لا يقل عن ثلاثة أرباع الديون غير الممتازة وغير المغطاة بضمانات\n⭐ تصبح ملزمة لجميع الدائنين حتى من لم يتقدم أو لم يوافق، دون المساس بحق اللجوء للقضاء","qs":[{"q":"يشترط لاعتماد خطة إعادة هيكلة ديون شركة التأمين موافقة خطية من دائنين يمثلون ما لا يقل عن:","o":["ثلاثة أرباع الديون غير الممتازة وغير المغطاة بضمانات","ثلثي الديون غير الممتازة وغير المغطاة بضمانات","نصف إجمالي ديون شركة التأمين","ثلاثة أرباع إجمالي ديون شركة التأمين بما فيها المضمونة"],"a":0},{"q":"دائن لم يوافق على خطة إعادة هيكلة ديون شركة التأمين التي حصلت على النسبة المطلوبة من الدائنين، فإن الخطة:","o":["تكون ملزمة له","لا تلزمه إلا إذا وقع عليها","تلزمه إذا كان قد تقدم ببيانات دينه فقط","لا تلزمه ويحق له التنفيذ فوراً على أموال الشركة"],"a":0},{"q":"قدم دائن بيانات دينه بعد انقضاء المدة المحددة في المادة (٥٠)، فإنه وفق المادة (٥١):","o":["يحق له اللجوء إلى القضاء لتثبيت دينه","يسقط حقه في الدين نهائياً","يحق له الاعتراض أمام المحافظ فقط","يعتبر دينه ممتازاً"],"a":0}]},{"n":"52","chapter":"","notes":[],"source":"أ- في حال موافقة الدائنين على خطة إعادة هيكلة الديون وفقاً لأحكام المادة (٥١) من هذا القانون، تقدم لجنة إعادة هيكلة ديون شركة التأمين هذه الخطة إلى المجلس لإصدار قرار بالبدء في تنفيذها.\nب- في حال عدم موافقة الدائنين على خطة إعادة هيكلة الديون وفقاً لأحكام المادة (٥١) من هذا القانون، تقدم لجنة إعادة هيكلة ديون شركة التأمين تقريرا بذلك إلى المجلس، الذي يقوم باتخاذ الإجراء الذي يراه مناسباً وفقا لأحكام هذا القانون.","title":"قرار تنفيذ خطة إعادة الهيكلة","memo":"⭐ عند موافقة الدائنين: تقدم اللجنة الخطة للمجلس لإصدار قرار بالبدء في تنفيذها\n⭐ عند عدم موافقتهم: تقدم اللجنة تقريراً للمجلس الذي يتخذ الإجراء المناسب","qs":[{"q":"في حال موافقة الدائنين على خطة إعادة هيكلة ديون شركة التأمين، يصدر قرار البدء في تنفيذها عن:","o":["المجلس","لجنة إعادة هيكلة الديون","الهيئة العامة لشركة التأمين","محكمة بداية عمان"],"a":0},{"q":"إذا لم يوافق الدائنون على خطة إعادة هيكلة ديون شركة التأمين، فإن لجنة إعادة الهيكلة:","o":["تقدم تقريراً بذلك إلى المجلس الذي يتخذ الإجراء المناسب","تنفذ الخطة رغم عدم الموافقة","تعيد نشر الخطة لمدة ستين يوماً","تصدر قراراً بتصفية الشركة"],"a":0}]},{"n":"53","chapter":"","notes":[],"source":"أ- تنتهي إعادة هيكلة الديون بقرار من المجلس إذا تم استكمال تنفيذ خطة إعادة هيكلة الديون، وفي هذه الحالة ينتهي عمل لجنة إعادة هيكلة ديون شركة التأمين ويتم انتخاب مجلس إدارة جديد لشركة التأمين وفقاً لأحكام قانون الشركات ، وفي هذه الحالة يراعى مايلي:- ١- تلغى أي حجوزات تحفظية أو تنفيذية وأي قرارات مستعجلة أو تنفيذية تم اتخاذها في الدعاوى والمعاملات المشار اليها في البندين (٢) و(٣) من الفقرة (أ) من المادة (٤٩) من هذا القانون، ويستمر وقف تلك الدعاوى والمعاملات بحكم القانون.\n٢- إذا تخلفت شركة التأمين عن الوفاء بالتزاماتها المحددة وفق خطة إعادة هيكلة الديون تجاه أولئك المدعين والمحكوم لهم، ففي هذه الحالة يحق لهم إعادة السير في دعاويهم ومعاملاتهم بعد تعديل مطالباتهم المقدمة فيها لتتطابق مع ما تقرر لهم وفق خطة إعادة هيكلة الديون.\nب- تلغى إعادة هيكلة الديون بقرار من المجلس إذا تبين له خلال تطبيق خطة إعادة هيكلة الديون عدم جدواها .\nج - إذا تقرر إلغاء إعادة هيكلة الديون، فعلى المجلس اتخاذ الإجراء المناسب وفق أحكام هذا القانون، وفي الأحوال جميعها يستمر تطبيق أحكام الفقرة (أ) من المادة (٤٩) من هذا القانون الى حين اتخاذ البنك المركزي إجراء آخر وفق أحكام هذه الفقرة.","title":"انتهاء وإلغاء إعادة هيكلة الديون","memo":"⭐ تنتهي بقرار من المجلس عند استكمال تنفيذ الخطة، وينتهي عمل اللجنة ويُنتخب مجلس إدارة جديد وفق قانون الشركات\n⭐ تلغى الحجوزات والقرارات المستعجلة ويستمر وقف الدعاوى، ويحق إعادة السير بها عند تخلف الشركة عن الوفاء وفق الخطة\n⭐ تلغى بقرار من المجلس إذا تبين عدم جدواها، ويستمر تطبيق المادة (٤٩/أ) لحين اتخاذ إجراء آخر","qs":[{"q":"تنتهي إعادة هيكلة ديون شركة التأمين عند استكمال تنفيذ الخطة بقرار من:","o":["المجلس","لجنة إعادة هيكلة الديون","الهيئة العامة للشركة","المحكمة الإدارية"],"a":0},{"q":"يترتب على انتهاء إعادة هيكلة الديون باستكمال تنفيذ الخطة بالنسبة للحجوزات التحفظية والتنفيذية في الدعاوى الموقوفة:","o":["إلغاؤها","استمرارها حتى سداد كامل الديون","تحويلها إلى رهون لصالح الدائنين","تجديدها لمدة ثلاثة أشهر"],"a":0},{"q":"تخلفت شركة التأمين بعد انتهاء إعادة الهيكلة عن الوفاء بالتزاماتها المحددة في الخطة تجاه أحد المدعين، فإنه يحق لهذا المدعي:","o":["إعادة السير في دعواه بعد تعديل مطالبته لتتطابق مع ما تقرر له وفق الخطة","إعادة السير في دعواه بكامل مطالبته الأصلية","طلب تصفية الشركة مباشرة من المحكمة","مطالبة البنك المركزي بالتعويض"],"a":0},{"q":"تلغى إعادة هيكلة ديون شركة التأمين بقرار من المجلس إذا:","o":["تبين له خلال تطبيق الخطة عدم جدواها","طلب ذلك ربع الدائنين","انقضت سنة على صدور القرار","طلبت ذلك الهيئة العامة للشركة"],"a":0}]},{"n":"54","chapter":"","notes":[],"source":"أ- يكون البنك المركزي الجهة الوحيدة المختصة بإصدار قرار تصفية أي شركة تأمين.\nب- يصدر قرار تصفية شركة التأمين في أي من الحالات التالية:-\n١- إذا لم يكن بالإمكان معالجة أوضاع شركة التأمين وفقا لأحكام المادة (٤٥) من هذا القانون، وكان من شأن استمرارها المساس بحقوق المؤمن لهم والمستفيدين.\n٢- إذا تعرضت شركة التأمين لأوضاع تؤثر جوهريا في مركزها المالي وتحول دون استمرارها في مزاولة أعمالها.\n٣- إذا صدر قرار بإلغاء ترخيص شركة التأمين.\nج- تسري على تصفية شركة التأمين الأحكام الواردة في هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه، كما يعمل بأحكام التصفية الواردة في قانون الشركات بالقدر الذي لا تتعارض فيه مع تلك الأحكام.\nد- تطبق أحكام الفقرة (ب) من المادة (١٢) من هذا القانون إذا قرر البنك المركزي تصفية فرع شركة تأمين أجنبيـــة.","title":"قرار تصفية شركة التأمين وحالاته","memo":"⭐ البنك المركزي الجهة الوحيدة المختصة بإصدار قرار التصفية\n⭐ الحالات: تعذر المعالجة وفق المادة (٤٥) مع المساس بحقوق المؤمن لهم، أوضاع تؤثر جوهرياً وتحول دون الاستمرار، إلغاء الترخيص\n⭐ تطبق أحكام قانون التأمين، وقانون الشركات بالقدر الذي لا يتعارض","qs":[{"q":"الجهة الوحيدة المختصة بإصدار قرار تصفية أي شركة تأمين هي:","o":["البنك المركزي","محكمة بداية عمان","مراقب الشركات","الهيئة العامة غير العادية للشركة"],"a":0},{"q":"أي مما يلي لا يعد من حالات إصدار قرار تصفية شركة التأمين وفق المادة (٥٤)؟","o":["توجيه تنبيه خطي لشركة التأمين","صدور قرار بإلغاء ترخيص شركة التأمين","تعرض الشركة لأوضاع تؤثر جوهرياً في مركزها المالي وتحول دون استمرارها","تعذر معالجة أوضاعها وفق المادة (٤٥) مع المساس بحقوق المؤمن لهم"],"a":0},{"q":"تسري على تصفية شركة التأمين أحكام التصفية الواردة في قانون الشركات:","o":["بالقدر الذي لا تتعارض فيه مع أحكام قانون تنظيم أعمال التأمين وأنظمته وتعليماته","بصورة أصلية ومقدمة على قانون تنظيم أعمال التأمين","في حالة التصفية الاختيارية فقط","لا تسري مطلقاً"],"a":0}]},{"n":"55","chapter":"","notes":[],"source":"أ- يكون القرار الذي يصدره المجلس بتصفية شركة التأمين قابلا للطعن لدى المحكمة الإدارية خلال ثلاثين يوماً من تاريخ نشره في الجريدة الرسمية على ان يتوافر في الطاعن أي من الشرطين التاليين:-\n١- أن يكون مالكاً أو مجموعة مساهمين يملكون ما لا يقل عن (٥%) من رأسمال شركة التأمين المكتتب به.\n٢- أن يكون له دين على شركة التأمين لا تقل نسبته عن (٥%) من إجمالي الديون المطلوبة من شركة التأمين.\nب- إذا قررت المحكمة الإدارية إلغاء قرار التصفية، فعلى مجلس إدارة شركة التأمين التقيد بأي متطلبات أو شروط خاصة يقررها المجلس.\nج- على الرغم مما ورد في أي تشريع آخر، لا يوقف الطعن وفق أحكام الفقرة (أ) من هذه المادة إجراءات التصفية.","title":"الطعن في قرار التصفية","memo":"⭐ يطعن لدى المحكمة الإدارية خلال ٣٠ يوماً من نشر القرار في الجريدة الرسمية\n⭐ الطاعن: مالك أو مساهمون يملكون ٥% على الأقل من رأس المال المكتتب به، أو دائن لا يقل دينه عن ٥% من إجمالي ديون الشركة\n⭐ الطعن لا يوقف إجراءات التصفية؛ وعند الإلغاء يتقيد مجلس الإدارة بشروط المجلس","qs":[{"q":"يطعن في قرار المجلس بتصفية شركة التأمين لدى المحكمة الإدارية خلال:","o":["ثلاثين يوماً من تاريخ نشره في الجريدة الرسمية","ستين يوماً من تاريخ صدوره","ثلاثين يوماً من تاريخ تبليغه للشركة","خمسة عشر يوماً من تاريخ نشره في الصحف"],"a":0},{"q":"يحق لمجموعة مساهمين الطعن في قرار تصفية شركة التأمين إذا كانوا يملكون ما لا يقل عن:","o":["(٥%) من رأسمال شركة التأمين المكتتب به","(١٠%) من رأسمال شركة التأمين المكتتب به","(٢٥%) من رأسمال شركة التأمين المدفوع","(١%) من رأسمال شركة التأمين المكتتب به"],"a":0},{"q":"دائن لشركة تأمين يبلغ دينه (٣%) من إجمالي الديون المطلوبة من الشركة، ولا يملك أسهماً فيها، فإنه بالنسبة للطعن في قرار التصفية:","o":["لا يحق له الطعن لأن دينه يقل عن (٥%) من إجمالي الديون","يحق له الطعن لأن كل دائن ذو مصلحة","يحق له الطعن أمام محكمة بداية عمان فقط","يحق له الطعن بعد موافقة المصفي"],"a":0},{"q":"يترتب على الطعن في قرار تصفية شركة التأمين أمام المحكمة الإدارية:","o":["عدم وقف إجراءات التصفية","وقف إجراءات التصفية حكماً","وقف إجراءات التصفية لمدة ثلاثة أشهر","وقف إجراءات التصفية إذا قدم الطاعن كفالة"],"a":0}]},{"n":"56","chapter":"","notes":[],"source":"أ- يفقد مجلس إدارة شركة التأمين وهيئتها العامة ومديرها العام منذ تاريخ صدور قرار التصفية المهام والصلاحيات جميعها المنوطة بأي منهم بموجب أحكام التشريعات النافذة وعقد تأسيس شركة التأمين وأنظمتها الداخلية، ويعين المجلس مصفياً لشركة التأمين يتولى الإشراف على أعمالها والمحافظة على أموالها وموجوداتها وتمثيلها أمام الغير والتوقيع بالنيابة عنها على العقود والمعاملات إلى حين الانتهاء من إجراءات التصفية، كما يحق للمجلس عزل المصفي أو استبدال غيره به في أي مرحلة من مراحل التصفية.\nب- يحدد المجلس أتعاب المصفي والكفالة التي يجب عليه تقديمها لصالح شركة التأمين.\nج- يجوز أن يكون المصفي لجنة من ثلاثة أعضاء على الأقل يختار المجلس رئيسا من بينهم، وفي هذه الحالة تنطبق شروط وأحكام تعيين المصفي على كل واحد منهم، وتصدر قرارات اللجنة بالأكثرية، كما لها توزيع صلاحياتها فيما بين الرئيس وأي من أعضائها.\nد- يشترط أن تتوافر فيمن يتم تعيينه مصفيا،ً أو ممثلا عنه إذا كان المصفي شخصاً اعتباريا،ً ما يلي:-\n١- المؤهلات والخبرات التي يتم تحديدها بموجب التعليمات الصادرة بموجب أحكام هذا القانون.\n٢- أن لا تربطه بأي من أعضاء مجلس إدارة شركة التأمين أو مديرها العام أو زوج أي منهم علاقة قرابة حتى الدرجة الرابعة أو علاقة عمل.\n٣- أن لا يكون من الدائنين أو المدينين للشركة.\n٤- أن لا يكون من العاملين لدى شركة التأمين أو من مستشاريها أو من أعضاء مجلس إدارة أي شركة تملكها شركة التأمين أو كانت تملكها خلال السنتين السابقتين لصدور قرار التصفية.\n٥- أن لا يكون قد حكم عليه بجنحة مخلة بالشرف أو الأمانة أو بأي جناية أو كان خاضعاً لإجراءات الإعسار أو صدر عليه حكم بالإفلاس.","title":"تعيين المصفي وشروطه","memo":"⭐ يفقد مجلس الإدارة والهيئة العامة والمدير العام صلاحياتهم من تاريخ قرار التصفية؛ والمجلس يعين المصفي ويعزله ويحدد أتعابه وكفالته\n⭐ يجوز أن يكون المصفي لجنة من ٣ أعضاء على الأقل يختار المجلس رئيسها، وقراراتها بالأكثرية\n⭐ شروطه: لا قرابة حتى الدرجة الرابعة مع أعضاء المجلس أو المدير العام، ليس دائناً أو مديناً، لم يعمل في الشركة أو شركاتها خلال السنتين السابقتين، غير محكوم","qs":[{"q":"من يعين المصفي لشركة التأمين ويحق له عزله أو استبداله في أي مرحلة من مراحل التصفية؟","o":["المجلس","المحكمة الإدارية","الهيئة العامة لشركة التأمين","محكمة بداية عمان"],"a":0},{"q":"إذا كان المصفي لجنة، فيجب ألا يقل عدد أعضائها عن:","o":["ثلاثة أعضاء","عضوين","خمسة أعضاء","سبعة أعضاء"],"a":0},{"q":"لا يجوز تعيين شخص مصفياً لشركة التأمين إذا كانت تربطه بأي من أعضاء مجلس إدارتها أو مديرها العام علاقة قرابة حتى الدرجة:","o":["الرابعة","الثالثة","الثانية","الخامسة"],"a":0},{"q":"كان أحمد عضواً في مجلس إدارة شركة تملكها شركة التأمين قبل سنة من صدور قرار التصفية، فإن تعيينه مصفياً:","o":["غير جائز لأنه كان كذلك خلال السنتين السابقتين لقرار التصفية","جائز لأنه لم يكن موظفاً في شركة التأمين نفسها","جائز بشرط تقديم كفالة","جائز بموافقة الهيئة العامة"],"a":0}]},{"n":"57","chapter":"","notes":[],"source":"على شركة التأمين تسليم المصفي الأموال والأوراق والدفاتر والسجلات الخاصة بشركة التأمين كافة ، واطلاع المصفي على الوثائق والعقود والبيانات المالية والحسابات البنكية الخاصة بشركة التأمين جميعها.","title":"تسليم المصفي أموال الشركة وسجلاتها","memo":"⭐ على شركة التأمين تسليم المصفي الأموال والأوراق والدفاتر والسجلات كافة\n⭐ وإطلاعه على الوثائق والعقود والبيانات المالية والحسابات البنكية جميعها","qs":[{"q":"بعد صدور قرار التصفية، على شركة التأمين تسليم المصفي:","o":["الأموال والأوراق والدفاتر والسجلات الخاصة بها كافة","البيانات المالية للسنة الأخيرة فقط","السجلات التي يحددها مجلس إدارتها فقط","الأموال النقدية دون الدفاتر والسجلات"],"a":0},{"q":"أي مما يلي يتوجب على شركة التأمين تحت التصفية إطلاع المصفي عليه؟","o":["الحسابات البنكية الخاصة بها جميعها","الحسابات البنكية الشخصية لأعضاء مجلس إدارتها","حسابات المؤمن لهم لدى البنوك","حسابات معيدي التأمين لدى البنوك الأجنبية"],"a":0}]},{"n":"58","chapter":"","notes":[],"source":"يترتب على صدور قرار التصفية ما يلي:-\nأ- توقف شركة التأمين عن ممارسة أعمالها على أن تستمر شخصيتها الاعتبارية ويمثلها المصفي إلى حين الانتهاء من أعمال التصفية.\nب- إضافة عبارة (تحت التصفية) إلى اسم شركة التأمين في أوراقها ومراسلاتها جميعها .\nج- وقف العمل بأي تفويض أو صلاحية توقيع صادرة عن شركة التأمين، ويختص المصفي حصرا بمنح أي تفويض أو صلاحية توقيع تتطلبه إجراءات التصفية.\nد- وقف احتساب مرور الزمن المانع من سماع الدعوى بشأن أي حقوق أو مطالبات مستحقة أو قائمة لصالح شركة التأمين لمدة سنة واحدة اعتبارا من تاريخ صدور قرار التصفية.\nهـ- حلول آجال الوفاء بجميع الديون المترتبة لشركة التأمين بما في ذلك الديون المؤجلة والتي لم يستحق أداؤها سواء كانت عادية أو مضمونة برهن.\nو- وقف سريان فوائد الديون كافة اعتباراً من تاريخ صدور قرار التصفية، إلا إذا كانت فوائد هذه الديون مؤمنة برهون أو بضمانات.\nز- وقف السير في الدعاوى وجميع الاجراءات القضائية المقامة من شركة التأمين أو ضدها لمدة ثلاثة أشهر إلا إذا قرر المصفي أن إجراءات التصفية والمحافظة على أموال شركة التأمين وموجوداتها وحقوقها تتطلب متابعة السير فيها قبل انتهاء هذه المدة.\nح- منع السير في أي معاملات تنفيذية أو قبولها ضد شركة التأمين إلا إذا كانت بناء على طلب أي من اصحاب الحقوق المضمونة ومتعلقة بالحق المضمون ذاته، ففي هذه الحالة لا يتم اتخاذ أي اجراءات في تلك المعاملات لمدة ثلاثة أشهر من تاريخ صدور قرار التصفية.\nط- منع اقامة أي دعاوى ضد شركة التأمين لمدة ثلاثة أشهر من تاريخ صدور قرار التصفية على أن لا تحتسب هذه المدة من ضمن المدة المقررة لعدم سماع الدعوى بشأن أي حقوق أو مطالبات للدائنين أو أي اشخاص آخرين تجاه شركة التأمين تحت التصفية.","title":"آثار صدور قرار التصفية","memo":"⭐ توقف الأعمال مع استمرار الشخصية الاعتبارية ويمثلها المصفي، وإضافة عبارة (تحت التصفية)\n⭐ وقف مرور الزمن على حقوق الشركة لمدة سنة واحدة؛ حلول آجال الديون المترتبة للشركة؛ وقف سريان الفوائد إلا المؤمنة برهون أو ضمانات\n⭐ وقف الدعاوى لمدة ٣ أشهر (إلا إذا قرر المصفي متابعتها)، ومنع إقامة دعاوى ضدها لمدة ٣ أشهر\n⭐ منع المعاملات التنفيذية إلا لأصحاب الحقوق المضمونة ولا يتخذ فيها إجراء لمدة ٣ أشهر","qs":[{"q":"يترتب على صدور قرار تصفية شركة التأمين بالنسبة لشخصيتها الاعتبارية:","o":["استمرارها ويمثلها المصفي إلى حين الانتهاء من أعمال التصفية","زوالها فوراً من تاريخ قرار التصفية","زوالها بعد ثلاثة أشهر من قرار التصفية","انتقالها إلى البنك المركزي"],"a":0},{"q":"يوقف احتساب مرور الزمن المانع من سماع الدعوى بشأن الحقوق المستحقة لصالح شركة التأمين تحت التصفية لمدة:","o":["سنة واحدة اعتباراً من تاريخ صدور قرار التصفية","ثلاثة أشهر من تاريخ صدور قرار التصفية","ستة أشهر من تاريخ نشر قرار التصفية","طوال مدة التصفية"],"a":0},{"q":"أي مما يلي لا يعد من آثار صدور قرار تصفية شركة التأمين؟","o":["استمرار سريان فوائد جميع الديون غير المضمونة","إضافة عبارة (تحت التصفية) إلى اسم الشركة في أوراقها ومراسلاتها","حلول آجال الوفاء بجميع الديون المترتبة لشركة التأمين","وقف العمل بأي تفويض أو صلاحية توقيع صادرة عن الشركة"],"a":0},{"q":"أراد دائن عادي إقامة دعوى ضد شركة تأمين بعد شهر من صدور قرار تصفيتها، فإن ذلك:","o":["ممنوع لأنه يمنع إقامة أي دعاوى ضد الشركة لمدة ثلاثة أشهر من تاريخ قرار التصفية","جائز دون قيد","ممنوع لمدة سنة من تاريخ قرار التصفية","جائز بموافقة المصفي فقط"],"a":0}]},{"n":"59","chapter":"","notes":[],"source":"أ- تعتبر باطلة جميع الرهون والضمانات التي وقعت على أي أموال أو حقوق عائدة للشركة خلال الثلاثة أشهر السابقة لتاريخ صدور قرار التصفية وتكون هذه المدة سنة واحدة إذا كانت هذه الرهون أو الضمانات لصالح شخص مرتبط بشركة التأمين.\nب- يعتبر ملغى كل قرار حجز وقع على أي حق عائد للشركة قبل صدور قرار التصفية إلا إذا كان هذا القرار صادرا بناء على طلب أي من اصحاب الحقوق المضمونة ومتعلقا بالحق المضمون ذاته.","title":"بطلان الرهون والحجوزات قبل التصفية","memo":"⭐ تبطل الرهون والضمانات على أموال الشركة خلال ٣ أشهر السابقة لقرار التصفية، وسنة واحدة إذا كانت لصالح شخص مرتبط بالشركة\n⭐ يلغى كل قرار حجز على حقوق الشركة قبل التصفية إلا إذا كان بطلب صاحب حق مضمون ومتعلقاً بالحق المضمون ذاته","qs":[{"q":"تعتبر باطلة الرهون والضمانات التي وقعت على أموال شركة التأمين خلال المدة السابقة لتاريخ صدور قرار التصفية والبالغة:","o":["ثلاثة أشهر","شهراً واحداً","ستة أشهر","سنتين"],"a":0},{"q":"رتبت شركة تأمين رهناً على أحد أموالها لصالح عضو في مجلس إدارتها قبل تسعة أشهر من صدور قرار تصفيتها، فإن هذا الرهن:","o":["باطل لأن المدة سنة واحدة إذا كان الرهن لصالح شخص مرتبط بالشركة","صحيح لأنه وقع قبل أكثر من ثلاثة أشهر من قرار التصفية","صحيح إذا وافقت عليه الهيئة العامة","قابل للإبطال بقرار من المحكمة الإدارية فقط"],"a":0},{"q":"يعتبر ملغى كل قرار حجز وقع على أي حق عائد لشركة التأمين قبل صدور قرار التصفية، باستثناء:","o":["القرار الصادر بناء على طلب صاحب حق مضمون ومتعلقاً بالحق المضمون ذاته","القرار الصادر لصالح دائن عادي","القرار الصادر لصالح أحد المساهمين","القرار الصادر لصالح أحد معيدي التأمين"],"a":0}]},{"n":"60","chapter":"","notes":[],"source":"على المصفي اتخاذ القرارات والإجراءات التي يراها لازمة لإتمام عملية التصفية، وفق التعليمات الصادرة لهذه الغاية، بما في ذلك ما يلي:-\nأ- إدارة أعمال شركة التأمين في حدود ما تتطلبه إجراءات التصفية.\nب- تعيين أي من الخبراء والأشخاص لمساعدته على إتمام إجراءات التصفية أو تعيين لجان خاصة وتفويضها بأي من المهام والصلاحيات المنوطة به وإصدار القرارات اللازمة لإتمام إجراءات التصفية.\nج- تعيين محام أو أكثر لتمثيل شركة التأمين تحت التصفية في أي دعاوى أو إجراءات قضائية أو تحكيمية.\nد- قبول التحكيم أو التوصل إلى اتفاقات تسوية مع الدائنين والمدينين وأي أطراف أخرى ذات علاقة مع شركة التأمين.","title":"صلاحيات المصفي لإتمام التصفية","memo":"⭐ يتخذ المصفي القرارات والإجراءات اللازمة وفق التعليمات\n⭐ يدير أعمال الشركة في حدود متطلبات التصفية، ويعين خبراء ولجاناً ويفوضها، ويعين محامياً أو أكثر\n⭐ يقبل التحكيم ويتوصل لاتفاقات تسوية مع الدائنين والمدينين","qs":[{"q":"يدير المصفي أعمال شركة التأمين تحت التصفية:","o":["في حدود ما تتطلبه إجراءات التصفية","بشكل كامل كما لو كانت الشركة غير خاضعة للتصفية","بعد موافقة الهيئة العامة للشركة","بموجب تفويض من مجلس إدارة الشركة"],"a":0},{"q":"أي مما يلي لا يعد من صلاحيات المصفي الواردة في المادة (٦٠)؟","o":["إصدار تعليمات تنظيم إجراءات التصفية","تعيين محام أو أكثر لتمثيل الشركة تحت التصفية","قبول التحكيم أو التوصل إلى اتفاقات تسوية مع الدائنين والمدينين","تعيين خبراء أو لجان خاصة وتفويضها ببعض مهامه"],"a":0}]},{"n":"61","chapter":"","notes":[],"source":"أ- على المصفي اتخاذ الإجراءات القانونية والقضائية اللازمة جميعها لحماية وتحصيل حقوق شركة التأمين ومطالباتها سواء داخل المملكة أو خارجها.\nب- على الرغم من أي اتفاق مخالف، للمصفي أن يتخذ جميع الإجراءات التي يراها ضرورية لحماية حقوق شركة التأمين بما في ذلك ما يلي:-\n١- إلغاء أي تصرف أو فسخ أي عقد أجرته شركة التأمين أو استرداد أي مبلغ دفعته خلال الأشهر الثلاثة التي سبقت صدور قرار التصفية إذا كان في ذلك تفضيل لشخص معين على دائني شركة التأمين، وتكون المدة سنة واحدة إذا كان ذلك الشخص مرتبطاً بشركة التأمين، ويعتبر التفضيل متحققا إذا كان التصرف أو الإجراء دون عوض أو بعوض جزئي أو كان منطويا على تقدير مال أو حق بغير قيمته الحقيقية أو بغير قيمته السائدة في السوق.\n٢- إلغاء أي تصرف أو فسخ أي عقد أجرته شركة التأمين مع أي شخص مرتبط بشركة التأمين أو استرداد أي مبلغ دفعته شركة التأمين إليه وذلك خلال الأشهر الثلاثة التي سبقت صدور قرار التصفية.\n٣- إنهاء استخدام أي من العاملين لدى شركة التأمين مع دفع مستحقاته.\n٤- إنهاء أي عقد أبرمته شركة التأمين مع أي شخص قبل انتهاء مدته.","title":"حماية حقوق الشركة تحت التصفية","memo":"⭐ على المصفي اتخاذ الإجراءات لحماية وتحصيل حقوق الشركة داخل المملكة وخارجها، رغم أي اتفاق مخالف\n⭐ إلغاء التصرفات التفضيلية خلال ٣ أشهر قبل التصفية، وسنة إذا كان الشخص مرتبطاً بالشركة\n⭐ التفضيل: دون عوض أو بعوض جزئي أو تقدير بغير القيمة الحقيقية أو السوقية\n⭐ إلغاء تصرفات الأشخاص المرتبطين خلال ٣ أشهر، إنهاء استخدام العاملين مع دفع مستحقاتهم، إنهاء العقود قبل انتهاء مدتها","qs":[{"q":"للمصفي إلغاء أي تصرف أجرته شركة التأمين فيه تفضيل لشخص غير مرتبط بها على دائنيها إذا وقع خلال:","o":["الأشهر الثلاثة التي سبقت صدور قرار التصفية","الأشهر الستة التي سبقت صدور قرار التصفية","السنة التي سبقت صدور قرار التصفية","السنتين اللتين سبقتا صدور قرار التصفية"],"a":0},{"q":"يعتبر التفضيل متحققاً في التصرف الذي أجرته شركة التأمين قبل التصفية في أي من الحالات التالية باستثناء:","o":["إذا كان التصرف بعوض كامل يعادل القيمة السائدة في السوق","إذا كان التصرف دون عوض","إذا كان التصرف بعوض جزئي","إذا انطوى على تقدير مال بغير قيمته الحقيقية"],"a":0},{"q":"للمصفي إنهاء استخدام أي من العاملين لدى شركة التأمين تحت التصفية:","o":["مع دفع مستحقاته","دون دفع أي مستحقات","بعد موافقة وزارة العمل","بعد انتهاء عقد العامل فقط"],"a":0},{"q":"باعت شركة تأمين عقاراً لشخص غير مرتبط بها بنصف قيمته السوقية قبل ثمانية أشهر من صدور قرار تصفيتها، فإن المصفي وفق المادة (٦١):","o":["لا يملك إلغاء التصرف بموجب هذا النص لوقوعه خارج مدة الأشهر الثلاثة","يملك إلغاء التصرف لوقوعه خلال السنة السابقة للتصفية","يملك إلغاء التصرف دون التقيد بأي مدة","يملك إلغاء التصرف بعد موافقة المحكمة الإدارية"],"a":0}]},{"n":"62","chapter":"","notes":[],"source":"لمقاصد تطبيق أحكام التصفية، يعتبر الشخص مرتبطا بشركة التأمين في أي من الحالتين التاليتين:-\nأ- إذا كان الشخص مساهماً رئيسياً أو له مصلحة مؤثرة فيها أو عضوا في مجلس إدارة شركة التأمين أو موظفا فيها أو له مصلحة عمل مشتركة مع أي منهم.\nب- إذا كان زوجا لأي من الأشخاص المشار إليهم في الفقرة (أ) من هذه المادة أو قريبا لأي منهم أو لزوجه حتى الدرجة الثالثة أو كانت له مصلحة عمل مشتركة مع أي منهم.","title":"الشخص المرتبط بشركة التأمين","memo":"⭐ مساهم رئيسي أو له مصلحة مؤثرة أو عضو مجلس إدارة أو موظف أو له مصلحة عمل مشتركة مع أي منهم\n⭐ زوج أي منهم أو قريب له أو لزوجه حتى الدرجة الثالثة أو له مصلحة عمل مشتركة معهم","qs":[{"q":"لمقاصد أحكام التصفية، يعتبر قريب عضو مجلس إدارة شركة التأمين شخصاً مرتبطاً بها إذا كانت القرابة حتى الدرجة:","o":["الثالثة","الرابعة","الثانية","الأولى"],"a":0},{"q":"أي من الأشخاص التالين لا يعتبر بذاته شخصاً مرتبطاً بشركة التأمين لمقاصد أحكام التصفية؟","o":["مؤمن له يحمل وثيقة تأمين لدى الشركة","مساهم رئيسي في الشركة","زوج أحد موظفي الشركة","شخص له مصلحة عمل مشتركة مع عضو في مجلس إدارتها"],"a":0}]},{"n":"63","chapter":"","notes":[],"source":"أ- على المصفي خلال ثلاثين يوما من تاريخ صدور قرار التصفية نشر إعلان بمكان ظاهر في صحيفتين يوميتين محليتين الأوسع انتشاراً على الأقل لإشعار الدائنين بتقديم مطالباتهم تجاه شركة التأمين سواء كانت مستحقة الوفاء أو غير مستحقة وذلك خلال شهرين من تاريخ النشر إذا كانوا مقيمين في المملكة وثلاثة أشهر إذا كانوا مقيمين خارجها.\nب- يعاد نشر الإعلان بالطريقة ذاتها فور انقضاء أربعة عشر يوما على تاريخ نشر الإعلان الأول، وتحتسب مدة تقديم المطالبات من تاريخ نشر الإعلان الأول.\nج- إذا اقتنع المصفي بوجود عذر مشروع للدائن لعدم تمكنه من تقديم مطالبته خلال المدة المحددة في الفقرة (أ) من هذه المادة أو إذا كانت المطالبة مقدمة من أي من المؤمن لهم أو المستفيدين، فيتم في هذه الحالة قبولها على أن لا تتجاوز في الأحوال جميعها ستة أشهر من تاريخ صدور قرار التصفية.\nد- لا تحتسب المدة من تاريخ صدور قرار التصفية إلى تاريخ نشر الإعلان الأول المذكور في الفقرة (أ) من هذه المادة من ضمن المدة المقررة لعدم سماع الدعوى بشأن أي حقوق أو مطالبات للدائنين تجاه شركة التأمين تحت التصفية.","title":"إعلان المصفي ومدد تقديم المطالبات","memo":"⭐ ينشر المصفي إعلاناً خلال ٣٠ يوماً من قرار التصفية في صحيفتين يوميتين على الأقل\n⭐ مدة تقديم المطالبات: شهران للمقيم في المملكة وثلاثة أشهر للمقيم خارجها، من تاريخ الإعلان الأول\n⭐ يعاد النشر فور انقضاء ١٤ يوماً على الإعلان الأول\n⭐ قبول المطالبة المتأخرة لعذر مشروع أو من المؤمن لهم بما لا يتجاوز ٦ أشهر من قرار التصفية","qs":[{"q":"على المصفي نشر إعلان لإشعار دائني شركة التأمين بتقديم مطالباتهم خلال:","o":["ثلاثين يوماً من تاريخ صدور قرار التصفية","ستين يوماً من تاريخ صدور قرار التصفية","أربعة عشر يوماً من تاريخ تعيينه","ثلاثة أشهر من تاريخ صدور قرار التصفية"],"a":0},{"q":"المدة التي يقدم خلالها الدائن المقيم خارج المملكة مطالبته تجاه شركة التأمين تحت التصفية هي:","o":["ثلاثة أشهر من تاريخ النشر","شهران من تاريخ النشر","ستون يوماً من تاريخ صدور قرار التصفية","ستة أشهر من تاريخ النشر"],"a":0},{"q":"يعاد نشر إعلان المصفي بالطريقة ذاتها فور انقضاء:","o":["أربعة عشر يوماً على تاريخ نشر الإعلان الأول","سبعة أيام على تاريخ نشر الإعلان الأول","ثلاثين يوماً على تاريخ نشر الإعلان الأول","ثلاثة أيام عمل على تاريخ نشر الإعلان الأول"],"a":0},{"q":"قدم مؤمن له مطالبته للمصفي بعد انقضاء المدة المحددة، فإنه يتم قبولها على ألا تتجاوز في الأحوال جميعها:","o":["ستة أشهر من تاريخ صدور قرار التصفية","ثلاثة أشهر من تاريخ صدور قرار التصفية","سنة من تاريخ نشر الإعلان الأول","ثلاث سنوات من تاريخ صدور قرار التصفية"],"a":0}]},{"n":"64","chapter":"","notes":[],"source":"يصدر البنك المركزي تعليمات تحدد إجراءات ومواعيد صدور قرارات المصفي بشأن مطالبات المؤمن لهم والمستفيدين وجميع الدائنين الآخرين.","title":"تعليمات قرارات المصفي بشأن المطالبات","memo":"⭐ يصدر البنك المركزي تعليمات تحدد إجراءات ومواعيد صدور قرارات المصفي بشأن مطالبات المؤمن لهم والمستفيدين والدائنين","qs":[{"q":"تحدد إجراءات ومواعيد صدور قرارات المصفي بشأن مطالبات المؤمن لهم والمستفيدين والدائنين بموجب:","o":["تعليمات يصدرها البنك المركزي","نظام يصدره مجلس الوزراء","قرار من محكمة بداية عمان","قرار من المصفي نفسه"],"a":0}]},{"n":"65","chapter":"","notes":[],"source":"أ- تختص محكمة بداية عمان بالنظر في الدعاوى الحقوقية المقامة ضد شركة التأمين تحت التصفية جميعها ، وتحال إليها جميع الدعاوى المرفوعة ضدها والمنظورة أمام المحاكم بتاريخ صدور قرار التصفية.\nب- لكل ذي مصلحة الطعن في قرارات المصفي وإجراءاته أمام محكمة بداية عمان خلال ثلاثين يوما من اليوم التالي لتاريخ تبليغه القرار أو خلال الستين يوما التالية لتاريخ نشره في صحيفتين يوميتين محليتين الأوسع انتشاراً أيهما أقصر.","title":"المحكمة المختصة بدعاوى الشركة تحت التصفية","memo":"⭐ محكمة بداية عمان تختص بجميع الدعاوى الحقوقية ضد الشركة تحت التصفية وتحال إليها الدعاوى المنظورة\n⭐ الطعن في قرارات المصفي أمام محكمة بداية عمان خلال ٣٠ يوماً من اليوم التالي للتبليغ أو ٦٠ يوماً من النشر، أيهما أقصر","qs":[{"q":"المحكمة المختصة بالنظر في الدعاوى الحقوقية المقامة ضد شركة التأمين تحت التصفية هي:","o":["محكمة بداية عمان","المحكمة الإدارية","محكمة استئناف عمان","محكمة صلح عمان"],"a":0},{"q":"يطعن ذو المصلحة في قرارات المصفي أمام محكمة بداية عمان خلال:","o":["ثلاثين يوماً من اليوم التالي لتبليغه أو ستين يوماً من نشره، أيهما أقصر","ثلاثين يوماً من تبليغه أو ستين يوماً من نشره، أيهما أطول","ستين يوماً من تاريخ صدور القرار","خمسة عشر يوماً من تاريخ نشره في الجريدة الرسمية"],"a":0},{"q":"كانت دعوى حقوقية ضد شركة تأمين منظورة أمام محكمة بداية إربد عند صدور قرار تصفيتها، فإن هذه الدعوى:","o":["تحال إلى محكمة بداية عمان","تستمر أمام محكمة بداية إربد","تسقط بحكم القانون","تحال إلى المحكمة الإدارية"],"a":0}]},{"n":"66","chapter":"","notes":[],"source":"إذا قدم المصفي طلبا إلى المحكمة المختصة لإلقاء حجز احتياطي أو لاتخاذ أي من الإجراءات الاحتياطية أو المستعجلة وفق أحكام التشريعات النافذة، فيعفى من إرفاق كفالة مع طلبه في حال الموافقة عليه.","title":"إعفاء المصفي من الكفالة","memo":"⭐ يعفى المصفي من إرفاق كفالة مع طلب الحجز الاحتياطي أو الإجراءات الاحتياطية أو المستعجلة","qs":[{"q":"إذا قدم المصفي طلباً إلى المحكمة المختصة لإلقاء حجز احتياطي، فإنه:","o":["يعفى من إرفاق كفالة مع طلبه","يلزم بإرفاق كفالة مصرفية بنسبة (١٠%) من قيمة المطالبة","يلزم بإرفاق كفالة عدلية","يلزم بالحصول على موافقة البنك المركزي على الكفالة"],"a":0},{"q":"يشمل إعفاء المصفي من إرفاق الكفالة الطلبات المتعلقة بـ:","o":["الحجز الاحتياطي أو أي من الإجراءات الاحتياطية أو المستعجلة","الطعن في قرارات البنك المركزي","الطعن في أحكام محكمة الاستئناف","تسجيل الرهون لصالح الشركة"],"a":0}]},{"n":"67","chapter":"","notes":[],"source":"للمصفي، بموافقة مسبقة من البنك المركزي، أن يقترض باسم شركة التأمين تحت التصفية ما يلزمه من أموال لتمكينه من إتمام أعمال التصفية، وله أن يرهن أيا من موجودات شركة التأمين أو حقوقها ضمانا لذلك.","title":"اقتراض المصفي باسم الشركة","memo":"⭐ للمصفي بموافقة مسبقة من البنك المركزي الاقتراض باسم الشركة تحت التصفية لإتمام التصفية\n⭐ وله رهن أي من موجودات الشركة أو حقوقها ضماناً لذلك","qs":[{"q":"يجوز للمصفي أن يقترض باسم شركة التأمين تحت التصفية ما يلزمه من أموال لإتمام التصفية بشرط:","o":["الحصول على موافقة مسبقة من البنك المركزي","الحصول على موافقة الدائنين العاديين","الحصول على إذن من محكمة بداية عمان","الحصول على موافقة الهيئة العامة للشركة"],"a":0},{"q":"ضماناً للقرض الذي يحصل عليه المصفي باسم شركة التأمين تحت التصفية، يجوز له:","o":["رهن أي من موجودات شركة التأمين أو حقوقها","رهن أموال أعضاء مجلس إدارة الشركة","تقديم كفالة من صندوق ضمان حقوق المؤمن لهم حصراً","رهن أموال المؤمن لهم"],"a":0}]},{"n":"68","chapter":"","notes":[],"source":"للمصفي بعد الحصول على موافقة خطية مسبقة من البنك المركزي أو بناء على طلب مجموعة من الدائنين العاديين الذين تزيد ديونهم على (٥٠%) من مجموع الديون العادية تسديد الدين المضمون برهن ورفع إشارة الرهن عن المال المرهون وإعادته لحساب التصفية.","title":"تسديد الدين المضمون برهن","memo":"⭐ للمصفي بموافقة خطية مسبقة من البنك المركزي، أو بطلب دائنين عاديين تزيد ديونهم على ٥٠% من مجموع الديون العادية\n⭐ تسديد الدين المضمون برهن ورفع إشارة الرهن وإعادة المال لحساب التصفية","qs":[{"q":"يجوز للمصفي تسديد الدين المضمون برهن ورفع إشارة الرهن بناء على طلب مجموعة من الدائنين العاديين تزيد ديونهم على:","o":["(٥٠%) من مجموع الديون العادية","(٧٥%) من مجموع الديون العادية","(٢٥%) من مجموع الديون العادية","(٥%) من مجموع الديون العادية"],"a":0},{"q":"يتم إعادة المال المرهون بعد تسديد المصفي للدين المضمون به ورفع إشارة الرهن عنه إلى:","o":["حساب التصفية","الدائن المرتهن","البنك المركزي","المساهمين"],"a":0}]},{"n":"69","chapter":"","notes":[],"source":"للمصفي بعد أخذ موافقة المجلس أن يتخذ أيا من الإجراءين التاليين دونما حاجة للحصول على موافقة المؤمن لهم أو المستفيدين أو الدائنين أو أي جهة أخرى:-\nأ- الاتفاق مع شركة تأمين واحدة أو أكثر لبيع جميع أو بعض موجودات شركة التأمين تحت التصفية وحقوقها والتزاماتها، بما في ذلك أي التزامات أو حقوق أخرى مهما كان نوعها وذلك دونما حاجة للتقيد بأي إجراءات ينص عليها أي تشريع آخر.\nب- بيع جميع أو أي من موجودات شركة التأمين تحت التصفية وحقوقها في مزايدة علنية وفق إجراءات خاصة تحددها تعليمات تصدر لهذه الغاية.","title":"بيع موجودات الشركة تحت التصفية","memo":"⭐ للمصفي بعد موافقة المجلس، دون حاجة لموافقة المؤمن لهم أو الدائنين أو أي جهة\n⭐ الاتفاق مع شركة تأمين أو أكثر لبيع الموجودات والحقوق والالتزامات دون التقيد بإجراءات أي تشريع آخر\n⭐ أو البيع في مزايدة علنية وفق تعليمات خاصة","qs":[{"q":"يشترط لقيام المصفي ببيع جميع أو بعض موجودات شركة التأمين تحت التصفية والتزاماتها لشركة تأمين أخرى:","o":["أخذ موافقة المجلس","موافقة المؤمن لهم والمستفيدين","موافقة الدائنين","موافقة محكمة بداية عمان"],"a":0},{"q":"إذا قرر المصفي بيع موجودات شركة التأمين تحت التصفية في مزايدة علنية، فيتم ذلك وفق:","o":["إجراءات خاصة تحددها تعليمات تصدر لهذه الغاية","أحكام قانون التنفيذ حصراً","إجراءات تحددها الهيئة العامة للدائنين","قرار من محكمة بداية عمان"],"a":0}]},{"n":"70","chapter":"","notes":[],"source":"إذا وجدت لدى شركة التأمين تحت التصفية أي سندات باعتبارها مؤتمنة عليها أو حارسة لها أو ما شابه ذلك من حالات، فلا تعتبر هذه السندات من ضمن موجودات شركة التأمين تحت التصفية وتعاد إلى أصحابها شريطة أن يسددوا جميع الالتزامات المترتبة عليهم تجاه شركة التأمين.","title":"السندات المؤتمنة لدى الشركة تحت التصفية","memo":"⭐ السندات المؤتمنة أو المحروسة لدى الشركة لا تعتبر من موجوداتها\n⭐ تعاد لأصحابها شريطة أن يسددوا جميع التزاماتهم تجاه الشركة","qs":[{"q":"السندات الموجودة لدى شركة التأمين تحت التصفية باعتبارها مؤتمنة عليها:","o":["لا تعتبر من موجوداتها وتعاد إلى أصحابها","تعتبر من موجوداتها وتباع لسداد الديون","تودع لدى البنك المركزي لحين انتهاء التصفية","تعتبر من موجوداتها إذا مضى عليها سنة"],"a":0},{"q":"يشترط لإعادة السندات المؤتمنة لدى شركة التأمين تحت التصفية إلى أصحابها:","o":["أن يسددوا جميع الالتزامات المترتبة عليهم تجاه شركة التأمين","موافقة المجلس","صدور حكم من محكمة بداية عمان","انتهاء أعمال التصفية"],"a":0}]},{"n":"71","chapter":"","notes":[],"source":"أ- يحق للمؤمن له أو للمستفيد من عقد التأمين الانتفاع من شرط الاختراق، ولا يجوز لأي جهة الاعتراض على تفعيله.\nب- لغايات تطبيق أحكام الفقرة (أ) من هذه المادة، يقصد بشرط الاختراق الشرط الوارد في عقد إعادة التأمين والذي يقضي بمسؤولية معيد التأمين في حدود حصته من الخسارة المعاد تأمينها لديه تجاه المؤمن له والمستفيد في الحالات التي يتعذر على المؤمن الوفاء بالتزاماته تجاه المؤمن له أو المستفيد كتصفية شركة التأمين وبحيث تنشأ علاقة مباشرة بين معيد التأمين والمؤمن له والمستفيد.","title":"شرط الاختراق في عقد إعادة التأمين","memo":"⭐ يحق للمؤمن له أو المستفيد الانتفاع من شرط الاختراق ولا يجوز لأي جهة الاعتراض على تفعيله\n⭐ شرط الاختراق: شرط في عقد إعادة التأمين يجعل معيد التأمين مسؤولاً في حدود حصته من الخسارة تجاه المؤمن له والمستفيد عند تعذر وفاء المؤمن (كالتصفية)، فتنشأ علاقة مباشرة بينهم","qs":[{"q":"يقصد بشرط الاختراق الشرط الوارد في:","o":["عقد إعادة التأمين","عقد التأمين الأصلي","عقد الوكالة بين شركة التأمين ووكيلها","خطة إعادة هيكلة الديون"],"a":0},{"q":"بموجب شرط الاختراق، تكون مسؤولية معيد التأمين تجاه المؤمن له والمستفيد:","o":["في حدود حصته من الخسارة المعاد تأمينها لديه","عن كامل الخسارة ولو تجاوزت حصته","في حدود نصف الخسارة","عن الأقساط غير المكتسبة فقط"],"a":0},{"q":"صدر قرار بتصفية شركة تأمين ويتضمن عقد إعادة التأمين لديها شرط الاختراق، فإن المؤمن له:","o":["ينشأ له علاقة مباشرة مع معيد التأمين ولا يجوز لأي جهة الاعتراض على تفعيل الشرط","لا يحق له الرجوع إلا على المصفي","يحق له تفعيل الشرط بعد موافقة الدائنين","يحق له تفعيل الشرط بعد انتهاء أعمال التصفية فقط"],"a":0}]},{"n":"72","chapter":"","notes":[],"source":"ينحصر استخدام المخصصات الفنية المطلوب الاحتفاظ بها لدى شركة التأمين وفق أحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه في تسديد حقوق المؤمن لهم والمستفيدين، ويعتبر أي مبلغ تحصل عليه شركة التأمين تبعاً لترتيبات إعادة التأمين جزءا من تلك المخصصات.","title":"استخدام المخصصات الفنية","memo":"⭐ ينحصر استخدام المخصصات الفنية في تسديد حقوق المؤمن لهم والمستفيدين\n⭐ يعتبر أي مبلغ تحصل عليه الشركة تبعاً لترتيبات إعادة التأمين جزءاً من تلك المخصصات","qs":[{"q":"ينحصر استخدام المخصصات الفنية المطلوب الاحتفاظ بها لدى شركة التأمين في:","o":["تسديد حقوق المؤمن لهم والمستفيدين","تسديد رواتب الموظفين خلال فترة التصفية","تسديد الضرائب والرسوم المستحقة للخزينة","تسديد أتعاب المصفي"],"a":0},{"q":"المبالغ التي تحصل عليها شركة التأمين تبعاً لترتيبات إعادة التأمين تعتبر:","o":["جزءاً من المخصصات الفنية","من حقوق الدائنين العاديين","من حقوق المساهمين","إيرادات تخصص لنفقات التصفية"],"a":0}]},{"n":"73","chapter":"","notes":[],"source":"أ- يتم تسديد الديون والالتزامات المستحقة على شركة التأمين تحت التصفية وفق الترتيب التالي:-\n١- المصاريف والنفقات التي تكبدها المصفي بما في ذلك أتعاب المصفي ورواتب الموظفين خلال فترة التصفية والقروض التي حصل عليها وفق أحكام هذا القانون والتعليمات الصادرة بمقتضاه.\n٢- حقوق الموظفين والمستخدمين لدى شركة التأمين المستحقة خلال مدة ستة الأشهر السابقة على صدور قرار التصفية .\n٣- ما يتبقى من حقوق المؤمن لهم والمستفيدين من عقود التأمين بعد استعمال مبالغ المخصصات الفنية وفق أحكام المادة (٧٢) من هذا القانون.\n٤- المبالغ التي يدفعها الصندوق المنشأ بمقتضى أحكام المادة (٧٩) من هذا القانون للمؤمن لهم والمستفيدين من عقود التأمين المبرمة مع شركة التأمين تحت التصفية.\n٥- أي ضرائب ورسوم وبدلات وعوائد مستحقة للخزينة.\n٦- حقوق الدائنين العاديين بما فيها حقوق معيدي التأمين والديون غير المغطاة بضمانات وأي حقوق أخرى.\n٧- حقوق المساهمين.\nب- لا يجوز سداد أي مبلغ لأي فئة من الدائنين إلا بعد سداد كامل ديون الفئة ذات الأولوية الأعلى وتسدد الديون حسب الأولوية في الفئة ذاتها .\nج- إذا تعذر سداد كامل ديون فئة من الدائنين أو أحد الديون داخل الفئة ذاتها يقسم المبلغ بين دائني تلك الفئة أو الدين داخل الفئة قسمة غرماء .","title":"ترتيب سداد ديون الشركة تحت التصفية","memo":"⭐ الترتيب: ١- مصاريف المصفي وأتعابه ورواتب الموظفين خلال التصفية والقروض ٢- حقوق الموظفين عن ٦ أشهر السابقة للتصفية ٣- باقي حقوق المؤمن لهم بعد المخصصات الفنية ٤- مبالغ الصندوق (المادة ٧٩) ٥- الضرائب والرسوم للخزينة ٦- الدائنون العاديون ومعيدو التأمين ٧- المساهمون\n⭐ لا يسدد لفئة إلا بعد سداد كامل الفئة الأعلى؛ وعند العجز تقسم قسمة غرماء","qs":[{"q":"تأتي في المرتبة الأولى في ترتيب سداد ديون شركة التأمين تحت التصفية:","o":["المصاريف والنفقات التي تكبدها المصفي بما فيها أتعابه","حقوق المؤمن لهم والمستفيدين","الضرائب والرسوم المستحقة للخزينة","حقوق الموظفين المستحقة قبل التصفية"],"a":0},{"q":"تعد حقوق الموظفين لدى شركة التأمين من الديون ذات الأولوية الثانية إذا كانت مستحقة خلال مدة:","o":["ستة الأشهر السابقة على صدور قرار التصفية","ثلاثة الأشهر السابقة على صدور قرار التصفية","السنة السابقة على صدور قرار التصفية","السنتين السابقتين على صدور قرار التصفية"],"a":0},{"q":"تصنف حقوق معيدي التأمين في ترتيب سداد ديون شركة التأمين تحت التصفية ضمن:","o":["حقوق الدائنين العاديين","حقوق المؤمن لهم والمستفيدين","المصاريف والنفقات التي تكبدها المصفي","الديون الممتازة للخزينة"],"a":0},{"q":"إذا تعذر سداد كامل ديون فئة من الدائنين في تصفية شركة التأمين، فإن المبلغ المتوفر:","o":["يقسم بين دائني تلك الفئة قسمة غرماء","يدفع لأقدم الديون في الفئة أولاً بالكامل","ينقل لسداد الفئة التالية","يؤول إلى صندوق ضمان حقوق المؤمن لهم"],"a":0}]},{"n":"74","chapter":"","notes":[],"source":"أ- على المصفي أن ينهي أعمال التصفية خلال ثلاث سنوات من تاريخ صدور قرار التصفية، ويجوز تمديدها بموافقة المجلس للمدة التي يراها مناسبة.\nب- تنتهي إجراءات التصفية ويتم فسخ شركة التأمين بقرار من المجلس، ويتم تبليغ قرار الفسخ إلى دائرة مراقبة الشركات لشطب تسجيلها، وعلى مراقب الشركات نشر قرار فسخ شركة التأمين في صحيفتين محليتين يوميتين الأوسع انتشارا، وتعتبر شركة التأمين منقضية من تاريخ نشر قرار فسخها في الجريدة الرسمية.","title":"مدة التصفية وانقضاء الشركة","memo":"⭐ ينهي المصفي التصفية خلال ٣ سنوات من قرار التصفية، ويجوز التمديد بموافقة المجلس\n⭐ تنتهي التصفية ويتم الفسخ بقرار من المجلس ويبلغ لدائرة مراقبة الشركات لشطب التسجيل\n⭐ ينشر مراقب الشركات قرار الفسخ في صحيفتين يوميتين، وتعتبر الشركة منقضية من تاريخ نشر قرار الفسخ في الجريدة الرسمية","qs":[{"q":"على المصفي أن ينهي أعمال تصفية شركة التأمين خلال:","o":["ثلاث سنوات من تاريخ صدور قرار التصفية","سنتين من تاريخ صدور قرار التصفية","خمس سنوات من تاريخ تعيينه","سنة واحدة من تاريخ نشر الإعلان الأول"],"a":0},{"q":"تعتبر شركة التأمين منقضية من تاريخ:","o":["نشر قرار فسخها في الجريدة الرسمية","صدور قرار التصفية","تبليغ قرار الفسخ إلى دائرة مراقبة الشركات","نشر قرار الفسخ في الصحف اليومية"],"a":0},{"q":"الجهة التي تصدر قرار إنهاء إجراءات التصفية وفسخ شركة التأمين هي:","o":["المجلس","مراقب الشركات","محكمة بداية عمان","المصفي"],"a":0}]},{"n":"75","chapter":"","notes":[],"source":"يحتفظ البنك المركزي بدفاتر شركة التأمين تحت التصفية ووثائقها لمدة خمس سنوات من تاريخ فسخ شركة التأمين.","title":"حفظ دفاتر الشركة المصفاة","memo":"⭐ يحتفظ البنك المركزي بدفاتر ووثائق شركة التأمين تحت التصفية لمدة خمس سنوات من تاريخ فسخ الشركة","qs":[{"q":"يحتفظ البنك المركزي بدفاتر شركة التأمين تحت التصفية ووثائقها لمدة:","o":["خمس سنوات","ثلاث سنوات","سبع سنوات","عشر سنوات"],"a":0},{"q":"تبدأ مدة احتفاظ البنك المركزي بدفاتر شركة التأمين تحت التصفية ووثائقها من تاريخ:","o":["فسخ شركة التأمين","صدور قرار التصفية","تعيين المصفي","نشر قرار التصفية في الجريدة الرسمية"],"a":0}]},{"n":"76","chapter":"","notes":[],"source":"إذا تبين للبنك المركزي أن هناك موجودات منقولة أو غير منقولة أو حقوق متبقية لشركة التأمين تحت التصفية بعد صدور القرار بفسخها، فللمجلس تعيين مصفٍ جديد أو تكليف المصفي السابق لغايات التصرف في تلك الموجودات أو تحصيل تلك الحقوق وتسويتها وفق أحكام هذا القانون.","title":"الموجودات المتبقية بعد الفسخ","memo":"⭐ إذا ظهرت موجودات منقولة أو غير منقولة أو حقوق متبقية بعد قرار الفسخ: للمجلس تعيين مصفٍ جديد أو تكليف المصفي السابق\n⭐ الغاية: التصرف في الموجودات أو تحصيل الحقوق وتسويتها وفق أحكام القانون","qs":[{"q":"إذا تبين للبنك المركزي وجود موجودات متبقية لشركة التأمين تحت التصفية بعد صدور القرار بفسخها، فإن الجهة التي لها تعيين مصفٍ جديد أو تكليف المصفي السابق هي:","o":["المجلس","المحافظ","المحكمة المختصة","الهيئة العامة للشركة"],"a":0},{"q":"حالة عملية: بعد صدور قرار بفسخ شركة تأمين تحت التصفية تبين وجود عقار مملوك لها لم يُتصرف فيه، فإن الإجراء المقرر قانوناً هو:","o":["تعيين مصفٍ جديد أو تكليف المصفي السابق للتصرف فيه","إلغاء قرار الفسخ وإعادة الشركة للعمل","أيلولة العقار حكماً إلى صندوق تعويض المؤمن لهم","تسجيل العقار باسم البنك المركزي"],"a":0}]},{"n":"77","chapter":"","notes":[],"source":"أ- ١- يجري تبليغ أي قرار أو إجراء يتخذه المصفي وفق أحكام هذا القانون إلى الشخص المعني بتسليمه له شخصيا أو لمن يمثله قانونا أو بإرساله له بالبريد المسجل إلى آخر عنوان له محفوظ لدى شركة التأمين تحت التصفية ويجوز التبليغ بوسائل التقنية الحديثة بما في ذلك البريد الالكتروني.\n٢ - إذا جرى التبليغ بواسطة البريد المسجل، فيعتبر الإشعار قد تم تبليغه إلى الشخص المعني بعد مرور خمسة عشر يوما على تاريخ إيداعه في البريد المسجل إذا كان الشخص المبلغ إليه مقيما داخل المملكة أو ثلاثين يوما على تاريخ إيداعه إذا كان الشخص مقيما خارج المملكة.\n٣- يكفي لإثبات وقوع التبليغ المشار إليه في البند (٢) من هذه الفقرة أن يقام الدليل على أن إشعار التبليغ قد أودع في البريد على العنوان الصحيح إلا إذا اقتنع المصفي أن الشخص المرسل إليه لم يتسلمه لأسباب مبررة.\nب- إذا تعذر التبليغ وفق أحكام الفقرة (أ) من هذه المادة، فعلى المصفي إجراء التبليغ بالنشر في صحيفتين يوميتين محليتين الأوسع انتشارا، ولمرتين على الأقل، وتكون أجور النشر على نفقة الشخص المعني، ويعتبر هذا النشر من تاريخ وقوعه تبليغا قانونيا من جميع الوجوه.","title":"تبليغ قرارات المصفي","memo":"⭐ يبلغ قرار المصفي: شخصياً أو لمن يمثله قانوناً أو بالبريد المسجل إلى آخر عنوان لدى الشركة، ويجوز بوسائل التقنية الحديثة ومنها البريد الإلكتروني\n⭐ البريد المسجل: يعتبر التبليغ تم بعد ١٥ يوماً من الإيداع للمقيم داخل المملكة، و٣٠ يوماً للمقيم خارجها\n⭐ إذا تعذر التبليغ: النشر في صحيفتين يوميتين محليتين الأوسع انتشاراً لمرتين على الأقل وعلى نفقة الشخص المعني","qs":[{"q":"إذا جرى تبليغ قرار المصفي بالبريد المسجل لشخص مقيم داخل المملكة، فيعتبر الإشعار مبلغاً بعد مرور:","o":["خمسة عشر يوماً على تاريخ إيداعه في البريد","سبعة أيام على تاريخ إيداعه في البريد","ثلاثين يوماً على تاريخ إيداعه في البريد","عشرة أيام على تاريخ إيداعه في البريد"],"a":0},{"q":"حالة عملية: أرسل المصفي إشعاراً بالبريد المسجل لدائن مقيم خارج المملكة، يعتبر الإشعار مبلغاً بعد مرور:","o":["ثلاثين يوماً على تاريخ إيداعه","خمسة عشر يوماً على تاريخ إيداعه","ستين يوماً على تاريخ إيداعه","خمسة وأربعين يوماً على تاريخ إيداعه"],"a":0},{"q":"إذا تعذر التبليغ بالطرق العادية، يجري المصفي التبليغ بالنشر في صحيفتين يوميتين محليتين، وتكون أجور النشر على نفقة:","o":["الشخص المعني","شركة التأمين تحت التصفية","البنك المركزي","صندوق تعويض المؤمن لهم"],"a":0},{"q":"الحد الأدنى لعدد مرات النشر في الصحف عند تعذر التبليغ وفق المادة (٧٧):","o":["مرتان","مرة واحدة","ثلاث مرات","أربع مرات"],"a":0}]},{"n":"78","chapter":"","notes":[],"source":"تطبق الأحكام الواردة في هذا القانون الخاصة بتصفية شركة التأمين على شركات التأمين التي تقرر تصفيتها قبل نفاذ أحكام هذا القانون بموجب أحكام قانون تنظيم أعمال التأمين رقم (٣٣) لسنة ١٩٩٩ وتعديلاته شريطة ان لا يؤثر ذلك على المراكز القانونية التي نشأت قبل نفاذ أحكام هذا القانون .","title":"سريان أحكام التصفية على السابقة","memo":"⭐ تطبق أحكام التصفية في هذا القانون على الشركات التي تقررت تصفيتها قبل نفاذه بموجب القانون رقم (٣٣) لسنة ١٩٩٩\n⭐ شرط: ألا يؤثر ذلك على المراكز القانونية التي نشأت قبل نفاذ القانون","qs":[{"q":"تطبق أحكام التصفية الواردة في قانون تنظيم أعمال التأمين لسنة ٢٠٢١ على شركات التأمين التي تقررت تصفيتها قبل نفاذه شريطة:","o":["ألا يؤثر ذلك على المراكز القانونية التي نشأت قبل نفاذ القانون","موافقة الهيئة العامة للشركة","موافقة مجلس الوزراء","ألا تكون قد مضت سنة على قرار التصفية"],"a":0},{"q":"تمت تصفية الشركات المشمولة بحكم المادة (٧٨) قبل نفاذ القانون بموجب أحكام:","o":["قانون تنظيم أعمال التأمين رقم (٣٣) لسنة ١٩٩٩","قانون الشركات","قانون الإعسار","قانون البنك المركزي"],"a":0}]},{"n":"79","chapter":"","notes":[],"source":"أ- ينشأ بمقتضى أحكام هذا القانون صندوق لتعويض المؤمن لهم أو المستفيدين في حال صدور قرار بتصفية شركة التأمين وعدم كفاية موجودات شركة التأمين تحت التصفية لتسديد الالتزامات المستحقة عليها للمؤمن لهم والمستفيدين.\nب- للمجلس أن يقرر استخدام أموال هذا الصندوق لتمويل الاجراءات المتخذة وفقا لأحكام البنود من (١) الى (٣) من الفقرة (أ) من المادة (٤٥) من هذا القانون إذا كانت تكلفة تلك الإجراءات اقل من تكلفة قرار التصفية.","title":"صندوق تعويض المؤمن لهم","memo":"⭐ ينشأ صندوق لتعويض المؤمن لهم أو المستفيدين عند: صدور قرار بتصفية شركة التأمين + عدم كفاية موجوداتها لتسديد التزاماتها لهم\n⭐ للمجلس استخدام أموال الصندوق لتمويل الإجراءات وفق البنود (١-٣) من الفقرة (أ) من المادة (٤٥) إذا كانت تكلفتها أقل من تكلفة قرار التصفية","qs":[{"q":"يُستخدم صندوق تعويض المؤمن لهم أو المستفيدين المنشأ بموجب المادة (٧٩) في حال:","o":["صدور قرار بتصفية شركة التأمين وعدم كفاية موجوداتها لتسديد التزاماتها للمؤمن لهم والمستفيدين","وقوع حوادث مركبات غير مغطاة بتأمين إلزامي","عدم معرفة سائق المركبة المسببة للضرر","تأخر شركة التأمين في دفع التعويض لأكثر من ثلاثين يوماً"],"a":0},{"q":"الجهة التي لها أن تقرر استخدام أموال صندوق تعويض المؤمن لهم لتمويل الإجراءات المنصوص عليها في المادة (٤٥):","o":["المجلس","المحافظ","مجلس الوزراء","المصفي"],"a":0},{"q":"يجوز استخدام أموال صندوق تعويض المؤمن لهم لتمويل الإجراءات وفق البنود (١-٣) من الفقرة (أ) من المادة (٤٥) إذا:","o":["كانت تكلفة تلك الإجراءات أقل من تكلفة قرار التصفية","وافق مجلس الوزراء على ذلك","زادت موجودات الصندوق على مليون دينار","طلبت ذلك الهيئة العامة لشركة التأمين"],"a":0}]},{"n":"80","chapter":"","notes":[],"source":"أ- ينشأ بمقتضى أحكام هذا القانون صندوق لتعويض المتضررين عن الوفاة والإصابات الجسمانية والأضرار المعنوية الناجمة عنها ومصاريف العلاج الطبي الناشئة عن حوادث المركبات غير المغطاة بتأمين إلزامي وذلك في الحالتين التاليتين:-\n١- عند عدم وجود عقد تأمين ساري المفعول يغطي المسؤولية المدنية الناجمة عن استعمال المركبة.\n٢- عند عدم التحقق من هوية المركبة المسببة للضرر، أو عند عدم معرفة مالك تلك المركبة أو سائقها.\nب- يعتبر الصندوق المنشأ بمقتضى أحكام الفقرة (أ) من هذه المادة الخلف القانوني والواقعي للصندوق المنشأ بموجب أحكام قانون تنظيم أعمال التأمين رقم (٣٣) لسنة ١٩٩٩ وتعديلاته والتعليمات الصادرة بمقتضاه، وتؤول لهذا الصندوق جميع حقوق وموجودات ذلك الصندوق، كما يتحمل الالتزامات المترتبة عليه.","title":"صندوق تعويض متضرري المركبات","memo":"⭐ ينشأ صندوق لتعويض المتضررين عن الوفاة والإصابات الجسمانية والأضرار المعنوية الناجمة عنها ومصاريف العلاج من حوادث المركبات غير المغطاة بتأمين إلزامي\n⭐ الحالتان: ١- عدم وجود عقد تأمين ساري المفعول ٢- عدم التحقق من هوية المركبة أو عدم معرفة مالكها أو سائقها\n⭐ الصندوق هو الخلف القانوني والواقعي لصندوق القانون رقم (٣٣) لسنة ١٩٩٩، وتؤول إليه حقوقه وموجوداته ويتحمل التزاماته","qs":[{"q":"يعوض صندوق تعويض المتضررين من حوادث المركبات (المادة ٨٠) عن جميع ما يلي باستثناء:","o":["الأضرار المادية اللاحقة بالمركبات","الوفاة","الإصابات الجسمانية","مصاريف العلاج الطبي"],"a":0},{"q":"حالة عملية: صدمت مركبة مجهولة الهوية أحد المشاة ولاذت بالفرار وأصيب بإصابات جسمانية، فإن الجهة التي يعوضه عنها القانون هي:","o":["صندوق تعويض المتضررين من حوادث المركبات غير المغطاة بتأمين إلزامي","صندوق تعويض المؤمن لهم والمستفيدين","الاتحاد الأردني لشركات التأمين","المكتب الموحد"],"a":0},{"q":"أي مما يلي ليس من الحالات التي يعوض فيها صندوق المركبات المنشأ بموجب المادة (٨٠)؟","o":["تصفية شركة التأمين التي أصدرت وثيقة المركبة","عدم وجود عقد تأمين ساري المفعول يغطي المسؤولية المدنية","عدم التحقق من هوية المركبة المسببة للضرر","عدم معرفة مالك المركبة أو سائقها"],"a":0}]},{"n":"81","chapter":"","notes":[],"source":"أ- يتمتع كل من الصندوقين المنشأين بمقتضى أحكام المادتين (٧٩) و(٨٠) بالشخصية الاعتبارية، ولكل منهما بهذه الصفة تملك الأموال المنقولة وغير المنقولة والقيام بجميع التصرفات القانونية اللازمة لتحقيق أهدافه بما في ذلك إبرام العقود وقبول المساعدات والتبرعات والمنح والهبات شريطة الحصول على موافقة مجلس الوزراء إذا كانت من مصدر غير أردني، وله حق التقاضي وتعيين أي محام لهذه الغاية.\nب- يصدر نظام لتحديد المساهمات المترتبة على قطاع التأمين في هذين الصندوقين من شركات التأمين أو المؤمن لهم أو المستفيدين عند ابرام عقود التأمين أو قبض التعويضات أو أي حالات أو مصادر مساهمات أخرى، كما يحدد النظام الأحكام الخاصة بتنظيم شؤون هذين الصندوقين وإجراءات تحصيل المساهمات الخاصة بهما والصرف منهما وسائر الأمور والأحكام الأخرى المتعلقة بهما.\nج- لكل من الصندوقين أن يحل حلولاً قانونياً بحدود ما دفعه محل المستفيد منه في مواجهة أي شخص يحق للمستفيد مطالبته بما قبضه من الصندوق.","title":"الشخصية الاعتبارية للصندوقين","memo":"⭐ يتمتع الصندوقان (م٧٩ وم٨٠) بالشخصية الاعتبارية، وقبول المساعدات والتبرعات والمنح من مصدر غير أردني يحتاج موافقة مجلس الوزراء\n⭐ يصدر نظام لتحديد مساهمات قطاع التأمين في الصندوقين وتنظيم شؤونهما والصرف منهما\n⭐ لكل صندوق الحلول القانوني محل المستفيد بحدود ما دفعه","qs":[{"q":"يشترط لقبول أي من صندوقي المادتين (٧٩) و(٨٠) المساعدات والتبرعات إذا كانت من مصدر غير أردني الحصول على موافقة:","o":["مجلس الوزراء","المحافظ","مجلس إدارة البنك المركزي","وزير الصناعة والتجارة"],"a":0},{"q":"تحدد المساهمات المترتبة على قطاع التأمين في صندوقي التعويض بموجب:","o":["نظام","تعليمات يصدرها البنك المركزي","قرار من المحافظ","قرار من مجلس إدارة الاتحاد الأردني لشركات التأمين"],"a":0},{"q":"حالة عملية: دفع صندوق تعويض المتضررين تعويضاً لمصاب في حادث، ثم تبين وجود شخص يحق للمصاب مطالبته، فإن للصندوق:","o":["الحلول محل المستفيد في مواجهة ذلك الشخص بحدود ما دفعه","استرداد التعويض من المستفيد","الحلول محل المستفيد بكامل قيمة الضرر","مطالبة شركة التأمين بضعف ما دفعه"],"a":0}]},{"n":"82","chapter":"","notes":[],"source":"أ- يتم ترخيص مقدمي الخدمات التأمينية من البنك المركزي وفق أسس وشروط تنظم أعمالهم والرقابة عليها وفق تعليمات تصدر لهذه الغاية ولا يجوز تسجيلهم لدى الجهات المختصة إلا بموافقة مسبقة من البنك المركزي.\nب- تشمل أعمال مقدمي الخدمات التأمينية ما يلي:-\n١- الاكتواريون.\n٢- وكلاء التأمين.\n٣- وسطاء التأمين.\n٤- وسطاء إعادة التأمين، للقيام بأعمال وساطة التأمين بين شركة التأمين وشركة إعادة التأمين.\n٥- مسوّو الخسائر، للقيام بأعمال تسوية الخسائر لغايات التأمين، بما في ذلك الكشف على الأضرار والتحقق من سبب الخسارة والظروف المحيطة بها وتحديد مقدار التعويض.\n٦- المعاينون، للقيام بأعمال المعاينة لغايات التأمين، بما في ذلك الكشف على الممتلكات المراد التأمين عليها وتقدير قيمتها وتحديد الحد الأقصى للخسارة المالية المتوقعة عند وقوع الخطر، وتقديم المقترحات لتحسين وسائل الوقاية من الأخطار.\n٧- الاستشاريون، لتقديم الاستشارات التأمينية.\n٨- التأمين المصرفي، لقيام البنك المرخص له ببيع وتسويق منتجات تأمينية نيابة عن شركة التأمين.\n٩- إدارة أعمال التأمين، للقيام بإدارة أعمال شركة التأمين أو شركة إعادة التأمين أو أي صندوق يوفر لأعضائه أو المستفيدين منه منافع تأمينية كالتي يوفرها عقد التأمين وفقاً للاتفاقية المبرمة مع أي منهم لهذه الغاية.\n١٠- أي خدمات تأمينية أخرى يحددها البنك المركزي.\nج- إذا كان مقدم الخدمة التأمينية شخصاً اعتباريا،ً فتطبق عليها أحكام المواد (٢١-١٩) من هذا القانون.\nد- تحدد شروط ترخيص شركات المقر ومكاتب التمثيل التي ترغب في تقديم الخدمات التأمينية خارج المملكة وأسس تنظيم أعمالها ومراقبتها بموجب تعليمات تصدر لهذه الغاية.\nهـ- تحدد بتعليمات الحالات والشروط التي قد يسمح فيها بمنح موافقات لممارسة أعمال مقدمي الخدمات التأمينية لغير المقيمين في المملكة.","title":"ترخيص مقدمي الخدمات التأمينية","memo":"⭐ يرخص مقدمو الخدمات التأمينية من البنك المركزي، ولا يجوز تسجيلهم لدى الجهات المختصة إلا بموافقة مسبقة منه\n⭐ تشمل: الاكتواريين، الوكلاء، الوسطاء، وسطاء إعادة التأمين، مسوي الخسائر، المعاينين، الاستشاريين، التأمين المصرفي، إدارة أعمال التأمين، وأي خدمات يحددها البنك المركزي\n⭐ مقدم الخدمة الشخص الاعتباري تطبق عليه المواد (١٩-٢١)","qs":[{"q":"الكشف على الأضرار والتحقق من سبب الخسارة وتحديد مقدار التعويض من أعمال:","o":["مسوي الخسائر","المعاينين","الاكتواريين","وسطاء إعادة التأمين"],"a":0},{"q":"الكشف على الممتلكات المراد التأمين عليها وتقدير قيمتها وتحديد الحد الأقصى للخسارة المالية المتوقعة من أعمال:","o":["المعاينين","مسوي الخسائر","الاستشاريين","وكلاء التأمين"],"a":0},{"q":"قيام البنك المرخص ببيع وتسويق منتجات تأمينية نيابة عن شركة التأمين يسمى:","o":["التأمين المصرفي","وساطة التأمين","إدارة أعمال التأمين","وكالة إعادة التأمين"],"a":0},{"q":"إذا كان مقدم الخدمة التأمينية شخصاً اعتبارياً فتطبق عليه أحكام المواد:","o":["(١٩-٢١)","(١١) و(٤٢) و(٤٥)","(٨٨-٩٠)","(٢٢-٢٥)"],"a":0}]},{"n":"83","chapter":"","notes":[],"source":"أ- يخضع مقدمو الخدمات التأمينية أثناء ممارستهم لأعمالهم لرقابة البنك المركزي واشرافه، وعليهم تزويده بكل ما يطلبه من بيانات ومعلومات خلال المدة التي يحددها.\nب- تلتزم شركات التأمين ومقدمو الخدمات التأمينية بالافصاح لعملائهم عن أي من العمولات أو الاتعاب المرتبطة بالخدمة المقدمة سواء أكانت على نفقة العميل أم شركة التأمين.","title":"رقابة البنك والإفصاح عن العمولات","memo":"⭐ يخضع مقدمو الخدمات التأمينية لرقابة البنك المركزي وإشرافه ويزودونه بما يطلب خلال المدة التي يحددها\n⭐ تلتزم شركات التأمين ومقدمو الخدمات بالإفصاح لعملائهم عن العمولات أو الأتعاب سواء أكانت على نفقة العميل أم شركة التأمين","qs":[{"q":"يلتزم مقدمو الخدمات التأمينية بتزويد البنك المركزي بما يطلبه من بيانات ومعلومات خلال:","o":["المدة التي يحددها البنك المركزي","خمسة عشر يوماً من تاريخ الطلب","ثلاثين يوماً من تاريخ الطلب","المدة التي يحددها مجلس الوزراء"],"a":0},{"q":"يلتزم وسيط التأمين بالإفصاح لعميله عن العمولات المرتبطة بالخدمة المقدمة:","o":["سواء أكانت على نفقة العميل أم شركة التأمين","إذا كانت على نفقة العميل فقط","إذا كانت على نفقة شركة التأمين فقط","إذا طلب العميل ذلك خطياً فقط"],"a":0}]},{"n":"84","chapter":"","notes":[],"source":"يحظر على شركة التأمين التعامل مع أي من مقدمي الخدمات التأمينية ما لم يكن حاصلا على ترخيص أو موافقة من البنك المركزي لممارسة أعماله.","title":"حظر التعامل مع غير المرخصين","memo":"⭐ يحظر على شركة التأمين التعامل مع أي مقدم خدمات تأمينية غير حاصل على ترخيص أو موافقة من البنك المركزي","qs":[{"q":"يحظر على شركة التأمين التعامل مع مقدم الخدمات التأمينية ما لم يكن حاصلاً على ترخيص أو موافقة من:","o":["البنك المركزي","وزارة الصناعة والتجارة والتموين","الاتحاد الأردني لشركات التأمين","مراقب عام الشركات"],"a":0},{"q":"حالة عملية: رغبت شركة تأمين بالتعاقد مع مسوي خسائر غير حاصل على ترخيص أو موافقة من البنك المركزي، فإن هذا التعامل:","o":["محظور","جائز بموافقة مجلس إدارة الشركة","جائز إذا كان مسوي الخسائر مسجلاً لدى غرفة التجارة","جائز لمدة لا تزيد على سنة"],"a":0}]},{"n":"85","chapter":"","notes":[],"source":"تطبق أحكام المواد (١١) و(٤٢) و(٤٥) من هذا القانون على شركة إدارة أعمال التأمين ومجلس ادارتها أو هيئة مديريها ومديرها وباقي موظفيها بالقدر الذي لا تتعارض فيه مع طبيعة أعمالها.","title":"الأحكام المطبقة على شركة الإدارة","memo":"⭐ تطبق المواد (١١) و(٤٢) و(٤٥) على شركة إدارة أعمال التأمين ومجلس إدارتها أو هيئة مديريها ومديرها وموظفيها\n⭐ بالقدر الذي لا يتعارض مع طبيعة أعمالها","qs":[{"q":"تطبق على شركة إدارة أعمال التأمين أحكام المواد التالية من القانون:","o":["(١١) و(٤٢) و(٤٥)","(١٩) و(٢٠) و(٢١)","(٨٨) و(٨٩) و(٩٠)","(٧٩) و(٨٠) و(٨١)"],"a":0},{"q":"تطبق المواد المحددة في المادة (٨٥) على شركة إدارة أعمال التأمين:","o":["بالقدر الذي لا تتعارض فيه مع طبيعة أعمالها","بشكل مطلق دون أي قيد","بموافقة مجلس الوزراء","خلال السنة الأولى من ترخيصها فقط"],"a":0}]},{"n":"86","chapter":"","notes":[],"source":"للبنك المركزي فرض غرامة مالية لا تقل عن ألف دينار ولا تزيد على مائة ألف دينار على أي من مقدمي الخدمات التأمينية في حال مخالفتهم أحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه.","title":"غرامات مقدمي الخدمات التأمينية","memo":"⭐ للبنك المركزي فرض غرامة على مقدم الخدمات التأمينية المخالف: لا تقل عن ١٠٠٠ دينار ولا تزيد على ١٠٠٠٠٠ دينار","qs":[{"q":"الحد الأعلى للغرامة التي يفرضها البنك المركزي على مقدم الخدمات التأمينية المخالف:","o":["مائة ألف دينار","خمسون ألف دينار","أربعمائة ألف دينار","عشرة آلاف دينار"],"a":0},{"q":"الحد الأدنى للغرامة التي يفرضها البنك المركزي على مقدمي الخدمات التأمينية المخالفين:","o":["ألف دينار","خمسمائة دينار","عشرة آلاف دينار","خمسة آلاف دينار"],"a":0}]},{"n":"87","chapter":"","notes":[],"source":"أ- يشكل المحافظ لجنة أو أكثر تسمى (لجنة حل نزاعات التأمين) تتولى النظر في الشكاوى المقدمة من المؤمن لهم والمستفيدين والمتعلقة بأي من أعمال التأمين والبت فيها وتكون قرارات اللجنة ملزمة للشركة ولأي جهة مرخصة وفقاً لأحكام هذا القانون اذا ارتضى مقدم الشكوى بقرارها .\nب- تحدد اجراءات عمل اللجنة وسائر الشؤون المتعلقة بها بمقتضى تعليمات تصدر لهذه الغاية .\nج- يترتب على تقديم أي شكوى متعلقة بأعمال التأمين أمام لجنة حل نزاعات التأمين وقف مدة التقادم.\nد- تحال الشكاوى المنظورة أمام لجنة حل نزاعات التأمين المشكلة بموجب قانون تنظيم أعمال التأمين رقم (٣٣) لسنة ١٩٩٩ وتعديلاته إلى اللجنة المنصوص عليها في هذه المادة .","title":"لجنة حل نزاعات التأمين","memo":"⭐ يشكل المحافظ لجنة أو أكثر (لجنة حل نزاعات التأمين) للنظر في شكاوى المؤمن لهم والمستفيدين\n⭐ قراراتها ملزمة للشركة ولأي جهة مرخصة إذا ارتضى مقدم الشكوى بقرارها\n⭐ تقديم الشكوى أمام اللجنة يوقف مدة التقادم\n⭐ تحال الشكاوى المنظورة أمام لجنة القانون رقم (٣٣) لسنة ١٩٩٩ إلى اللجنة الجديدة","qs":[{"q":"الجهة التي تشكل لجنة حل نزاعات التأمين:","o":["المحافظ","مجلس إدارة البنك المركزي","مجلس الوزراء","الاتحاد الأردني لشركات التأمين"],"a":0},{"q":"تكون قرارات لجنة حل نزاعات التأمين ملزمة للشركة ولأي جهة مرخصة إذا:","o":["ارتضى مقدم الشكوى بقرارها","صادق عليها المحافظ","لم يطعن بها أمام المحكمة خلال ثلاثين يوماً","صدرت بالإجماع"],"a":0},{"q":"يترتب على تقديم شكوى متعلقة بأعمال التأمين أمام لجنة حل نزاعات التأمين:","o":["وقف مدة التقادم","انقطاع مدة التقادم","سقوط حق التقاضي أمام المحاكم","وقف تنفيذ عقد التأمين"],"a":0}]},{"n":"88","chapter":"","notes":[],"source":"على شركات التأمين ومقدمي الخدمات التأمينية مراعاة السرية التامة في الأمور الخاصة بأعمال التأمين والخدمات التي تقدمها، ويحظر إعطاء أي بيانات عن تلك الأعمال والخدمات وعن المؤمن لهم والمستفيدين في غير الحالات المسموح بها بمقتضى أحكام هذا القانون، ويستمر هذا الحظر قائماً ولو انتهت العلاقة مع المؤمن لهم والمستفيدين.","title":"سرية أعمال التأمين","memo":"⭐ على شركات التأمين ومقدمي الخدمات مراعاة السرية التامة، ويحظر إعطاء بيانات عن الأعمال والمؤمن لهم والمستفيدين في غير الحالات المسموح بها\n⭐ يستمر الحظر قائماً ولو انتهت العلاقة مع المؤمن لهم والمستفيدين","qs":[{"q":"يستمر حظر إعطاء البيانات عن المؤمن لهم والمستفيدين المفروض على شركات التأمين:","o":["ولو انتهت العلاقة مع المؤمن لهم والمستفيدين","لمدة خمس سنوات من انتهاء العلاقة","طوال مدة سريان عقد التأمين فقط","لمدة سنتين من انتهاء العلاقة"],"a":0},{"q":"حالة عملية: انتهت وثيقة تأمين أحد العملاء منذ سنوات، وطلب طرف آخر من الشركة بيانات عنه في غير الحالات المسموح بها قانوناً، فإن على الشركة:","o":["الامتناع عن تقديمها لاستمرار حظر السرية","تقديمها لانتهاء العلاقة التعاقدية","تقديمها بعد إشعار العميل","تقديمها بموافقة مدير الشركة"],"a":0}]},{"n":"89","chapter":"","notes":[],"source":"يحظر على أي من موظفي شركات التأمين ومقدمي الخدمات التأمينية أو أي من موظفيها السابقين إعطاء أي معلومات أو بيانات عن المؤمن لهم أو المستفيدين أو تمكين الغير من الاطلاع عليها في غير الحالات المسموح بها بمقتضى أحكام هذا القانون، ويسري هذا الحظر على كل من يطلع بحكم مهنته أو وظيفته أو عمله بطريق مباشر أو غير مباشر على تلك البيانات والمعلومات بما في ذلك موظفو البنك المركزي والمحاسبون القانونيون الخارجيون وأي شخص يقوم البنك المركزي بتكليفه لتقييم أي جوانب تتعلق بأعمال التأمين للجهات الخاضعة لرقابته بموجب أحكام هذا القانون.","title":"سرية الموظفين ومن في حكمهم","memo":"⭐ يحظر على موظفي شركات التأمين ومقدمي الخدمات وموظفيها السابقين إعطاء معلومات عن المؤمن لهم أو تمكين الغير من الاطلاع عليها\n⭐ يسري الحظر على كل من يطلع بحكم مهنته، بما فيهم موظفو البنك المركزي والمحاسبون القانونيون الخارجيون ومن يكلفهم البنك بالتقييم","qs":[{"q":"يشمل الحظر الوارد في المادة (٨٩) إعطاء أي معلومات أو بيانات عن المؤمن لهم أو المستفيدين، وكذلك:","o":["تمكين الغير من الاطلاع عليها","نشر البنك المركزي للبيانات الإحصائية المجمعة","تقديمها للبنك المركزي عند قيامه بمهامه","الإفصاح عنها لإثبات حق الشركة في نزاع قضائي مع عميلها"],"a":0},{"q":"حالة عملية: محاسب قانوني خارجي اطلع بحكم عمله على بيانات مؤمن لهم لدى شركة تأمين، فإن إعطاءه هذه البيانات للغير في غير الحالات المسموح بها:","o":["محظور عليه كما هو محظور على موظفي الشركة","جائز لأنه ليس موظفاً في الشركة","جائز بعد انتهاء عملية التدقيق","جائز بموافقة نقابة المحاسبين"],"a":0},{"q":"يشمل حظر إفشاء المعلومات الوارد في المادة (٨٩):","o":["الموظفين الحاليين والسابقين لشركات التأمين ومقدمي الخدمات التأمينية","الموظفين الحاليين فقط","أعضاء مجلس الإدارة فقط","الموظفين السابقين خلال سنتين من انتهاء خدمتهم فقط"],"a":0}]},{"n":"90","chapter":"","notes":[],"source":"يستثنى من أحكام المادتين (٨٨) و(٨٩) من هذا القانون كل من:-\nأ- البنك المركزي عند قيامه بأعماله ومهامه وفق أحكام هذا القانون.\nب- شركات التأمين ومقدمي الخدمات التأمينية وأي جهة أخرى يوافق عليها البنك المركزي عند تبادل المعلومات الخاصة بعقود التأمين.\nج- أي من الجهات التي تمارس أعمال التأمين أو الخدمات التأمينية إذا تم ذلك لإثبات حقها في نزاع قضائي نشأ بينها وبين عميلها بشأن أي معاملة تتعلق بعقود التأمين أو الخدمات التأمينية.\nد- المحاسب القانوني الخارجي أو الاكتواري الملزم بالإفصاح عن أي معلومات أو بيانات وفق أحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه.","title":"استثناءات السرية","memo":"⭐ يستثنى من حظر المادتين (٨٨) و(٨٩): ١- البنك المركزي عند قيامه بمهامه ٢- شركات التأمين ومقدمو الخدمات وأي جهة يوافق عليها البنك عند تبادل معلومات عقود التأمين\n⭐ ٣- الجهة التي تمارس أعمال التأمين لإثبات حقها في نزاع قضائي مع عميلها ٤- المحاسب القانوني الخارجي أو الاكتواري الملزم بالإفصاح قانوناً","qs":[{"q":"أي مما يلي لا يعد من الاستثناءات الواردة على حظر إفشاء المعلومات في المادة (٩٠)؟","o":["إفصاح الموظف السابق عن بيانات العملاء بعد انتهاء خدمته","البنك المركزي عند قيامه بأعماله ومهامه","تبادل شركات التأمين للمعلومات الخاصة بعقود التأمين","الاكتواري الملزم بالإفصاح وفق أحكام القانون"],"a":0},{"q":"حالة عملية: رفع مؤمن له دعوى على شركة التأمين بشأن عقد تأمين، فقدمت الشركة للمحكمة بيانات تخصه لإثبات حقها، فإن ذلك:","o":["جائز لأنه من الحالات المستثناة من حظر السرية","محظور ويعاقب عليه بالحبس","جائز بموافقة المؤمن له الخطية فقط","جائز بموافقة لجنة حل نزاعات التأمين فقط"],"a":0},{"q":"يجوز لشركات التأمين تبادل المعلومات الخاصة بعقود التأمين مع أي جهة أخرى دون مخالفة حظر السرية إذا كانت تلك الجهة:","o":["يوافق عليها البنك المركزي","يوافق عليها مجلس إدارة الشركة","عضواً في الاتحاد الأردني لشركات التأمين","حاصلة على موافقة وزير الصناعة والتجارة"],"a":0}]},{"n":"91","chapter":"","notes":[],"source":"أ- تعتبر جميع المعلومات والبيانات الإفرادية التي تقدم للبنك المركزي وفق أحكام هذا القانون معلومات وبيانات سرية لا يجوز إطلاع أي شخص أو هيئة عليها إلا من خلال البيانات الإحصائية المجمعة التي ينشرها البنك من آن لاخر.\nب- للبنك المركزي تبادل المعلومات الخاصة بقطاع التأمين مع الهيئات والمؤسسات المنظمة والمشرفة على القطاع المالي داخل المملكة وخارجها، بما في ذلك الجهات المختصة بمكافحة الاحتيال في أعمال التأمين شريطة المعاملة بالمثل إذا جرى هذا التبادل مع جهات خارج المملكة وأن تتوافر لدى تلك الجهات الضمانات الكافية للمحافظة على سرية المعلومات التي يتم تزويدها بها.","title":"سرية البيانات المقدمة للبنك","memo":"⭐ المعلومات والبيانات الإفرادية المقدمة للبنك المركزي سرية، ولا يطلع عليها أحد إلا من خلال البيانات الإحصائية المجمعة التي ينشرها البنك\n⭐ للبنك تبادل المعلومات مع الجهات المنظمة والمشرفة على القطاع المالي داخل المملكة وخارجها ومنها جهات مكافحة الاحتيال\n⭐ شرط التبادل مع الخارج: المعاملة بالمثل + توافر ضمانات كافية للسرية","qs":[{"q":"لا يجوز إطلاع أي شخص على المعلومات والبيانات الإفرادية المقدمة للبنك المركزي إلا من خلال:","o":["البيانات الإحصائية المجمعة التي ينشرها البنك","قرار من المحكمة المختصة","موافقة مجلس الوزراء","طلب من الاتحاد الأردني لشركات التأمين"],"a":0},{"q":"يشترط لتبادل البنك المركزي المعلومات الخاصة بقطاع التأمين مع جهات خارج المملكة:","o":["المعاملة بالمثل وتوافر ضمانات كافية للمحافظة على السرية","موافقة مجلس الوزراء المسبقة","موافقة شركات التأمين المعنية","أن تكون الجهة عضواً في جامعة الدول العربية"],"a":0}]},{"n":"92","chapter":"","notes":[],"source":"يعاقب كل من يخالف أحكام المادتين (٨٨) و(٨٩) من هذا القانون بالحبس مدة لا تقل عن ستة أشهر أو بغرامة لا تقل عن عشرة آلاف دينار ولا تزيد على خمسين ألف دينار أو بكلتا هاتين العقوبتين.","title":"عقوبة إفشاء السرية","memo":"⭐ عقوبة مخالفة المادتين (٨٨) و(٨٩): الحبس مدة لا تقل عن ستة أشهر أو غرامة من ١٠٠٠٠ إلى ٥٠٠٠٠ دينار أو كلتاهما","qs":[{"q":"الحد الأدنى لعقوبة الحبس لمن يخالف أحكام السرية في المادتين (٨٨) و(٨٩):","o":["ستة أشهر","ثلاثة أشهر","سنة","شهر واحد"],"a":0},{"q":"الحد الأعلى للغرامة على مخالفة أحكام السرية في المادتين (٨٨) و(٨٩):","o":["خمسون ألف دينار","مائة ألف دينار","أربعمائة ألف دينار","عشرون ألف دينار"],"a":0},{"q":"الحد الأدنى للغرامة على مخالفة أحكام السرية في المادتين (٨٨) و(٨٩):","o":["عشرة آلاف دينار","ألف دينار","خمسة آلاف دينار","خمسون ألف دينار"],"a":0}]},{"n":"93","chapter":"","notes":[],"source":"أ- ينشأ بمقتضى هذا القانون اتحاد مهني يسمى (الاتحاد الأردني لشركات التأمين) يتمتع بالشخصية الاعتبارية ذات الاستقلال المالي والإداري وله بهذه الصفة تملك الأموال المنقولة وغير المنقولة والقيام بجميع التصرفات القانونية اللازمة لتحقيق أهدافه بما في ذلك إبرام العقود وقبول المساعدات والتبرعات والمنح والهبات شريطة الحصول على موافقة مجلس الوزراء إذا كانت من مصدر غير أردني ، وله حق التقاضي وتعيين أي محام لهذه الغاية.\nب- يعتبر هذا الاتحاد الخلف القانوني والواقعي للاتحاد الأردني لشركات التأمين المؤسس بمقتضى قانون تنظيم أعمال التأمين رقم (٣٣) لسنة ١٩٩٩ وتعديلاته وتعتبر شركات التأمين وشركات إعادة التأمين جميعها أعضاء في هذا الاتحاد حكماً.\nج- تحدد مهام الاتحاد ومسؤولياته والأحكام والإجراءات الخاصة بجمعيته العمومية وتشكيل مجلس إدارته واجتماعات كل منهما ورسوم الانتساب إليه والاشتراك السنوي به وموارده المالية والإجراءات التأديبية بحق أعضائه وغير ذلك من شؤونه الإدارية والمالية بما في ذلك أسس الحوكمة والتدقيق بموجب نظام يصدر لهذه الغاية.","title":"الاتحاد الأردني لشركات التأمين","memo":"⭐ ينشأ (الاتحاد الأردني لشركات التأمين) اتحاداً مهنياً بشخصية اعتبارية واستقلال مالي وإداري\n⭐ المنح والتبرعات من مصدر غير أردني تحتاج موافقة مجلس الوزراء\n⭐ خلف قانوني وواقعي للاتحاد المؤسس بالقانون رقم (٣٣) لسنة ١٩٩٩، وشركات التأمين وإعادة التأمين جميعها أعضاء حكماً\n⭐ تحدد مهامه وجمعيته العمومية ومجلس إدارته ورسومه والحوكمة بموجب نظام","qs":[{"q":"العضوية في الاتحاد الأردني لشركات التأمين بالنسبة لشركات التأمين وشركات إعادة التأمين:","o":["حكمية لجميعها","اختيارية بطلب من الشركة","إلزامية لشركات التأمين دون شركات إعادة التأمين","بموافقة البنك المركزي على كل طلب"],"a":0},{"q":"يشترط لقبول الاتحاد الأردني لشركات التأمين التبرعات والمنح من مصدر غير أردني موافقة:","o":["مجلس الوزراء","البنك المركزي","الجمعية العمومية للاتحاد","المحافظ"],"a":0},{"q":"تحدد مهام الاتحاد الأردني لشركات التأمين ورسوم الانتساب إليه والإجراءات التأديبية بحق أعضائه بموجب:","o":["نظام","تعليمات يصدرها البنك المركزي","النظام الداخلي الذي تقره الجمعية العمومية","قرار من المحافظ"],"a":0}]},{"n":"94","chapter":"","notes":[],"source":"أ- تنفيذاً لأحكام اتفاقية بطاقة التأمين الموحدة عن سير السيارات عبر البلاد العربية (البطاقة البرتقالية) ينشأ بموجب أحكام هذا القانون مكتب إقليمي يسمى (المكتب الموحد)، للقيام بالمهام الواردة في تلك الاتفاقية.\nب- تحدد الأحكام والإجراءات الخاصة بإدارة المكتب الموحد وموارده المالية ورقابة البنك المركزي عليه وغير ذلك من شؤونه الإدارية والمالية وأي مهام أخرى يوكله بها البنك المركزي بموجب نظام يصدر لهذه الغاية.","title":"المكتب الموحد (البطاقة البرتقالية)","memo":"⭐ ينشأ (المكتب الموحد) مكتباً إقليمياً تنفيذاً لاتفاقية بطاقة التأمين الموحدة عن سير السيارات عبر البلاد العربية (البطاقة البرتقالية)\n⭐ تحدد إدارته وموارده ورقابة البنك المركزي عليه بموجب نظام","qs":[{"q":"أنشئ المكتب الموحد تنفيذاً لأحكام اتفاقية:","o":["بطاقة التأمين الموحدة عن سير السيارات عبر البلاد العربية (البطاقة البرتقالية)","البطاقة الخضراء الدولية للتأمين على السيارات","تيسير التجارة العربية الكبرى","السوق العربية المشتركة للتأمين"],"a":0},{"q":"تحدد الأحكام الخاصة بإدارة المكتب الموحد وموارده المالية ورقابة البنك المركزي عليه بموجب:","o":["نظام","تعليمات","قرار من المحافظ","اتفاقية بين شركات التأمين"],"a":0}]},{"n":"95","chapter":"","notes":[],"source":"أ- يستوفي البنك المركزي الرسوم التالية:-\n١- رسم سنوي على شركة التأمين وشركة إعادة التأمين بنسبة لا تتجاوز (٥،٤) في الألف من إجمالي الأقساط المكتتبة، وفقا لآلية الاحتساب التي يحددها البنك المركزي لهذه الغاية.\n٢- رسم سنوي مبلغاً مقطوعاً يستوفى من الجهات الخاضعة لرقابة البنك المركزي وفق أحكام هذا القانون من غير شركات التأمين.\n٣- رسم طلب الترخيص.\n٤- رسم منح الترخيص.\n٥- رسم الموافقة على فتح فرع.\n٦- رسم ترخيص شركة التأمين الأجنبية وشركات مقدمي الخدمات التأمينية الأجنبية غير العاملة في المملكة (شركات المقر ومكاتب التمثيل).\nب- يحدد مقدار كل من هذه الرسوم بموجب نظام يصدر لهذه الغاية.\nج- يحدد بتعليمات بدل الخدمات التي يقدمها البنك المركزي لغايات تنفيذ أحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه.","title":"رسوم البنك المركزي","memo":"⭐ رسم سنوي على شركة التأمين وإعادة التأمين لا يتجاوز (٥،٤) في الألف من إجمالي الأقساط المكتتبة\n⭐ رسم سنوي مقطوع على الجهات الخاضعة للرقابة من غير شركات التأمين، إضافة لرسوم طلب الترخيص ومنحه وفتح الفرع وترخيص شركات المقر ومكاتب التمثيل\n⭐ مقدار الرسوم بنظام، وبدل الخدمات بتعليمات","qs":[{"q":"الحد الأعلى للرسم السنوي الذي يستوفيه البنك المركزي من شركة التأمين:","o":["(٥،٤) في الألف من إجمالي الأقساط المكتتبة","(٥) في الألف من صافي الأرباح","(١) بالمائة من إجمالي الأقساط المكتتبة","(٤،٥) في الألف من رأس المال المدفوع"],"a":0},{"q":"يستوفى الرسم السنوي من الجهات الخاضعة لرقابة البنك المركزي من غير شركات التأمين على شكل:","o":["مبلغ مقطوع","نسبة من الأقساط المكتتبة","نسبة من الإيرادات","نسبة من رأس المال"],"a":0},{"q":"يحدد مقدار الرسوم التي يستوفيها البنك المركزي بموجب المادة (٩٥) بموجب:","o":["نظام","تعليمات","قرار من المحافظ","قرار من مجلس الوزراء"],"a":0}]},{"n":"96","chapter":"","notes":[],"source":"يعاقب بغرامة لا تقل عن ألف دينار ولا تزيد على أربعمائة ألف دينار كل من يخالف أحكام هذا القانون أو الأنظمة أو التعليمات الصادرة بمقتضاه من غير شركات التأمين ومقدمي الخدمات التأمينية وفق تعليمات تصدر لهذه الغاية .","title":"غرامة المخالفين من غير الشركات","memo":"⭐ يعاقب المخالف من غير شركات التأمين ومقدمي الخدمات التأمينية بغرامة من ١٠٠٠ إلى ٤٠٠٠٠٠ دينار وفق تعليمات","qs":[{"q":"الحد الأعلى للغرامة على من يخالف أحكام القانون من غير شركات التأمين ومقدمي الخدمات التأمينية:","o":["أربعمائة ألف دينار","مائة ألف دينار","خمسون ألف دينار","مليون دينار"],"a":0},{"q":"تطبق الغرامة الواردة في المادة (٩٦) على المخالفين:","o":["من غير شركات التأمين ومقدمي الخدمات التأمينية","من شركات التأمين فقط","من مقدمي الخدمات التأمينية فقط","من موظفي البنك المركزي"],"a":0}]},{"n":"97","chapter":"","notes":[],"source":"تحصل الغرامات المفروضة بمقتضى أحكام هذا القانون من البنك المركزي وتحول شهريا لحساب الصندوق المنشأ وفقا لأحكام المادة (٧٩) من هذا القانون.","title":"تحصيل الغرامات وتحويلها","memo":"⭐ تحصل الغرامات من البنك المركزي وتحول شهرياً لحساب صندوق تعويض المؤمن لهم (المادة ٧٩)","qs":[{"q":"تحول الغرامات المفروضة بمقتضى قانون تنظيم أعمال التأمين إلى:","o":["حساب صندوق تعويض المؤمن لهم والمستفيدين المنشأ وفق المادة (٧٩)","الخزينة العامة","حساب صندوق تعويض المتضررين من حوادث المركبات","حساب الاتحاد الأردني لشركات التأمين"],"a":0},{"q":"تحول الغرامات المحصلة بمقتضى قانون تنظيم أعمال التأمين لحساب الصندوق المختص بشكل:","o":["شهري","ربع سنوي","سنوي","نصف سنوي"],"a":0}]},{"n":"98","chapter":"","notes":[],"source":"يجوز فرض التأمين الإلزامي ضد بعض الأخطار بموجب نظام يحدد شروط هذا التأمين وأحكامه العامة وجميع الأمور المتعلقة به.","title":"التأمين الإلزامي","memo":"⭐ يجوز فرض التأمين الإلزامي ضد بعض الأخطار بموجب نظام يحدد شروطه وأحكامه","qs":[{"q":"يفرض التأمين الإلزامي ضد بعض الأخطار بموجب:","o":["نظام","تعليمات يصدرها البنك المركزي","قرار من المحافظ","قانون خاص لكل خطر"],"a":0}]},{"n":"99","chapter":"","notes":[],"source":"تبدأ السنة المالية لشركة التأمين في الأول من كانون الثاني من السنة وتنتهي في الحادي والثلاثين من كانون الأول من تلك السنة.","title":"السنة المالية لشركة التأمين","memo":"⭐ السنة المالية لشركة التأمين: من الأول من كانون الثاني إلى الحادي والثلاثين من كانون الأول","qs":[{"q":"تبدأ السنة المالية لشركة التأمين في:","o":["الأول من كانون الثاني","الأول من نيسان","الأول من تموز","تاريخ تسجيل الشركة"],"a":0},{"q":"تنتهي السنة المالية لشركة التأمين في:","o":["الحادي والثلاثين من كانون الأول","الثلاثين من حزيران","الحادي والثلاثين من آذار","نهاية السنة التي يحددها نظامها الأساسي"],"a":0}]},{"n":"100","chapter":"","notes":[],"source":"تلتزم شركات التأمين بتبادل المعلومات الخاصة بعقود التأمين لديها لغايات الحد من ارتكاب أي مخالفة لأحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه والتشريعات الأخرى ذات العلاقة بما في ذلك منع الحصول على منافع غير محقة وذلك فيما بين شركات التأمين والبنك المركزي وأي جهات أخرى وفق تعليمات تصدر لهذه الغاية.","title":"تبادل معلومات عقود التأمين","memo":"⭐ تلتزم شركات التأمين بتبادل معلومات عقود التأمين فيما بينها ومع البنك المركزي وأي جهات أخرى وفق تعليمات\n⭐ الغاية: الحد من المخالفات بما في ذلك منع الحصول على منافع غير محقة","qs":[{"q":"الغاية من التزام شركات التأمين بتبادل المعلومات الخاصة بعقود التأمين لديها:","o":["الحد من ارتكاب المخالفات بما في ذلك منع الحصول على منافع غير محقة","توحيد أسعار وثائق التأمين","زيادة الحصة السوقية للشركات","تسهيل اندماج الشركات"],"a":0},{"q":"ينظم تبادل المعلومات بين شركات التأمين والبنك المركزي والجهات الأخرى وفق المادة (١٠٠) بموجب:","o":["تعليمات","نظام","اتفاقية بين الشركات","قرار من مجلس الوزراء"],"a":0}]},{"n":"101","chapter":"","notes":[],"source":"على الجهات الخاضعة لرقابة البنك المركزي جميعها وفقاً لأحكام هذا القانون والتعليمات الصادرة بمقتضاه، أن تحصل على موافقة البنك المركزي على استخدام أي موظف غير أردني لديها، وللبنك المركزي تحديد عدد الموظفين غير الأردنيين أو نسبتهم لمجموع عدد موظفي أي من تلك الجهات.","title":"استخدام الموظفين غير الأردنيين","memo":"⭐ على الجهات الخاضعة لرقابة البنك المركزي الحصول على موافقته لاستخدام أي موظف غير أردني\n⭐ للبنك المركزي تحديد عدد الموظفين غير الأردنيين أو نسبتهم","qs":[{"q":"يشترط لاستخدام شركة التأمين أي موظف غير أردني الحصول على موافقة:","o":["البنك المركزي","وزارة الداخلية فقط","مجلس إدارة الشركة فقط","الاتحاد الأردني لشركات التأمين"],"a":0},{"q":"الجهة التي لها تحديد عدد الموظفين غير الأردنيين أو نسبتهم لدى الجهات الخاضعة لرقابة البنك المركزي:","o":["البنك المركزي","مجلس الوزراء","الاتحاد الأردني لشركات التأمين","الهيئة العامة للشركة"],"a":0}]},{"n":"102","chapter":"","notes":[],"source":"لا يجوز لأي جهة خاضعة لرقابة البنك المركزي وفقاً لأحكام هذا القانون والتعليمات الصادرة بمقتضاه أن ترتبط بعقد عمل مع أي شخص كان موظفاً في البنك المركزي خلال مدة سنتين من تاريخ انتهاء خدمته فيه إلا بعد الحصول على موافقة خطية مسبقة من البنك المركزي.","title":"تعيين موظفي البنك السابقين","memo":"⭐ لا يجوز للجهة الخاضعة للرقابة التعاقد مع موظف سابق في البنك المركزي خلال سنتين من انتهاء خدمته إلا بموافقة خطية مسبقة من البنك","qs":[{"q":"لا يجوز لشركة التأمين أن ترتبط بعقد عمل مع موظف سابق في البنك المركزي دون موافقة خطية مسبقة من البنك خلال مدة:","o":["سنتين من تاريخ انتهاء خدمته","سنة من تاريخ انتهاء خدمته","ثلاث سنوات من تاريخ انتهاء خدمته","ستة أشهر من تاريخ انتهاء خدمته"],"a":0},{"q":"حالة عملية: انتهت خدمة موظف في البنك المركزي قبل سنة، ورغبت شركة وساطة تأمين بتعيينه، فإن ذلك:","o":["يتطلب موافقة خطية مسبقة من البنك المركزي","ممنوع منعاً مطلقاً","جائز دون قيد","يتطلب موافقة مجلس الوزراء"],"a":0}]},{"n":"103","chapter":"","notes":[],"source":"أ- تلتزم الجهات الخاضعة لرقابة البنك المركزي وفقاً لأحكام هذا القانون والتعليمات الصادرة بمقتضاه القائمة عند نفاذ أحكامه بتوفيق أوضاعها وفقاً لأحكام هذا القانون خلال المدة التي تحددها التعليمات الصادرة لهذه الغاية.\nب- تعتبر كل من شركات التأمين ومقدمي الخدمات التأمينية المرخصين قبل نفاذ أحكام هذا القانون مرخصين حكماً لدى البنك المركزي شريطة توفيق أوضاعهم وفق أحكام هذا القانون والأنظمة والتعليمات والقرارات الصادرة بمقتضاه خلال المدة التي يحددها البنك المركزي لهذه الغاية، وبخلاف ذلك يلغى ترخيص شركة التأمين أو مقدم الخدمة التأمينية.","title":"توفيق الأوضاع","memo":"⭐ تلتزم الجهات القائمة عند نفاذ القانون بتوفيق أوضاعها خلال المدة التي تحددها التعليمات\n⭐ شركات التأمين ومقدمو الخدمات المرخصون سابقاً مرخصون حكماً بشرط توفيق الأوضاع خلال المدة التي يحددها البنك المركزي، وإلا يلغى الترخيص","qs":[{"q":"تعتبر شركات التأمين المرخصة قبل نفاذ قانون تنظيم أعمال التأمين لسنة ٢٠٢١ لدى البنك المركزي:","o":["مرخصة حكماً شريطة توفيق أوضاعها خلال المدة التي يحددها البنك المركزي","ملزمة بتقديم طلب ترخيص جديد","مرخصة حكماً دون أي شرط","ملغى ترخيصها حكماً"],"a":0},{"q":"الأثر المترتب على عدم قيام مقدم خدمة تأمينية مرخص قبل نفاذ القانون بتوفيق أوضاعه خلال المدة المحددة:","o":["إلغاء ترخيصه","وقف ترخيصه لمدة سنة","فرض غرامة عليه فقط","تمديد المدة حكماً"],"a":0}]},{"n":"104","chapter":"","notes":[],"source":"أ- للجهات الخاضعة لأحكام هذا القانون أن تحتفظ للمدة المقررة قانوناً بصورة مصغرة (ميكرو فيلم أو غيره من التقنيات الحديثة) بدلا من أصل الدفاتر والسجلات والكشوفات والوثائق والمراسلات والبرقيات والإشعارات وغيرها من الأوراق المتصلة بأعمالها المالية وتكون لهذه الصور المصغرة حجية الأصل في الإثبات شريطة مراعاة أحكام قانون المعاملات المالية الإلكترونية.\nب- تعتبر جميع الأعمال التأمينية تجارية بحكم ماهيتها الذاتية بغض النظر عن صفة العميل المتعاقد أو المتعامل مع الجهات الخاضعة لأحكام هذا القانون سواء كان مدنياً أو تجاريا،ً وتسري عليها أحكام قانون التجارة.","title":"الصور المصغرة وتجارية الأعمال","memo":"⭐ يجوز الاحتفاظ بصور مصغرة (ميكروفيلم أو تقنيات حديثة) بدل الأصل، ولها حجية الأصل في الإثبات بشرط مراعاة قانون المعاملات المالية الإلكترونية\n⭐ جميع الأعمال التأمينية تجارية بحكم ماهيتها الذاتية بغض النظر عن صفة العميل مدنياً أو تجارياً، وتسري عليها أحكام قانون التجارة","qs":[{"q":"تكون للصور المصغرة (الميكروفيلم) التي تحتفظ بها الجهات الخاضعة للقانون بدلاً من الأصل:","o":["حجية الأصل في الإثبات","حجية مبدأ ثبوت بالكتابة فقط","حجية القرينة البسيطة","لا حجية لها في الإثبات"],"a":0},{"q":"تعتبر الأعمال التأمينية وفق المادة (١٠٤):","o":["تجارية بحكم ماهيتها الذاتية بغض النظر عن صفة العميل","تجارية إذا كان العميل تاجراً فقط","مدنية إذا كان العميل غير تاجر","مختلطة تخضع للقانون المدني"],"a":0},{"q":"يشترط لاعتبار الصور المصغرة ذات حجية الأصل في الإثبات مراعاة أحكام:","o":["قانون المعاملات المالية الإلكترونية","قانون البينات وحده","قانون الشركات","قانون التجارة"],"a":0}]},{"n":"105","chapter":"","notes":[],"source":"على الوزارات والدوائر الحكومية والمؤسسات العامة والشركات التي تساهم فيها الحكومة، والتي تستفيد من أعمال التأمين، تقديم أي بيانات أو معلومات تتعلق بترتيبات التأمين الحاصلة عليها أو التي ستحصل عليها، يطلبها البنك المركزي خلال المدة التي يحددها لذلك.","title":"بيانات التأمين الحكومي","memo":"⭐ على الوزارات والدوائر الحكومية والمؤسسات العامة والشركات التي تساهم فيها الحكومة تقديم بيانات ترتيبات التأمين التي يطلبها البنك المركزي خلال المدة التي يحددها","qs":[{"q":"تلتزم الشركات التي تساهم فيها الحكومة بتقديم البيانات المتعلقة بترتيبات التأمين الحاصلة عليها إلى:","o":["البنك المركزي","ديوان المحاسبة","وزارة المالية","الاتحاد الأردني لشركات التأمين"],"a":0},{"q":"تقدم الجهات الحكومية البيانات المتعلقة بترتيبات التأمين التي يطلبها البنك المركزي خلال:","o":["المدة التي يحددها البنك المركزي","ثلاثين يوماً من تاريخ الطلب","خمسة عشر يوماً من تاريخ الطلب","السنة المالية التالية"],"a":0}]},{"n":"106","chapter":"","notes":[],"source":"أ- يتم نشر القرارات المتعلقة بوقف الترخيص أو إلغائه أو إعادته أو القرارات المتعلقة باندماج الشركات أو تملكها أو إعادة هيكلتها أو تصفيتها أو فسخها في الجريدة الرسمية وفي صحيفتين يوميتين محليتين الأوسع انتشارا على نفقة شركة التأمين باستثناء نشر قرار تصفية شركة التأمين أو فسخها الذي يتم على نفقة البنك المركزي.\nب- للبنك المركزي أن ينشر بياناً عن أي مخالفة لأحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه بطريقة تتناسب مع طبيعة المخالفة وحجمها والإجراء المتخذ بخصوصها.","title":"نشر القرارات والمخالفات","memo":"⭐ تنشر قرارات وقف الترخيص أو إلغائه أو إعادته والاندماج والتملك وإعادة الهيكلة والتصفية والفسخ في الجريدة الرسمية وصحيفتين يوميتين محليتين على نفقة شركة التأمين\n⭐ استثناء: نشر قرار التصفية أو الفسخ على نفقة البنك المركزي\n⭐ للبنك نشر بيان عن أي مخالفة بطريقة تتناسب مع طبيعتها وحجمها","qs":[{"q":"يتم نشر قرار اندماج شركات التأمين في الجريدة الرسمية والصحف على نفقة:","o":["شركة التأمين","البنك المركزي","الشركة الدامجة والمندمجة مناصفة","الاتحاد الأردني لشركات التأمين"],"a":0},{"q":"يتم نشر قرار تصفية شركة التأمين أو فسخها على نفقة:","o":["البنك المركزي","شركة التأمين","المصفي","صندوق تعويض المؤمن لهم"],"a":0},{"q":"ينشر البنك المركزي بياناً عن أي مخالفة لأحكام القانون بطريقة تتناسب مع:","o":["طبيعة المخالفة وحجمها والإجراء المتخذ بخصوصها","رغبة الشركة المخالفة","قيمة الغرامة المفروضة فقط","حجم رأس مال الشركة"],"a":0}]},{"n":"107","chapter":"","notes":[],"source":"أ- لا يكون البنك المركزي أو أي من مسؤوليه أو موظفيه مسؤولا عن أي إجراء أو فعل أو امتناع ألحق ضررا بالغير إذا كان ذلك تنفيذاً لمهام ومسؤوليات البنك المركزي وفي حدود صلاحياته المنصوص عليها في هذا القانون و الأنظمة والتعليمات والقرارات الصادرة بمقتضاه، ويغطي البنك المركزي أي تكاليف خاصة بمتابعة ذلك لدى أي جهة حتى بعد انتهاء عمل المسؤول أو الموظف.\nب- لا تطبق أحكام الفقرة (أ) من هذه المادة إذا شكل الإجراء أو الفعل أو الامتناع إهمالا جسيماً أو كان بسوء نية.\nج- لا يكون المصفي مسؤولا عن أي شيكات يحررها تنفيذا لأعمال التصفية اذا ثبت لديه وجود رصيد كاف لتغطية تلك الشيكات بتاريخ تحريرها .","title":"حصانة البنك والمصفي","memo":"⭐ لا يسأل البنك المركزي أو مسؤولوه أو موظفوه عن الضرر إذا كان تنفيذاً لمهامه وفي حدود صلاحياته، ويغطي البنك تكاليف المتابعة حتى بعد انتهاء عمل الموظف\n⭐ لا تطبق الحصانة إذا شكل الفعل إهمالاً جسيماً أو كان بسوء نية\n⭐ لا يسأل المصفي عن الشيكات التي يحررها إذا ثبت لديه وجود رصيد كاف بتاريخ تحريرها","qs":[{"q":"لا تطبق حصانة موظفي البنك المركزي من المسؤولية عن أفعالهم إذا شكل الإجراء أو الفعل:","o":["إهمالاً جسيماً أو كان بسوء نية","خطأً يسيراً","ضرراً لشركة تأمين","مخالفة لتعليمات داخلية"],"a":0},{"q":"لا يكون المصفي مسؤولاً عن الشيكات التي يحررها تنفيذاً لأعمال التصفية إذا:","o":["ثبت لديه وجود رصيد كاف لتغطيتها بتاريخ تحريرها","وافق المجلس على تحريرها","كانت قيمتها لا تتجاوز ألف دينار","حررها لصالح البنك المركزي"],"a":0},{"q":"يغطي البنك المركزي التكاليف الخاصة بمتابعة الإجراءات المتخذة ضد موظفيه بسبب أعمالهم المشمولة بالحصانة:","o":["حتى بعد انتهاء عمل المسؤول أو الموظف","طوال مدة خدمة الموظف فقط","لمدة سنتين بعد انتهاء خدمة الموظف","إذا وافق مجلس الوزراء"],"a":0}]},{"n":"108","chapter":"","notes":[],"source":"تطبق أحكام قانون الشركات أو أي قانون آخر على أعمال التأمين والجهات الخاضعة لأحكام هذا القانون بالقدر الذي لا تتعارض فيها تلك الأحكام مع أحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه.","title":"تطبيق القوانين الأخرى","memo":"⭐ تطبق أحكام قانون الشركات أو أي قانون آخر على أعمال التأمين بالقدر الذي لا تتعارض فيه مع هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه","qs":[{"q":"تطبق أحكام قانون الشركات على أعمال التأمين والجهات الخاضعة لقانون تنظيم أعمال التأمين:","o":["بالقدر الذي لا تتعارض فيه مع أحكام قانون تنظيم أعمال التأمين وأنظمته وتعليماته","بشكل مطلق وتتقدم على أحكام قانون تنظيم أعمال التأمين","في حالة التصفية فقط","بموافقة البنك المركزي في كل حالة"],"a":0},{"q":"عند تعارض حكم في قانون الشركات مع حكم في قانون تنظيم أعمال التأمين بشأن شركة تأمين، فإن الحكم الواجب التطبيق:","o":["حكم قانون تنظيم أعمال التأمين","حكم قانون الشركات","الحكم الأحدث صدوراً","الحكم الذي تختاره الشركة"],"a":0}]},{"n":"109","chapter":"","notes":[],"source":"أ- يصدر مجلس الوزراء الأنظمة اللازمة لتنفيذ أحكام هذا القانون .\nب- يصدر البنك المركزي التعليمات اللازمة لتنفيذ أحكام هذا القانون ويصدر المحافظ القرارات اللازمة لتنفيذ أحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه.\nج- للمحافظ أن يفوض أياً من نائبيه أو كليهما أو أياً من موظفي البنك المركزي بأي من الصلاحيات المخولة له بمقتضى أحكام هذا القانون والأنظمة والتعليمات الصادرة بمقتضاه.","title":"الأنظمة والتعليمات والتفويض","memo":"⭐ مجلس الوزراء يصدر الأنظمة\n⭐ البنك المركزي يصدر التعليمات، والمحافظ يصدر القرارات\n⭐ للمحافظ تفويض أي من نائبيه أو كليهما أو أي من موظفي البنك بأي من صلاحياته","qs":[{"q":"الجهة المختصة بإصدار الأنظمة اللازمة لتنفيذ قانون تنظيم أعمال التأمين:","o":["مجلس الوزراء","البنك المركزي","المحافظ","مجلس إدارة البنك المركزي"],"a":0},{"q":"الجهة التي تصدر القرارات اللازمة لتنفيذ أحكام قانون تنظيم أعمال التأمين والأنظمة والتعليمات الصادرة بمقتضاه:","o":["المحافظ","مجلس الوزراء","وزير الصناعة والتجارة","الاتحاد الأردني لشركات التأمين"],"a":0},{"q":"للمحافظ أن يفوض صلاحياته بموجب قانون تنظيم أعمال التأمين إلى:","o":["أي من نائبيه أو كليهما أو أي من موظفي البنك المركزي","نائبه الأول فقط","مجلس إدارة الاتحاد الأردني لشركات التأمين","أي من مديري شركات التأمين"],"a":0}]},{"n":"110","chapter":"","notes":[],"source":"أ- يلغى قانون تنظيم أعمال التأمين رقم (٣٣) لسنة ١٩٩٩ وتعديلاته على أن تبقى الأنظمة والتعليمات والقرارات الصادرة بموجبه والإجراءات التي تمت بموجب أي منها سارية المفعول إلى أن تلغى أو يستبدل غيرها بها .\nب- اعتبارا من تاريخ نفاذ أحكام هذا القانون تنتقل للبنك المركزي أعمال تنظيم قطاع التأمين والرقابة عليه، ويستكمل البنك المركزي القيام بتنفيذ الأعمال والمهام و القرارات التي صدرت بموجب أحكام قانون تنظيم أعمال التأمين رقم (٣٣) لسنة ١٩٩٩ وتعديلاته والأنظمة والتعليمات الصادرة بمقتضاه.\nج- تستبدل بأي عبارة تدل على (هيئة تنظيم قطاع التأمين) أو (هيئة التأمين) أو (إدارة التأمين) عبارة (البنك المركزي)، كما تستبدل بأي عبارة تدل على (مجلس إدارة هيئة التأمين) عبارة (مجلس إدارة البنك المركزي)، وتستبدل بأي عبارة تدل على (مدير عام هيئة التأمين) عبارة (محافظ البنك المركزي)، وذلك أينما وردت هذه العبارات في الأنظمة والتعليمات والقرارات الصادرة بمقتضى قانون تنظيم أعمال التأمين رقم (٣٣) لسنة ١٩٩٩ وتعديلاته وفي أي تشريع آخر.\nد- على الرغم مما ورد في نظام موظفي البنك المركزي الأردني للمجلس اتخاذ الإجراءات والقرارات التي يراها مناسبة لتعيين موظفي إدارة التأمين في وزارة الصناعة والتجارة والتموين في البنك المركزي.","title":"الإلغاء وانتقال الرقابة","memo":"⭐ يلغى القانون رقم (٣٣) لسنة ١٩٩٩، وتبقى أنظمته وتعليماته وقراراته سارية حتى تلغى أو تستبدل\n⭐ تنتقل أعمال تنظيم قطاع التأمين والرقابة عليه للبنك المركزي\n⭐ تستبدل (هيئة التأمين/إدارة التأمين) بـ(البنك المركزي)، و(مجلس إدارة هيئة التأمين) بـ(مجلس إدارة البنك المركزي)، و(مدير عام هيئة التأمين) بـ(محافظ البنك المركزي)\n⭐ للمجلس تعيين موظفي إدارة التأمين في وزارة الصناعة والتجارة والتموين في البنك المركزي","qs":[{"q":"بعد إلغاء قانون تنظيم أعمال التأمين رقم (٣٣) لسنة ١٩٩٩، فإن الأنظمة والتعليمات الصادرة بموجبه:","o":["تبقى سارية المفعول إلى أن تلغى أو يستبدل غيرها بها","تلغى حكماً من تاريخ نفاذ القانون الجديد","تبقى سارية لمدة سنة واحدة فقط","تبقى سارية لمدة ستة أشهر فقط"],"a":0},{"q":"تستبدل بعبارة (مدير عام هيئة التأمين) أينما وردت في التشريعات عبارة:","o":["محافظ البنك المركزي","مجلس إدارة البنك المركزي","البنك المركزي","نائب محافظ البنك المركزي"],"a":0},{"q":"انتقلت أعمال تنظيم قطاع التأمين والرقابة عليه اعتباراً من تاريخ نفاذ القانون إلى:","o":["البنك المركزي","وزارة الصناعة والتجارة والتموين","هيئة الأوراق المالية","الاتحاد الأردني لشركات التأمين"],"a":0},{"q":"الجهة المختصة باتخاذ الإجراءات والقرارات لتعيين موظفي إدارة التأمين في وزارة الصناعة والتجارة والتموين في البنك المركزي:","o":["المجلس","مجلس الوزراء","وزير الصناعة والتجارة والتموين","ديوان الخدمة المدنية"],"a":0}]},{"n":"111","chapter":"","notes":[],"source":"رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون.","title":"تنفيذ القانون","memo":"⭐ رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون.","qs":[{"q":"المكلفون بتنفيذ أحكام قانون تنظيم أعمال التأمين:","o":["رئيس الوزراء والوزراء","محافظ البنك المركزي وحده","مجلس إدارة البنك المركزي","وزير الصناعة والتجارة والتموين وحده"],"a":0}]}]};
